func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		localSpent:    make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[candidateEdgeKey]liquidityBelief),
		blocked:       make(map[candidateEdgeKey]bool),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:  make(map[candidateEdgeKey]float64),
		lastRemaining: spec.Amount,
	}

	parts := uint32(1)
	switch {
	case spec.Amount > 1_000_000_000:
		parts = 6
	case spec.Amount > 250_000_000:
		parts = 4
	case spec.Amount > 50_000_000:
		parts = 2
	}
	if spec.MaxParts != 0 && parts > spec.MaxParts {
		parts = spec.MaxParts
	}
	if parts == 0 {
		parts = 1
	}
	r.baseShard = ceilDiv(
		spec.Amount, lnwire.MilliSatoshi(parts),
	)

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, ok := r.edgeByKey[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}
	return (a + b - 1) / b
}

func clampAmount(amt, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if amt < 0 {
		return 0
	}
	if amt > capacity {
		return capacity
	}
	return amt
}

func clampProbability(p float64) float64 {
	if p < minProbability {
		return minProbability
	}
	if p > maxProbability {
		return maxProbability
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-x/0.025)
	highMode := 0.48 / (1 + math.Exp(14*(x-0.78)))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) localAvailable(
	edge *candidateEdge) lnwire.MilliSatoshi {

	available := r.localBalances[edge.key.chanID]

	spent := r.localSpent[edge.key.chanID]
	if spent >= available {
		return 0
	}
	available -= spent

	reserved := r.reserved[edge.key]
	if reserved >= available {
		return 0
	}

	return available - reserved
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if amt > r.localAvailable(edge) {
			return minProbability
		}
		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	if belief.upperBad != 0 && amt >= belief.upperBad {
		return minProbability
	}
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.07, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(belief.estimate))/width,
	))

	return clampProbability(0.50*prior + 0.50*point)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)

		bestScore, ok := dist[item.node]
		if !ok || item.score > bestScore {
			continue
		}
		if required[item.node] != item.arriving {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) {
				continue
			}

			reserved := r.reserved[edge.key]
			if reserved >= edge.capacity ||
				amtOver > edge.capacity-reserved {

				continue
			}

			sending := amtOver
			fee := lnwire.MilliSatoshi(0)

			if edge.key.from == r.source {
				if sending > r.localAvailable(edge) {
					continue
				}
			} else {
				fee = edge.fee(amtOver)
				if fee < 0 ||
					amtOver > lnwire.MilliSatoshi(
						math.MaxInt64,
					)-fee {

					continue
				}
				sending += fee
			}

			probability := r.probability(edge, amtOver)
			risk := -math.Log(probability) * riskCostMsat
			score := item.score + float64(fee) + risk +
				r.routePenalty[edge.key] + 250

			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge

			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to

		if len(path) > len(r.edgeByKey) {
			return nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		fee := forwardingEdge.fee(amtOver[i+1])
		if fee < 0 ||
			amtOver[i+1] > lnwire.MilliSatoshi(
				math.MaxInt64,
			)-fee {

			return nil, errors.New("route amount overflow")
		}

		amtOver[i] = amtOver[i+1] + fee
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, ok := r.edgeByKey[key]

	return key, ok
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) routeProbability(rt *route.Route) float64 {
	probability := 1.0

	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			return minProbability
		}

		edge := r.edgeByKey[key]
		probability *= r.probability(
			edge, routeAmount(rt, i),
		)
	}

	if probability < math.SmallestNonzeroFloat64 {
		return math.SmallestNonzeroFloat64
	}
	return probability
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.reserved[key] += routeAmount(rt, i)
		}
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func appendCandidate(values []lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return values
	}

	seen[value] = true
	return append(values, value)
}

func (r *candidateRouter) shardCandidates(amt,
	minimum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 12)

	for _, numerator := range []int64{
		100, 84, 70, 58, 48, 40, 33, 27,
	} {
		value := lnwire.MilliSatoshi(
			int64(amt) * numerator / 100,
		)
		values = appendCandidate(
			values, seen, value, minimum, amt,
		)
	}

	values = appendCandidate(
		values, seen, r.baseShard, minimum, amt,
	)
	values = appendCandidate(
		values, seen, minimum, minimum, amt,
	)

	return values
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 ||
		inFlightHtlcs >= r.spec.MaxParts {

		return nil, errors.New("maximum parts in flight")
	}

	if amt < r.lastRemaining {
		r.consecutiveFailures = 0
	}
	r.lastRemaining = amt

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	minimum := ceilDiv(
		amt, lnwire.MilliSatoshi(partsLeft),
	)

	var (
		bestRoute   *route.Route
		bestUtility = math.Inf(-1)
		lastErr     error
	)

	for _, shard := range r.shardCandidates(amt, minimum) {
		rt, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		probability := r.routeProbability(rt)
		sizeRatio := float64(shard) / float64(minimum)
		fee := rt.TotalAmount - deliveredAmount(rt)

		utility := math.Log(probability) +
			1.35*math.Log(sizeRatio) -
			float64(fee)/2_000_000

		if shard == amt {
			utility += 0.08
		}
		if utility > bestUtility {
			bestUtility = utility
			bestRoute = rt
		}
	}

	if bestRoute == nil {
		if lastErr == nil {
			lastErr = errors.New("no route found")
		}
		return nil, lastErr
	}

	r.reserve(bestRoute)
	return bestRoute, nil
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	edge := r.edgeByKey[key]
	if edge == nil {
		return
	}

	belief.lowerOK = clampAmount(
		belief.lowerOK, edge.capacity,
	)
	belief.upperBad = clampAmount(
		belief.upperBad, edge.capacity,
	)
	belief.estimate = clampAmount(
		belief.estimate, edge.capacity,
	)

	if belief.upperBad != 0 &&
		belief.lowerOK >= belief.upperBad {

		belief.upperBad = 0
	}

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordProbeSuccess(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	estimate := amt
	if edge.capacity > amt {
		estimate += (edge.capacity - amt) * 3 / 4
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt * 30 / 100
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func subtractBound(value,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value == 0 || value <= amt {
		return 0
	}
	return value - amt
}

func addBound(value, amt,
	capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value > capacity-amt {
		return capacity
	}
	return value + amt
}

func (r *candidateRouter) recordSettlement(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil {
		return
	}

	if key.from == r.source {
		r.localSpent[key.chanID] += amt
		return
	}

	belief := r.beliefs[key]
	preEstimate := belief.estimate

	inferred := amt
	if edge.capacity > amt {
		inferred += (edge.capacity - amt) * 3 / 4
	}
	if inferred > preEstimate {
		preEstimate = inferred
	}

	belief.lowerOK = subtractBound(belief.lowerOK, amt)
	belief.upperBad = subtractBound(belief.upperBad, amt)
	belief.estimate = subtractBound(preEstimate, amt)
	r.saveBelief(key, belief)

	reverseKey := candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edgeByKey[reverseKey]
	if reverseEdge == nil || reverseKey.from == r.source {
		return
	}

	reverse := r.beliefs[reverseKey]
	reverse.lowerOK = addBound(
		reverse.lowerOK, amt, reverseEdge.capacity,
	)
	if reverse.lowerOK < amt {
		reverse.lowerOK = amt
	}
	reverse.estimate = addBound(
		reverse.estimate, amt, reverseEdge.capacity,
	)
	if reverse.estimate < reverse.lowerOK {
		reverse.estimate = reverse.lowerOK
	}
	if reverse.upperBad != 0 {
		reverse.upperBad = addBound(
			reverse.upperBad, amt, reverseEdge.capacity,
		)
	}

	r.saveBelief(reverseKey, reverse)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			r.recordSettlement(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.20
		}

		r.consecutiveFailures = 0
		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if ok {
				r.routePenalty[key] += riskCostMsat / 2
			}
		}

		r.consecutiveFailures++
		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.recordProbeSuccess(
				key, routeAmount(rt, i),
			)
			r.routePenalty[key] *= 0.75
		}
	}

	key, ok := r.routeEdge(rt, failIndex)
	if !ok {
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	default:
		r.recordFailure(
			key, routeAmount(rt, failIndex),
		)
		r.routePenalty[key] += riskCostMsat
	}

	r.consecutiveFailures++

	delivered := deliveredAmount(rt)
	retry := lnwire.MilliSatoshi(
		float64(delivered) * lowerRetryFactor,
	)
	if retry > 0 && retry < r.baseShard {
		r.baseShard = retry
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta  = uint32(40)
	riskCostMsat    = 260000.0
	minProbability  = 0.003
	maxProbability  = 0.995
	diversityCost   = 6000000.0
	minimumShard    = lnwire.MilliSatoshi(10_000)
	maxPlanCorridors = 8
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return true
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type pathCandidate struct {
	edges []*candidateEdge
	limit lnwire.MilliSatoshi
	score float64
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	localSpent    map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]liquidityBelief
	blocked       map[candidateEdgeKey]bool
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty  map[candidateEdgeKey]float64

	lastRemaining       lnwire.MilliSatoshi
	consecutiveFailures uint32
	retryHint           lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeByKey:      make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		localSpent:     make(map[uint64]lnwire.MilliSatoshi),
		beliefs:        make(map[candidateEdgeKey]liquidityBelief),
		blocked:        make(map[candidateEdgeKey]bool),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:   make(map[candidateEdgeKey]float64),
		lastRemaining:  spec.Amount,
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, ok := r.edgeByKey[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}
	return (a + b - 1) / b
}

func clampProbability(p float64) float64 {
	if p < minProbability {
		return minProbability
	}
	if p > maxProbability {
		return maxProbability
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-x/0.025)
	highMode := 0.48 / (1 + math.Exp(14*(x-0.78)))

	return clampProbability(0.005 + lowMode + highMode)
}

func subtractFloor(value, amount lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if amount >= value {
		return 0
	}
	return value - amount
}

func (r *candidateRouter) localAvailable(
	key candidateEdgeKey) lnwire.MilliSatoshi {

	available := r.localBalances[key.chanID]
	available = subtractFloor(available, r.localSpent[key.chanID])
	available = subtractFloor(available, r.reserved[key])

	return available
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if amt > r.localAvailable(edge.key) {
			return minProbability
		}
		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		return minProbability
	}
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.07, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(belief.estimate))/width,
	))

	return clampProbability(0.52*prior + 0.48*point)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findPath(amt lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]int) ([]*candidateEdge, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)

		bestScore, ok := dist[item.node]
		if !ok || item.score > bestScore {
			continue
		}
		if item.arriving != required[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) {
				continue
			}

			reserved := r.reserved[edge.key]
			if reserved >= edge.capacity ||
				amtOver > edge.capacity-reserved {

				continue
			}

			if edge.key.from == r.source &&
				amtOver > r.localAvailable(edge.key) {

				continue
			}

			belief := r.beliefs[edge.key]
			if belief.upperBad != 0 && amtOver >= belief.upperBad {
				continue
			}

			probability := r.probability(edge, amtOver)
			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			}

			risk := -math.Log(probability) * riskCostMsat
			capacityBonus := 0.0
			if edge.capacity > 0 {
				spare := float64(edge.capacity-amtOver) /
					float64(edge.capacity)
				capacityBonus = math.Min(spare, 1) * 18000
			}

			score := item.score + float64(fee) + risk +
				r.routePenalty[edge.key] + 250 -
				capacityBonus

			if count := diversity[edge.key]; count != 0 {
				score += float64(count) * diversityCost
			}

			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	score, ok := dist[r.source]
	if !ok {
		return nil, 0, errors.New("no route found")
	}

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, 0, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edgeByKey) {
			return nil, 0, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, 0, errors.New("empty route")
	}

	return path, score, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		if !edge.usable(amtOver[i]) {
			return nil, errors.New("path cannot carry amount")
		}

		forward := amt
		expiry := finalCltvDelta
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeFeasible(rt *route.Route) bool {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok || r.blocked[key] {
			return false
		}

		edge := r.edgeByKey[key]
		amt := routeAmount(rt, i)
		if edge == nil || !edge.usable(amt) {
			return false
		}

		if edge.key.from == r.source {
			if amt > r.localAvailable(key) {
				return false
			}
			continue
		}

		reserved := r.reserved[key]
		if reserved >= edge.capacity ||
			amt > edge.capacity-reserved {

			return false
		}

		belief := r.beliefs[key]
		if belief.upperBad != 0 && amt >= belief.upperBad {
			return false
		}
	}

	return true
}

func (r *candidateRouter) pathLimit(path []*candidateEdge,
	maxAmount lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if maxAmount <= 0 {
		return 0
	}

	low := lnwire.MilliSatoshi(0)
	high := maxAmount

	for low < high {
		mid := low + (high-low+1)/2
		rt, err := r.buildRoute(mid, path)
		if err == nil && r.routeFeasible(rt) {
			low = mid
		} else {
			high = mid - 1
		}
	}

	return low
}

func pathID(path []*candidateEdge) string {
	id := ""
	for _, edge := range path {
		id += fmt.Sprintf(
			"%d:%x:%x/", edge.key.chanID, edge.key.from,
			edge.key.to,
		)
	}
	return id
}

func (r *candidateRouter) probeAmount(remaining lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts == 0 {
		parts = 1
	}

	probe := ceilDiv(
		remaining, lnwire.MilliSatoshi(parts)*6,
	)
	if probe < 100_000 {
		probe = 100_000
	}
	if probe > 50_000_000 {
		probe = 50_000_000
	}
	if probe > remaining {
		probe = remaining
	}

	return probe
}

func (r *candidateRouter) planPaths(remaining lnwire.MilliSatoshi,
	parts uint32) []pathCandidate {

	count := int(parts)
	if count < 1 {
		count = 1
	}
	if count > maxPlanCorridors {
		count = maxPlanCorridors
	}

	probes := []lnwire.MilliSatoshi{
		r.probeAmount(remaining, parts),
	}
	if probes[0] > minimumShard {
		probes = append(probes, minimumShard)
	}

	diversity := make(map[candidateEdgeKey]int)
	seen := make(map[string]bool)
	plans := make([]pathCandidate, 0, count)

	for len(plans) < count {
		var (
			path  []*candidateEdge
			score float64
			err   error
		)

		for _, probe := range probes {
			path, score, err = r.findPath(probe, diversity)
			if err == nil {
				break
			}
		}
		if err != nil {
			break
		}

		id := pathID(path)
		for _, edge := range path {
			diversity[edge.key]++
		}

		if seen[id] {
			if len(plans) != 0 {
				break
			}
			continue
		}
		seen[id] = true

		limit := r.pathLimit(path, remaining)
		if limit < minimumShard && limit < remaining {
			continue
		}

		plans = append(plans, pathCandidate{
			edges: path,
			limit: limit,
			score: score,
		})
	}

	sort.SliceStable(plans, func(i, j int) bool {
		pi := r.pathReliability(plans[i])
		pj := r.pathReliability(plans[j])
		if math.Abs(pi-pj) > 0.03 {
			return pi > pj
		}
		if plans[i].limit != plans[j].limit {
			return plans[i].limit > plans[j].limit
		}
		return plans[i].score < plans[j].score
	})

	return plans
}

func (r *candidateRouter) pathReliability(
	plan pathCandidate) float64 {

	if plan.limit <= 0 {
		return 0
	}

	probe := plan.limit
	if probe > 50_000_000 {
		probe = 50_000_000
	}

	probability := 1.0
	for _, edge := range plan.edges {
		probability *= r.probability(edge, probe)
	}

	return probability
}

func plannedAllocation(remaining lnwire.MilliSatoshi,
	plans []pathCandidate) lnwire.MilliSatoshi {

	if len(plans) == 0 {
		return 0
	}
	if len(plans) == 1 {
		if plans[0].limit < remaining {
			return plans[0].limit
		}
		return remaining
	}

	total := lnwire.MilliSatoshi(0)
	other := lnwire.MilliSatoshi(0)
	for i, plan := range plans {
		total += plan.limit
		if i != 0 {
			other += plan.limit
		}
	}

	if total <= 0 {
		return 0
	}

	allocation := lnwire.MilliSatoshi(
		float64(remaining) *
			float64(plans[0].limit) / float64(total),
	)

	requiredNow := subtractFloor(remaining, other)
	if allocation < requiredNow {
		allocation = requiredNow
	}

	fairMinimum := ceilDiv(
		remaining, lnwire.MilliSatoshi(len(plans)),
	)
	if allocation < fairMinimum &&
		plans[0].limit >= fairMinimum {

		allocation = fairMinimum
	}

	if allocation > plans[0].limit {
		allocation = plans[0].limit
	}
	if allocation > remaining {
		allocation = remaining
	}
	if allocation < minimumShard && remaining >= minimumShard {
		if plans[0].limit >= minimumShard {
			allocation = minimumShard
		}
	}

	return allocation
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, ok := r.edgeByKey[key]
	return key, ok
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}
		r.reserved[key] += routeAmount(rt, i)
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts in flight")
	}

	if amt < r.lastRemaining {
		r.consecutiveFailures = 0
		r.retryHint = 0
	}
	r.lastRemaining = amt

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	if partsLeft == 0 {
		return nil, errors.New("maximum parts in flight")
	}

	plans := r.planPaths(amt, partsLeft)
	if len(plans) != 0 {
		shard := plannedAllocation(amt, plans)

		if r.retryHint != 0 && shard > r.retryHint {
			shard = r.retryHint
		}
		if shard > plans[0].limit {
			shard = plans[0].limit
		}
		if shard > amt {
			shard = amt
		}

		for shard > 0 {
			rt, err := r.buildRoute(shard, plans[0].edges)
			if err == nil && r.routeFeasible(rt) {
				r.reserve(rt)
				return rt, nil
			}

			next := shard * 2 / 3
			if next >= shard {
				next = shard - 1
			}
			if next < minimumShard && amt >= minimumShard {
				break
			}
			shard = next
		}
	}

	candidates := []lnwire.MilliSatoshi{
		amt,
		ceilDiv(amt, lnwire.MilliSatoshi(partsLeft)),
		amt * 2 / 3,
		amt / 2,
		amt / 3,
		minimumShard,
	}
	if r.retryHint != 0 {
		candidates = append(
			[]lnwire.MilliSatoshi{r.retryHint}, candidates...,
		)
	}

	tried := make(map[lnwire.MilliSatoshi]bool)
	var lastErr error
	for _, shard := range candidates {
		if shard <= 0 || shard > amt || tried[shard] {
			continue
		}
		tried[shard] = true

		path, _, err := r.findPath(
			shard, make(map[candidateEdgeKey]int),
		)
		if err != nil {
			lastErr = err
			continue
		}

		rt, err := r.buildRoute(shard, path)
		if err != nil || !r.routeFeasible(rt) {
			if err != nil {
				lastErr = err
			}
			continue
		}

		r.reserve(rt)
		return rt, nil
	}

	if lastErr == nil {
		lastErr = errors.New("no route found")
	}
	return nil, lastErr
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordPass(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	inferred := amt
	remaining := edge.capacity - amt
	if remaining > 0 {
		inferred += remaining * 3 / 4
	}
	if inferred > belief.estimate {
		belief.estimate = inferred
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordSettlement(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil {
		return
	}

	if key.from == r.source {
		r.localSpent[key.chanID] += amt
		return
	}

	belief := r.beliefs[key]

	preEstimate := belief.estimate
	if preEstimate < amt {
		preEstimate = amt
	}
	inferred := amt
	if edge.capacity > amt {
		inferred += (edge.capacity - amt) * 3 / 4
	}
	if inferred > preEstimate {
		preEstimate = inferred
	}

	belief.estimate = subtractFloor(preEstimate, amt)
	belief.lowerOK = subtractFloor(belief.lowerOK, amt)
	if belief.upperBad != 0 {
		belief.upperBad = subtractFloor(belief.upperBad, amt)
		if belief.upperBad == 0 {
			belief.upperBad = 1
		}
	}

	likelyRemaining := lnwire.MilliSatoshi(0)
	if edge.capacity > amt {
		likelyRemaining = (edge.capacity - amt) * 2 / 3
	}
	if belief.estimate < likelyRemaining {
		belief.estimate = likelyRemaining
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt * 30 / 100
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes != source {
			continue
		}

		outgoing := i + 1
		if outgoing < len(rt.Hops) {
			return outgoing
		}
		return -1
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			r.recordSettlement(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.20
		}

		r.consecutiveFailures = 0
		r.retryHint = 0
		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if ok {
				r.routePenalty[key] += riskCostMsat * 0.45
			}
		}

		r.consecutiveFailures++
		delivered := deliveredAmount(rt)
		if delivered > minimumShard {
			r.retryHint = delivered * 2 / 3
		}
		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.recordPass(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.75
		}
	}

	key, ok := r.routeEdge(rt, failIndex)
	if !ok {
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	case lnwire.CodeTemporaryChannelFailure:
		r.recordFailure(key, routeAmount(rt, failIndex))
		r.routePenalty[key] += riskCostMsat * 1.4

	default:
		r.routePenalty[key] += riskCostMsat * 0.75
	}

	r.consecutiveFailures++

	delivered := deliveredAmount(rt)
	if delivered > minimumShard {
		factor := lnwire.MilliSatoshi(2)
		divisor := lnwire.MilliSatoshi(3)
		if r.consecutiveFailures >= 3 {
			factor = 1
			divisor = 2
		}

		retry := delivered * factor / divisor
		if retry < minimumShard {
			retry = minimumShard
		}
		r.retryHint = retry
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta   = uint32(40)
	riskCostMsat     = 250000.0
	minProbability   = 0.003
	maxProbability   = 0.995
	lowerRetryFactor = 0.68
	minShardMsat     = lnwire.MilliSatoshi(10_000)
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	localSpent    map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]liquidityBelief
	blocked       map[candidateEdgeKey]bool
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty  map[candidateEdgeKey]float64

	lastRemaining       lnwire.MilliSatoshi
	retryCap            lnwire.MilliSatoshi
	consecutiveFailures uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeByKey:      make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		localSpent:     make(map[uint64]lnwire.MilliSatoshi),
		beliefs:        make(map[candidateEdgeKey]liquidityBelief),
		blocked:        make(map[candidateEdgeKey]bool),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:   make(map[candidateEdgeKey]float64),
		lastRemaining:  spec.Amount,
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, ok := r.edgeByKey[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}
	return (a + b - 1) / b
}

func minMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a < b {
		return a
	}
	return b
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}
	return b
}

func clampProbability(p float64) float64 {
	if p < minProbability {
		return minProbability
	}
	if p > maxProbability {
		return maxProbability
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-x/0.025)
	highMode := 0.48 / (1 + math.Exp(14*(x-0.78)))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) localAvailable(
	edge *candidateEdge) lnwire.MilliSatoshi {

	available := r.localBalances[edge.key.chanID]
	spent := r.localSpent[edge.key.chanID]
	if spent >= available {
		return 0
	}
	available -= spent

	reserved := r.reserved[edge.key]
	if reserved >= available {
		return 0
	}
	return available - reserved
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if amt > r.localAvailable(edge) {
			return minProbability
		}
		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		return minProbability
	}
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.07, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(belief.estimate))/width,
	))

	weight := 0.48
	if belief.lowerOK != 0 || belief.upperBad != 0 {
		weight = 0.64
	}

	return clampProbability((1-weight)*prior + weight*point)
}

func (r *candidateRouter) edgeSafeLimit(
	edge *candidateEdge) lnwire.MilliSatoshi {

	if r.blocked[edge.key] {
		return 0
	}

	limit := edge.capacity
	if edge.maxHTLC != 0 && edge.maxHTLC < limit {
		limit = edge.maxHTLC
	}

	if edge.key.from == r.source {
		limit = minMSat(limit, r.localAvailable(edge))
		if limit < edge.minHTLC {
			return 0
		}
		return limit
	}

	reserved := r.reserved[edge.key]
	if reserved >= limit {
		return 0
	}
	limit -= reserved

	belief := r.beliefs[edge.key]
	safe := limit * 72 / 100

	if belief.estimate != 0 {
		safe = belief.estimate * 90 / 100
	}
	if belief.upperBad != 0 {
		retry := belief.upperBad * 68 / 100
		safe = maxMSat(safe, retry)
	}
	if belief.lowerOK != 0 {
		safe = maxMSat(safe, belief.lowerOK)
	}

	if belief.upperBad != 0 && safe >= belief.upperBad {
		safe = belief.upperBad - 1
	}
	if safe > limit {
		safe = limit
	}
	if safe < edge.minHTLC {
		return 0
	}

	return safe
}

type widestItem struct {
	node  route.Vertex
	width lnwire.MilliSatoshi
}

type widestQueue []*widestItem

func (q widestQueue) Len() int {
	return len(q)
}

func (q widestQueue) Less(i, j int) bool {
	return q[i].width > q[j].width
}

func (q widestQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *widestQueue) Push(value any) {
	*q = append(*q, value.(*widestItem))
}

func (q *widestQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) widestAmount(
	maximum lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if maximum <= 0 {
		return 0
	}

	width := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: maximum,
	}
	pq := &widestQueue{}
	heap.Push(pq, &widestItem{
		node:  r.spec.Target,
		width: maximum,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*widestItem)
		if item.width != width[item.node] {
			continue
		}
		if item.node == r.source {
			return item.width
		}

		for _, edge := range r.incomingEdges[item.node] {
			limit := r.edgeSafeLimit(edge)
			if limit == 0 {
				continue
			}

			candidate := minMSat(item.width, limit)
			if candidate <= width[edge.key.from] {
				continue
			}

			width[edge.key.from] = candidate
			heap.Push(pq, &widestItem{
				node:  edge.key.from,
				width: candidate,
			})
		}
	}

	return 0
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		bestScore, ok := dist[item.node]
		if !ok || item.score > bestScore {
			continue
		}
		if item.arriving != required[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) {
				continue
			}

			reserved := r.reserved[edge.key]
			if edge.key.from != r.source {
				if reserved >= edge.capacity ||
					amtOver > edge.capacity-reserved {

					continue
				}
			}

			probability := r.probability(edge, amtOver)
			belief := r.beliefs[edge.key]
			if belief.upperBad != 0 &&
				amtOver >= belief.upperBad {

				continue
			}

			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			} else if sending > r.localAvailable(edge) {
				continue
			}

			risk := -math.Log(probability) * riskCostMsat
			score := item.score + float64(fee) + risk +
				r.routePenalty[edge.key] + 200

			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edgeByKey) {
			return nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, ok := r.edgeByKey[key]
	return key, ok
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.reserved[key] += routeAmount(rt, i)
		}
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts in flight")
	}

	if amt < r.lastRemaining {
		r.consecutiveFailures = 0
		r.retryCap = 0
	}
	r.lastRemaining = amt

	for key, penalty := range r.routePenalty {
		penalty *= 0.90
		if penalty < 1 {
			delete(r.routePenalty, key)
		} else {
			r.routePenalty[key] = penalty
		}
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	if partsLeft == 0 {
		partsLeft = 1
	}

	desired := ceilDiv(
		amt, lnwire.MilliSatoshi(partsLeft),
	)
	if partsLeft == 1 {
		desired = amt
	}

	widest := r.widestAmount(amt)
	shard := desired
	if widest != 0 {
		safe := widest * 92 / 100
		if safe < minShardMsat {
			safe = minMSat(widest, minShardMsat)
		}
		shard = minMSat(shard, safe)
	}

	if r.retryCap != 0 && shard > r.retryCap {
		shard = r.retryCap
	}
	if shard > amt {
		shard = amt
	}

	minShard := minShardMsat
	if amt < minShard {
		minShard = amt
	}
	if shard < minShard {
		shard = minShard
	}

	var lastErr error
	tried := make(map[lnwire.MilliSatoshi]bool)

	for shard >= minShard {
		if !tried[shard] {
			tried[shard] = true
			rt, err := r.findRoute(shard)
			if err == nil {
				r.reserve(rt)
				return rt, nil
			}
			lastErr = err
		}

		if shard == minShard {
			break
		}

		nextShard := lnwire.MilliSatoshi(
			float64(shard) * lowerRetryFactor,
		)
		if nextShard >= shard {
			nextShard = shard - 1
		}
		if nextShard < minShard {
			nextShard = minShard
		}
		shard = nextShard
	}

	if !tried[amt] && partsLeft == 1 {
		rt, err := r.findRoute(amt)
		if err == nil {
			r.reserve(rt)
			return rt, nil
		}
		lastErr = err
	}

	if lastErr == nil {
		lastErr = errors.New("no route found")
	}
	return nil, lastErr
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	estimate := amt
	if edge.capacity > amt {
		estimate += (edge.capacity - amt) * 3 / 4
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordSettlement(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil {
		return
	}

	if key.from == r.source {
		r.localSpent[key.chanID] += amt
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}

	lower := maxMSat(belief.lowerOK, amt)
	if lower > amt {
		belief.lowerOK = lower - amt
	} else {
		belief.lowerOK = 0
	}

	inferred := amt
	if edge.capacity > amt {
		inferred += (edge.capacity - amt) * 3 / 4
	}
	estimate := maxMSat(belief.estimate, inferred)
	if estimate > amt {
		belief.estimate = estimate - amt
	} else {
		belief.estimate = 0
	}

	if belief.upperBad != 0 {
		if belief.upperBad > amt {
			belief.upperBad -= amt
		} else {
			belief.upperBad = 0
		}
	}

	if belief.estimate > edge.capacity {
		belief.estimate = edge.capacity
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt * 35 / 100
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			r.recordSettlement(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.20
		}
		r.consecutiveFailures = 0
		r.retryCap = 0
		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if ok {
				r.routePenalty[key] += riskCostMsat / 3
			}
		}

		r.consecutiveFailures++
		delivered := deliveredAmount(rt)
		retry := delivered * 3 / 4
		if retry > 0 &&
			(r.retryCap == 0 || retry < r.retryCap) {

			r.retryCap = retry
		}
		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.recordSuccess(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.50
		}
	}

	key, ok := r.routeEdge(rt, failIndex)
	if !ok {
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	default:
		failedAmt := routeAmount(rt, failIndex)
		r.recordFailure(key, failedAmt)
		r.routePenalty[key] += riskCostMsat

		delivered := deliveredAmount(rt)
		retry := lnwire.MilliSatoshi(
			float64(delivered) * lowerRetryFactor,
		)
		if retry > 0 &&
			(r.retryCap == 0 || retry < r.retryCap) {

			r.retryCap = retry
		}
	}

	r.consecutiveFailures++
	if r.consecutiveFailures >= 3 {
		for key, penalty := range r.routePenalty {
			r.routePenalty[key] = penalty * 0.72
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta   = uint32(40)
	riskCostMsat     = 320000.0
	minProbability   = 0.003
	maxProbability   = 0.995
	diversityCost    = 2200000.0
	minimumShard     = lnwire.MilliSatoshi(10_000)
	maxPlanCorridors = 8
	maxPathHops       = 24
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type pathCandidate struct {
	edges       []*candidateEdge
	hardLimit   lnwire.MilliSatoshi
	likelyLimit lnwire.MilliSatoshi
	score       float64
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	localSpent    map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]liquidityBelief
	blocked       map[candidateEdgeKey]bool
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty  map[candidateEdgeKey]float64

	lastRemaining       lnwire.MilliSatoshi
	consecutiveFailures uint32
	retryHint           lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeByKey:      make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		localSpent:     make(map[uint64]lnwire.MilliSatoshi),
		beliefs:        make(map[candidateEdgeKey]liquidityBelief),
		blocked:        make(map[candidateEdgeKey]bool),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:   make(map[candidateEdgeKey]float64),
		lastRemaining:  spec.Amount,
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, ok := r.edgeByKey[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}

	return (a + b - 1) / b
}

func subtractFloor(value, amount lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if amount >= value {
		return 0
	}

	return value - amount
}

func clampProbability(p float64) float64 {
	if p < minProbability {
		return minProbability
	}
	if p > maxProbability {
		return maxProbability
	}

	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.51 * math.Exp(-x/0.026)
	highMode := 0.475 / (1 + math.Exp(15*(x-0.79)))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) localAvailable(
	key candidateEdgeKey) lnwire.MilliSatoshi {

	available := r.localBalances[key.chanID]
	available = subtractFloor(available, r.localSpent[key.chanID])
	available = subtractFloor(available, r.reserved[key])

	return available
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if amt > r.localAvailable(edge.key) {
			return minProbability
		}

		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		return minProbability
	}
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.055, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(belief.estimate))/width,
	))

	return clampProbability(0.43*prior + 0.57*point)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
	hops     int
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	if q[i].score == q[j].score {
		return q[i].hops < q[j].hops
	}

	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]

	return item
}

func (r *candidateRouter) edgeCost(edge *candidateEdge,
	amt lnwire.MilliSatoshi, fee lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]int) float64 {

	p := r.probability(edge, amt)
	cost := float64(fee) - math.Log(p)*riskCostMsat + 500

	if edge.capacity > 0 {
		load := float64(amt) / float64(edge.capacity)
		cost += 22000 * load * load
	}

	cost += r.routePenalty[edge.key]
	if count := diversity[edge.key]; count != 0 {
		cost += float64(count) * diversityCost
	}

	if cost < 1 {
		return 1
	}

	return cost
}

func (r *candidateRouter) findPath(amt lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]int) ([]*candidateEdge, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	hopCount := map[route.Vertex]int{
		r.spec.Target: 0,
	}
	next := make(map[route.Vertex]*candidateEdge)
	settled := make(map[route.Vertex]bool)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)

		bestScore, ok := dist[item.node]
		if !ok || item.score != bestScore {
			continue
		}
		if item.arriving != required[item.node] {
			continue
		}
		if settled[item.node] {
			continue
		}
		settled[item.node] = true

		if item.node == r.source {
			break
		}
		if item.hops >= maxPathHops {
			continue
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}
			if edge.key.from == r.spec.Target {
				continue
			}
			if settled[edge.key.from] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) {
				continue
			}

			reserved := r.reserved[edge.key]
			if reserved >= edge.capacity ||
				amtOver > edge.capacity-reserved {

				continue
			}

			if edge.key.from == r.source &&
				amtOver > r.localAvailable(edge.key) {

				continue
			}

			belief := r.beliefs[edge.key]
			if belief.upperBad != 0 && amtOver >= belief.upperBad {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			sending := amtOver
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			}

			score := item.score + r.edgeCost(
				edge, amtOver, fee, diversity,
			)
			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			hopCount[edge.key.from] = item.hops + 1
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
				hops:     item.hops + 1,
			})
		}
	}

	score, ok := dist[r.source]
	if !ok {
		return nil, 0, errors.New("no route found")
	}

	visited := make(map[route.Vertex]bool)
	path := make([]*candidateEdge, 0, hopCount[r.source])
	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, 0, errors.New("route contains a cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, 0, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > maxPathHops {
			return nil, 0, errors.New("route exceeds hop limit")
		}
	}

	if len(path) == 0 {
		return nil, 0, errors.New("empty route")
	}

	return path, score, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		if !edge.usable(amtOver[i]) {
			return nil, errors.New("path cannot carry amount")
		}

		forward := amt
		expiry := finalCltvDelta
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, ok := r.edgeByKey[key]

	return key, ok
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}

	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) routeFeasible(rt *route.Route) bool {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok || r.blocked[key] {
			return false
		}

		edge := r.edgeByKey[key]
		amt := routeAmount(rt, i)
		if edge == nil || !edge.usable(amt) {
			return false
		}

		if edge.key.from == r.source {
			if amt > r.localAvailable(key) {
				return false
			}
			continue
		}

		reserved := r.reserved[key]
		if reserved >= edge.capacity ||
			amt > edge.capacity-reserved {

			return false
		}

		belief := r.beliefs[key]
		if belief.upperBad != 0 && amt >= belief.upperBad {
			return false
		}
	}

	return true
}

func (r *candidateRouter) credibleAmount(
	edge *candidateEdge) lnwire.MilliSatoshi {

	if edge.key.from == r.source {
		return r.localAvailable(edge.key)
	}

	limit := edge.capacity
	if edge.maxHTLC != 0 && edge.maxHTLC < limit {
		limit = edge.maxHTLC
	}

	reserved := r.reserved[edge.key]
	limit = subtractFloor(limit, reserved)

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && belief.upperBad-1 < limit {
		limit = belief.upperBad - 1
	}

	if belief.estimate != 0 {
		likely := belief.estimate * 92 / 100
		if belief.lowerOK > likely {
			likely = belief.lowerOK
		}
		if likely < limit {
			limit = likely
		}

		return limit
	}

	priorLimit := edge.capacity * 72 / 100
	priorLimit = subtractFloor(priorLimit, reserved)
	if priorLimit < limit {
		limit = priorLimit
	}

	return limit
}

func (r *candidateRouter) routeLikely(rt *route.Route) bool {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			return false
		}

		edge := r.edgeByKey[key]
		if edge == nil || routeAmount(rt, i) > r.credibleAmount(edge) {
			return false
		}
	}

	return true
}

func (r *candidateRouter) amountLimit(path []*candidateEdge,
	maxAmount lnwire.MilliSatoshi, likely bool) lnwire.MilliSatoshi {

	if maxAmount <= 0 {
		return 0
	}

	low := lnwire.MilliSatoshi(0)
	high := maxAmount

	for low < high {
		mid := low + (high-low+1)/2
		rt, err := r.buildRoute(mid, path)
		ok := err == nil && r.routeFeasible(rt)
		if ok && likely {
			ok = r.routeLikely(rt)
		}

		if ok {
			low = mid
		} else {
			high = mid - 1
		}
	}

	return low
}

func pathID(path []*candidateEdge) string {
	id := ""
	for _, edge := range path {
		id += fmt.Sprintf(
			"%d:%x:%x/", edge.key.chanID, edge.key.from,
			edge.key.to,
		)
	}

	return id
}

func (r *candidateRouter) pathProbability(path []*candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	rt, err := r.buildRoute(amt, path)
	if err != nil {
		return 0
	}

	probability := 1.0
	for i, edge := range path {
		probability *= r.probability(edge, routeAmount(rt, i))
	}

	return probability
}

func (r *candidateRouter) discoveryProbe(remaining
	lnwire.MilliSatoshi, parts uint32) lnwire.MilliSatoshi {

	if parts == 0 {
		parts = 1
	}

	probe := ceilDiv(
		remaining, lnwire.MilliSatoshi(parts)*8,
	)
	if probe < 100_000 {
		probe = 100_000
	}
	if probe > 25_000_000 {
		probe = 25_000_000
	}
	if probe > remaining {
		probe = remaining
	}

	return probe
}

func (r *candidateRouter) planPaths(remaining lnwire.MilliSatoshi,
	parts uint32) []pathCandidate {

	count := int(parts)
	if count < 1 {
		count = 1
	}
	if count > maxPlanCorridors {
		count = maxPlanCorridors
	}

	probes := []lnwire.MilliSatoshi{
		r.discoveryProbe(remaining, parts),
		100_000,
		minimumShard,
	}

	diversity := make(map[candidateEdgeKey]int)
	seen := make(map[string]bool)
	plans := make([]pathCandidate, 0, count)
	maxSearches := count * 5

	for search := 0; search < maxSearches &&
		len(plans) < count; search++ {

		var (
			path  []*candidateEdge
			score float64
			err   error
		)

		for _, probe := range probes {
			if probe <= 0 || probe > remaining {
				continue
			}

			path, score, err = r.findPath(probe, diversity)
			if err == nil {
				break
			}
		}
		if err != nil {
			break
		}

		id := pathID(path)
		for _, edge := range path {
			diversity[edge.key]++
		}
		if seen[id] {
			continue
		}
		seen[id] = true

		hardLimit := r.amountLimit(path, remaining, false)
		if hardLimit <= 0 {
			continue
		}

		likelyLimit := r.amountLimit(path, hardLimit, true)
		if likelyLimit < minimumShard {
			likelyLimit = hardLimit
			if likelyLimit > 1_000_000 {
				likelyLimit = 1_000_000
			}
		}

		plans = append(plans, pathCandidate{
			edges:       path,
			hardLimit:   hardLimit,
			likelyLimit: likelyLimit,
			score:       score,
		})
	}

	sort.SliceStable(plans, func(i, j int) bool {
		pi := r.pathProbability(
			plans[i].edges, plans[i].likelyLimit,
		)
		pj := r.pathProbability(
			plans[j].edges, plans[j].likelyLimit,
		)
		if math.Abs(pi-pj) > 0.04 {
			return pi > pj
		}
		if plans[i].likelyLimit != plans[j].likelyLimit {
			return plans[i].likelyLimit > plans[j].likelyLimit
		}

		return plans[i].score < plans[j].score
	})

	return plans
}

func sumPlanLimits(plans []pathCandidate, start, count int,
	likely bool) lnwire.MilliSatoshi {

	total := lnwire.MilliSatoshi(0)
	end := start + count
	if end > len(plans) {
		end = len(plans)
	}

	for i := start; i < end; i++ {
		if likely {
			total += plans[i].likelyLimit
		} else {
			total += plans[i].hardLimit
		}
	}

	return total
}

func plannedAllocation(remaining lnwire.MilliSatoshi,
	parts uint32, plans []pathCandidate) lnwire.MilliSatoshi {

	if len(plans) == 0 || parts == 0 {
		return 0
	}

	usable := len(plans)
	if usable > int(parts) {
		usable = int(parts)
	}

	firstLimit := plans[0].likelyLimit
	totalLikely := sumPlanLimits(plans, 0, usable, true)
	if totalLikely < remaining {
		firstLimit = plans[0].hardLimit
	}

	otherCapacity := sumPlanLimits(plans, 1, usable-1, true)
	if totalLikely < remaining {
		otherCapacity = sumPlanLimits(
			plans, 1, usable-1, false,
		)
	}

	requiredNow := subtractFloor(remaining, otherCapacity)
	allocation := requiredNow

	totalWeight := totalLikely
	if totalWeight < remaining {
		totalWeight = sumPlanLimits(plans, 0, usable, false)
	}
	if totalWeight > 0 {
		weighted := lnwire.MilliSatoshi(
			float64(remaining) *
				float64(firstLimit) / float64(totalWeight),
		)
		if weighted > allocation {
			allocation = weighted
		}
	}

	if parts == 1 {
		allocation = remaining
	}
	if allocation > firstLimit {
		allocation = firstLimit
	}
	if allocation > plans[0].hardLimit {
		allocation = plans[0].hardLimit
	}
	if allocation > remaining {
		allocation = remaining
	}
	if allocation < minimumShard && remaining >= minimumShard &&
		plans[0].hardLimit >= minimumShard {

		allocation = minimumShard
	}

	return allocation
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.reserved[key] += routeAmount(rt, i)
		}
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func (r *candidateRouter) tryRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	rt, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}
	if !r.routeFeasible(rt) {
		return nil, errors.New("route is not feasible")
	}

	r.reserve(rt)

	return rt, nil
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 {
		return nil, errors.New("payment permits no parts")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts in flight")
	}

	if amt < r.lastRemaining {
		r.consecutiveFailures = 0
		r.retryHint = 0
	}
	r.lastRemaining = amt

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	plans := r.planPaths(amt, partsLeft)

	if len(plans) != 0 {
		shard := plannedAllocation(amt, partsLeft, plans)
		if r.retryHint != 0 && shard > r.retryHint {
			shard = r.retryHint
		}
		if partsLeft == 1 {
			shard = amt
		}

		for _, plan := range plans {
			tryAmt := shard
			if tryAmt > plan.hardLimit {
				tryAmt = plan.hardLimit
			}
			if tryAmt <= 0 {
				continue
			}

			rt, err := r.tryRoute(tryAmt, plan.edges)
			if err == nil {
				return rt, nil
			}
		}
	}

	candidates := []lnwire.MilliSatoshi{
		amt,
		ceilDiv(amt, lnwire.MilliSatoshi(partsLeft)),
		amt * 3 / 4,
		amt * 2 / 3,
		amt / 2,
		amt / 3,
		amt / 4,
		minimumShard,
	}
	if r.retryHint != 0 {
		candidates = append(
			[]lnwire.MilliSatoshi{r.retryHint}, candidates...,
		)
	}

	tried := make(map[lnwire.MilliSatoshi]bool)
	var lastErr error
	for _, shard := range candidates {
		if shard <= 0 || shard > amt || tried[shard] {
			continue
		}
		if partsLeft == 1 && shard != amt {
			continue
		}
		tried[shard] = true

		path, _, err := r.findPath(
			shard, make(map[candidateEdgeKey]int),
		)
		if err != nil {
			lastErr = err
			continue
		}

		rt, err := r.tryRoute(shard, path)
		if err == nil {
			return rt, nil
		}
		lastErr = err
	}

	if lastErr == nil {
		lastErr = errors.New("no route found")
	}

	return nil, lastErr
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordPass(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	inferred := amt
	if edge.capacity > amt {
		inferred += (edge.capacity - amt) * 4 / 5
	}
	if inferred > belief.estimate {
		belief.estimate = inferred
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordSettlement(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil {
		return
	}

	if key.from == r.source {
		r.localSpent[key.chanID] += amt
		return
	}

	belief := r.beliefs[key]
	preEstimate := belief.estimate
	if preEstimate < amt {
		preEstimate = amt
	}

	inferred := amt
	if edge.capacity > amt {
		inferred += (edge.capacity - amt) * 4 / 5
	}
	if inferred > preEstimate {
		preEstimate = inferred
	}

	belief.estimate = subtractFloor(preEstimate, amt)
	belief.lowerOK = subtractFloor(belief.lowerOK, amt)
	if belief.upperBad != 0 {
		belief.upperBad = subtractFloor(belief.upperBad, amt)
		if belief.upperBad == 0 {
			belief.upperBad = 1
		}
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt / 4
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes != source {
			continue
		}

		outgoing := i + 1
		if outgoing < len(rt.Hops) {
			return outgoing
		}

		return -1
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			r.recordSettlement(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.15
		}

		r.consecutiveFailures = 0
		r.retryHint = 0

		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if ok {
				r.routePenalty[key] += riskCostMsat * 0.65
			}
		}

		r.consecutiveFailures++
		delivered := deliveredAmount(rt)
		if delivered > minimumShard {
			r.retryHint = delivered / 2
			if r.retryHint < minimumShard {
				r.retryHint = minimumShard
			}
		}

		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.recordPass(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.65
		}
	}

	key, ok := r.routeEdge(rt, failIndex)
	if !ok {
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	case lnwire.CodeTemporaryChannelFailure:
		r.recordFailure(key, routeAmount(rt, failIndex))
		r.routePenalty[key] += riskCostMsat * 1.8

	default:
		r.routePenalty[key] += riskCostMsat
	}

	r.consecutiveFailures++

	delivered := deliveredAmount(rt)
	if delivered > minimumShard {
		retry := delivered * 3 / 5
		if r.consecutiveFailures >= 2 {
			retry = delivered / 2
		}
		if r.consecutiveFailures >= 4 {
			retry = delivered / 3
		}
		if retry < minimumShard {
			retry = minimumShard
		}
		r.retryHint = retry
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
	samples  uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved     map[edgeKey]lnwire.MilliSatoshi
	edgeFailures map[edgeKey]uint32
	broken       map[edgeKey]bool

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:  make(map[edgeKey]uint32),
		broken:        make(map[edgeKey]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)

	// The first term models the small depleted-side tail. The second
	// models the large liquid-side mode and its cliff near capacity.
	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}
		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := float64(edge.capacity) * 0.10
	if scale < 1 {
		scale = 1
	}
	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))

	confidence := math.Min(0.78, 0.22*float64(belief.samples))
	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{r.spec.Target: 0}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: deliver,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(item.amt) {
				continue
			}

			totalLiquidity := item.amt + r.reserved[edge.key]
			if totalLiquidity > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				totalLiquidity >
					r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			// Reliability dominates. A million-msat risk scale still
			// permits fees to break ties between similarly reliable paths.
			step := -math.Log(probability) +
				float64(edgeFee)/2_000_000 +
				0.015 +
				0.32*float64(r.edgeFailures[edge.key])
			candidate := item.score + step

			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(r.edges[key], amounts[i])
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}
		path = append(path, edge)
		node = edge.key.to

		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 14)

	addCandidate(&values, seen, amt, minimum, amt)
	addCandidate(&values, seen, amt*3/4, minimum, amt)
	addCandidate(&values, seen, amt*2/3, minimum, amt)
	addCandidate(&values, seen, amt/2, minimum, amt)
	addCandidate(&values, seen, amt/3, minimum, amt)
	addCandidate(&values, seen, minimum*2, minimum, amt)
	addCandidate(&values, seen, minimum*3/2, minimum, amt)
	addCandidate(&values, seen, minimum, minimum, amt)

	if r.lastFailedAmt > 0 {
		addCandidate(
			&values, seen, r.lastFailedAmt*3/4,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*2/3,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt/2,
			minimum, amt,
		)
	}

	// Failure bounds are useful shard breakpoints. Only retain the largest
	// few after deduplication to keep route search bounded.
	var bounds []lnwire.MilliSatoshi
	for key, belief := range r.beliefs {
		if r.broken[key] || belief.upperFail <= 1 {
			continue
		}
		bound := belief.upperFail * 3 / 4
		if bound >= minimum && bound <= amt {
			bounds = append(bounds, bound)
		}
	}
	sort.Slice(bounds, func(i, j int) bool {
		return bounds[i] > bounds[j]
	})
	if len(bounds) > 4 {
		bounds = bounds[:4]
	}
	for _, bound := range bounds {
		addCandidate(&values, seen, bound, minimum, amt)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})
	return values
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= 48 {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		// This approximates joint route-set planning. It prices route
		// failure, fees, and the number of shards needed to cover the
		// remaining amount while reservations steer concurrent shards onto
		// distinct corridors.
		shardRatio := float64(amt) / float64(shard)
		choice.utility = -math.Log(choice.probability) +
			0.30*math.Log(shardRatio) +
			float64(choice.fee)/2_000_000

		if best == nil || choice.utility < best.utility {
			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	for i, key := range best.keys {
		r.reserved[key] += best.amounts[i]
	}
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief
	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = amt / 3
	} else {
		belief.estimate = (2*belief.estimate + amt/3) / 3
	}
	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}
	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount lnwire.MilliSatoshi,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}
	return value - amount
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := belief.estimate
	if preEstimate < amt {
		preEstimate = amt
	}
	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	// Settlement moves liquidity away from this direction, so shift all
	// evidence by the amount that just traversed the channel.
	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}
	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}
	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}
	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}
	return b
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	keys, amounts := routeEdgeData(rt)
	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])
			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}
			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}
		r.lastFailedAmt = 0
		return nil
	}

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	for _, key := range keys {
		r.edgeFailures[key]++
	}

	if failIndex < 0 || failIndex >= len(keys) {
		r.lastFailedAmt = rt.Hops[len(rt.Hops)-1].AmtToForward
		return nil
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	r.lastFailedAmt = rt.Hops[len(rt.Hops)-1].AmtToForward
	r.edgeFailures[key] += 2

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		// A route using an advertised policy that is rejected for fees or
		// timelocks should not be retried during this payment.
		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta    = 40
	maxRouteAttempts  = 48
	maxAmountChoices  = 24
	maxForecastSearch = 160
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved     map[edgeKey]lnwire.MilliSatoshi
	edgeFailures map[edgeKey]uint32
	broken       map[edgeKey]bool

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:  make(map[edgeKey]uint32),
		broken:        make(map[edgeKey]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, exists := r.edges[key]; exists {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, exists := sharedBeliefs.values[key]
		if !exists {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := float64(edge.capacity) * 0.10
	if scale < 1 {
		scale = 1
	}

	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))
	confidence := math.Min(0.80, 0.20*float64(belief.samples))

	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: deliver,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, exists := score[item.node]
		if !exists || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		needed := required[item.node]
		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(needed) {
				continue
			}

			total := needed + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, needed)
			edgeFee := edge.fee(needed)
			sending := needed + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = needed
			}

			failurePenalty := 0.20 *
				float64(r.edgeFailures[edge.key])
			step := -math.Log(probability) +
				float64(edgeFee)/2_000_000 +
				0.012 + failurePenalty
			candidate := item.score + step

			old, found := score[edge.key.from]
			if found && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
			})
		}
	}

	if _, exists := next[r.source]; !exists {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(r.edges[key], amounts[i])
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, exists := next[node]
		if !exists {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func ceilDivide(value lnwire.MilliSatoshi,
	divisor uint32) lnwire.MilliSatoshi {

	d := lnwire.MilliSatoshi(divisor)
	return (value + d - 1) / d
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := ceilDivide(amt, partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, maxAmountChoices)

	// Enumerate balanced and deliberately unequal allocations for every
	// feasible part count. Reservations make subsequent calls choose other
	// corridors, so these values act as the first shard of a joint plan.
	for parts := uint32(1); parts <= partsLeft; parts++ {
		base := ceilDivide(amt, parts)
		addAmount(&values, seen, base, minimum, amt)

		if parts > 1 {
			addAmount(
				&values, seen, base*9/8, minimum, amt,
			)
			addAmount(
				&values, seen, base*5/4, minimum, amt,
			)
			addAmount(
				&values, seen, base*3/2, minimum, amt,
			)
		}
	}

	if r.lastFailedAmt > 0 {
		addAmount(
			&values, seen, r.lastFailedAmt*4/5,
			minimum, amt,
		)
		addAmount(
			&values, seen, r.lastFailedAmt*2/3,
			minimum, amt,
		)
		addAmount(
			&values, seen, r.lastFailedAmt/2,
			minimum, amt,
		)
	}

	var bounds []lnwire.MilliSatoshi
	for key, belief := range r.beliefs {
		if r.broken[key] {
			continue
		}

		if belief.lowerOK >= minimum && belief.lowerOK <= amt {
			bounds = append(bounds, belief.lowerOK)
		}
		if belief.upperFail > 1 {
			value := belief.upperFail * 4 / 5
			if value >= minimum && value <= amt {
				bounds = append(bounds, value)
			}
		}
		if belief.estimate >= minimum && belief.estimate <= amt {
			bounds = append(bounds, belief.estimate*9/10)
		}
	}

	sort.Slice(bounds, func(i, j int) bool {
		return bounds[i] > bounds[j]
	})
	if len(bounds) > 8 {
		bounds = bounds[:8]
	}
	for _, value := range bounds {
		addAmount(&values, seen, value, minimum, amt)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})
	if len(values) > maxAmountChoices {
		values = values[:maxAmountChoices]
	}

	return values
}

func reserveChoice(reserved map[edgeKey]lnwire.MilliSatoshi,
	choice *routeChoice) {

	for i, key := range choice.keys {
		reserved[key] += choice.amounts[i]
	}
}

func restoreReservations(destination,
	snapshot map[edgeKey]lnwire.MilliSatoshi) {

	for key := range destination {
		delete(destination, key)
	}
	for key, value := range snapshot {
		destination[key] = value
	}
}

func copyReservations(
	source map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	result := make(map[edgeKey]lnwire.MilliSatoshi, len(source))
	for key, value := range source {
		result[key] = value
	}

	return result
}

func choiceCost(choice *routeChoice) float64 {
	p := choice.probability
	if p < 0.005 {
		p = 0.005
	}

	// The logarithmic term maximizes the chance that every planned shard
	// settles. The reciprocal term mildly prices the expected retry count.
	return -math.Log(p) + 0.035/p +
		float64(choice.fee)/2_000_000
}

func (r *candidateRouter) forecastPlan(total lnwire.MilliSatoshi,
	partsLeft uint32, first *routeChoice) (float64, bool) {

	if first.deliver <= 0 || first.deliver > total {
		return 0, false
	}

	snapshot := copyReservations(r.reserved)
	defer restoreReservations(r.reserved, snapshot)

	reserveChoice(r.reserved, first)
	remaining := total - first.deliver
	score := choiceCost(first) + 0.025
	used := uint32(1)

	for remaining > 0 {
		if used >= partsLeft {
			return 0, false
		}

		slots := partsLeft - used
		shard := ceilDivide(remaining, slots)
		choice, err := r.findRoute(shard)
		if err != nil {
			// Try to place more on an available corridor so that later
			// slots are not forced below their channel minimums.
			found := false
			for divisor := uint32(2); divisor <= slots; divisor++ {
				probe := ceilDivide(remaining, divisor)
				choice, err = r.findRoute(probe)
				if err == nil {
					found = true
					break
				}
			}
			if !found {
				return 0, false
			}
		}

		reserveChoice(r.reserved, choice)
		remaining -= choice.deliver
		score += choiceCost(choice) + 0.025
		used++
	}

	// Prefer fewer parts only when end-to-end reliability is comparable.
	score += 0.012 * float64(used*used)

	return score, true
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxRouteAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice
	bestScore := math.Inf(1)
	searches := 0

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		if searches >= maxForecastSearch {
			break
		}

		choice, err := r.findRoute(shard)
		searches++
		if err != nil {
			continue
		}

		score, feasible := r.forecastPlan(amt, partsLeft, choice)
		if !feasible {
			continue
		}

		if best == nil || score < bestScore {
			best = choice
			bestScore = score
		}
	}

	if best == nil {
		// Preserve a reliable terminal fallback when the bounded joint
		// search cannot construct a complete portfolio.
		for _, shard := range r.candidateAmounts(amt, partsLeft) {
			choice, err := r.findRoute(shard)
			if err != nil {
				continue
			}

			score := choiceCost(choice)
			if best == nil || score < bestScore {
				best = choice
				bestScore = score
			}
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	reserveChoice(r.reserved, best)
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(key edgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = amt / 3
	} else {
		belief.estimate = (2*belief.estimate + amt/3) / 3
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnForwarded(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && belief.upperFail <= amt {
		belief.upperFail = 0
	}

	optimistic := edge.capacity * 9 / 10
	if belief.estimate < amt {
		belief.estimate = amt
	}
	if belief.estimate < optimistic {
		belief.estimate = (belief.estimate + optimistic) / 2
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	estimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if estimate < optimistic {
		estimate = (estimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(estimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}

	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}

	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) releaseReservations(keys []edgeKey,
	amounts []lnwire.MilliSatoshi) {

	for i, key := range keys {
		value := r.reserved[key]
		if value <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = value - amounts[i]
		}
	}
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	r.releaseReservations(keys, amounts)

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	r.lastFailedAmt = rt.Hops[len(rt.Hops)-1].AmtToForward

	if failIndex < 0 || failIndex >= len(keys) {
		// Unknown failures receive only a small path-level penalty. They do
		// not justify poisoning every channel on the route.
		for _, key := range keys {
			if r.edgeFailures[key] < 2 {
				r.edgeFailures[key]++
			}
		}

		return nil
	}

	// Every channel before the failing outgoing channel accepted the HTLC.
	// The failed attempt rolls back, so this is a liquidity observation
	// without the balance shift associated with settlement.
	for i := 0; i < failIndex; i++ {
		r.learnForwarded(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	r.edgeFailures[key] += 2

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	minProbability = 0.003
	maxProbability = 0.995
	riskCostMsat   = 280000.0

	lowerRetryFactor = 0.62
	minShardMsat     = lnwire.MilliSatoshi(10_000)
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
	failures uint16
	success  uint16
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	mu sync.Mutex

	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	localSpent    map[uint64]lnwire.MilliSatoshi

	beliefs      map[candidateEdgeKey]liquidityBelief
	blocked      map[candidateEdgeKey]bool
	reserved     map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty map[candidateEdgeKey]float64

	baseShard           lnwire.MilliSatoshi
	lastRemaining       lnwire.MilliSatoshi
	consecutiveFailures uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		localSpent:    make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[candidateEdgeKey]liquidityBelief),
		blocked:       make(map[candidateEdgeKey]bool),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:  make(map[candidateEdgeKey]float64),
		lastRemaining: spec.Amount,
	}

	parts := uint32(1)
	switch {
	case spec.Amount > 1_000_000_000:
		parts = 8
	case spec.Amount > 400_000_000:
		parts = 6
	case spec.Amount > 100_000_000:
		parts = 4
	case spec.Amount > 25_000_000:
		parts = 2
	}
	if spec.MaxParts != 0 && parts > spec.MaxParts {
		parts = spec.MaxParts
	}
	if parts == 0 {
		parts = 1
	}
	r.baseShard = ceilDiv(
		spec.Amount, lnwire.MilliSatoshi(parts),
	)

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, exists := r.edgeByKey[key]; exists {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, exists := r.edgeByKey[key]; exists {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}
	return (a + b - 1) / b
}

func clampProbability(p float64) float64 {
	switch {
	case p < minProbability:
		return minProbability
	case p > maxProbability:
		return maxProbability
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.51 * math.Exp(-x/0.027)
	highMode := 0.47 / (1 + math.Exp(15*(x-0.80)))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) localAvailable(
	edge *candidateEdge) lnwire.MilliSatoshi {

	available := r.localBalances[edge.key.chanID]
	spent := r.localSpent[edge.key.chanID]
	reserved := r.reserved[edge.key]

	if spent >= available {
		return 0
	}
	available -= spent
	if reserved >= available {
		return 0
	}
	return available - reserved
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if amt > r.localAvailable(edge) {
			return minProbability
		}
		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		return minProbability
	}
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.055, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(belief.estimate))/width,
	))

	if belief.failures > belief.success {
		weight := 0.72
		if belief.failures >= 3 {
			weight = 0.84
		}
		return clampProbability(
			(1-weight)*prior + weight*point,
		)
	}

	return clampProbability(0.48*prior + 0.52*point)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		bestScore, exists := dist[item.node]
		if !exists || item.score > bestScore {
			continue
		}
		if item.arriving != required[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) {
				continue
			}

			reserved := r.reserved[edge.key]
			if reserved >= edge.capacity ||
				amtOver > edge.capacity-reserved {

				continue
			}

			if edge.key.from == r.source &&
				amtOver > r.localAvailable(edge) {

				continue
			}

			belief := r.beliefs[edge.key]
			if belief.upperBad != 0 &&
				amtOver >= belief.upperBad {

				continue
			}

			probability := r.probability(edge, amtOver)
			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			}

			risk := -math.Log(probability) * riskCostMsat
			penalty := r.routePenalty[edge.key]
			score := item.score + float64(fee) + risk +
				penalty + 200

			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	if _, exists := next[r.source]; !exists {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, exists := next[node]
		if !exists {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edgeByKey) {
			return nil, errors.New("route contains a cycle")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, exists := r.edgeByKey[key]
	return key, exists
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func routeFee(rt *route.Route) lnwire.MilliSatoshi {
	delivered := deliveredAmount(rt)
	if rt.TotalAmount <= delivered {
		return 0
	}
	return rt.TotalAmount - delivered
}

func (r *candidateRouter) routeProbability(rt *route.Route) float64 {
	probability := 1.0
	for i := range rt.Hops {
		key, exists := r.routeEdge(rt, i)
		if !exists {
			return minProbability
		}

		edge := r.edgeByKey[key]
		probability *= r.probability(
			edge, routeAmount(rt, i),
		)
	}
	return probability
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, exists := r.routeEdge(rt, i)
		if exists {
			r.reserved[key] += routeAmount(rt, i)
		}
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, exists := r.routeEdge(rt, i)
		if !exists {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func appendShard(values []lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return values
	}

	seen[value] = true
	return append(values, value)
}

func (r *candidateRouter) shardCandidates(amt,
	minimum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 32)

	values = appendShard(values, seen, amt, minimum, amt)
	values = appendShard(
		values, seen, r.baseShard, minimum, amt,
	)

	fractions := []float64{
		0.82, 0.68, 0.56, 0.46, 0.38, 0.31, 0.25,
		0.20, 0.16, 0.125,
	}
	for _, fraction := range fractions {
		value := lnwire.MilliSatoshi(
			float64(amt) * fraction,
		)
		values = appendShard(
			values, seen, value, minimum, amt,
		)
	}

	for _, edge := range r.edgeByKey {
		var limit lnwire.MilliSatoshi
		switch {
		case edge.key.from == r.source:
			limit = r.localAvailable(edge)

		case r.beliefs[edge.key].lowerOK != 0:
			limit = r.beliefs[edge.key].lowerOK

		case r.beliefs[edge.key].estimate != 0:
			limit = r.beliefs[edge.key].estimate * 9 / 10

		case r.beliefs[edge.key].upperBad != 0:
			limit = r.beliefs[edge.key].upperBad * 3 / 5

		default:
			continue
		}

		values = appendShard(
			values, seen, limit, minimum, amt,
		)
		values = appendShard(
			values, seen, limit*4/5, minimum, amt,
		)
	}

	values = appendShard(
		values, seen, minimum, minimum, amt,
	)
	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	return values
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	r.mu.Lock()
	defer r.mu.Unlock()

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	if amt < r.lastRemaining {
		r.consecutiveFailures = 0
	}
	r.lastRemaining = amt

	if r.spec.MaxParts != 0 &&
		inFlightHtlcs >= r.spec.MaxParts {

		return nil, errors.New("maximum parts in flight")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	minimum := ceilDiv(
		amt, lnwire.MilliSatoshi(partsLeft),
	)
	if minimum < minShardMsat {
		minimum = minShardMsat
	}
	if minimum > amt {
		minimum = amt
	}

	candidates := r.shardCandidates(amt, minimum)
	var (
		bestRoute   *route.Route
		bestUtility = math.Inf(-1)
		lastErr     error
	)

	for _, shard := range candidates {
		rt, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		probability := r.routeProbability(rt)
		fee := float64(routeFee(rt))
		sizeGain := math.Log1p(
			float64(shard) / math.Max(float64(minimum), 1),
		)

		utility := 1.35*sizeGain +
			0.42*math.Log(math.Max(probability, 1e-12)) -
			fee/2_000_000

		if shard == amt {
			utility += 0.25
		}
		if probability >= 0.09 {
			utility += 0.18
		}
		if utility > bestUtility {
			bestUtility = utility
			bestRoute = rt
		}

		if shard > minimum && probability >= 0.22 {
			break
		}
	}

	if bestRoute == nil {
		if lastErr == nil {
			lastErr = errors.New("no route found")
		}
		return nil, lastErr
	}

	r.reserve(bestRoute)
	return bestRoute, nil
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	edge := r.edgeByKey[key]
	if edge != nil {
		if belief.lowerOK > edge.capacity {
			belief.lowerOK = edge.capacity
		}
		if belief.estimate > edge.capacity {
			belief.estimate = edge.capacity
		}
		if belief.upperBad > edge.capacity {
			belief.upperBad = edge.capacity
		}
	}

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordPass(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	remaining := edge.capacity - amt
	inferred := amt + remaining*4/5
	if inferred > belief.estimate {
		belief.estimate = inferred
	}
	if belief.success < math.MaxUint16 {
		belief.success++
	}
	if belief.failures > 0 {
		belief.failures--
	}

	r.saveBelief(key, belief)
}

func subtractFloor(value,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if amt >= value {
		return 0
	}
	return value - amt
}

func (r *candidateRouter) recordSettlement(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil {
		return
	}
	if key.from == r.source {
		r.localSpent[key.chanID] += amt
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	remaining := edge.capacity - amt
	inferredPre := amt + remaining*4/5
	if inferredPre > belief.estimate {
		belief.estimate = inferredPre
	}

	belief.lowerOK = subtractFloor(belief.lowerOK, amt)
	belief.estimate = subtractFloor(belief.estimate, amt)
	if belief.upperBad != 0 {
		belief.upperBad = subtractFloor(
			belief.upperBad, amt,
		)
		if belief.upperBad == 0 {
			belief.upperBad = 1
		}
	}
	if belief.success < math.MaxUint16 {
		belief.success++
	}
	if belief.failures > 0 {
		belief.failures--
	}
	r.saveBelief(key, belief)

	reverseKey := candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edgeByKey[reverseKey]
	if reverseEdge == nil || reverseKey.from == r.source {
		return
	}

	reverse := r.beliefs[reverseKey]
	if reverse.estimate > reverseEdge.capacity-amt {
		reverse.estimate = reverseEdge.capacity
	} else {
		reverse.estimate += amt
	}
	if reverse.lowerOK != 0 {
		if reverse.lowerOK > reverseEdge.capacity-amt {
			reverse.lowerOK = reverseEdge.capacity
		} else {
			reverse.lowerOK += amt
		}
	}
	if reverse.upperBad != 0 {
		if reverse.upperBad > reverseEdge.capacity-amt {
			reverse.upperBad = 0
		} else {
			reverse.upperBad += amt
		}
	}
	r.saveBelief(reverseKey, reverse)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt / 5
	depletedEstimate := edge.capacity / 25
	if estimate > depletedEstimate {
		estimate = depletedEstimate
	}
	if estimate <= 0 {
		estimate = 1
	}
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}
	if belief.failures < math.MaxUint16 {
		belief.failures++
	}
	if belief.success > 0 {
		belief.success--
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.mu.Lock()
	defer r.mu.Unlock()

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, exists := r.routeEdge(rt, i)
			if !exists {
				continue
			}

			r.recordSettlement(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.18
		}

		delivered := deliveredAmount(rt)
		if delivered > 0 {
			remaining := r.lastRemaining - delivered
			if remaining > 0 {
				target := delivered
				if target > remaining {
					target = remaining
				}
				r.baseShard = target
			}
		}
		r.consecutiveFailures = 0
		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, exists := r.routeEdge(rt, i)
			if exists {
				r.routePenalty[key] += riskCostMsat / 3
			}
		}
		r.consecutiveFailures++
		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, exists := r.routeEdge(rt, i)
		if exists {
			r.recordPass(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.7
		}
	}

	key, exists := r.routeEdge(rt, failIndex)
	if !exists {
		r.consecutiveFailures++
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	default:
		failedAmt := routeAmount(rt, failIndex)
		r.recordFailure(key, failedAmt)
		r.routePenalty[key] += riskCostMsat * 1.4
	}

	r.consecutiveFailures++

	delivered := deliveredAmount(rt)
	retry := lnwire.MilliSatoshi(
		float64(delivered) * lowerRetryFactor,
	)
	if retry > 0 && retry < r.baseShard {
		r.baseShard = retry
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	riskCostMsat   = 260000.0
	minProbability = 0.003
	maxProbability = 0.995

	lowerRetryFactor = 0.62
	maxShardFactor   = 2.20
	maxShardProbes   = 28
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]liquidityBelief
	blocked       map[candidateEdgeKey]bool
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty  map[candidateEdgeKey]float64

	lastRemaining lnwire.MilliSatoshi
	retryHint     lnwire.MilliSatoshi
	failureCount  uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		beliefs:       make(map[candidateEdgeKey]liquidityBelief),
		blocked:       make(map[candidateEdgeKey]bool),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:  make(map[candidateEdgeKey]float64),
		lastRemaining: spec.Amount,
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, exists := r.edgeByKey[key]; exists {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, exists := r.edgeByKey[key]; exists {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}
	return (a + b - 1) / b
}

func clampProbability(p float64) float64 {
	switch {
	case p < minProbability:
		return minProbability
	case p > maxProbability:
		return maxProbability
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-x/0.024)
	highMode := 0.48 / (1 + math.Exp(15*(x-0.80)))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) available(edge *candidateEdge) lnwire.MilliSatoshi {
	available := edge.capacity
	if edge.key.from == r.source {
		available = r.localBalances[edge.key.chanID]
	}

	reserved := r.reserved[edge.key]
	if reserved >= available {
		return 0
	}
	return available - reserved
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if amt > r.available(edge) {
		return minProbability
	}
	if edge.key.from == r.source {
		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		return minProbability
	}
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.065, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(belief.estimate))/width,
	))

	return clampProbability(0.52*prior + 0.48*point)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoutePass(amt lnwire.MilliSatoshi,
	allowKnownBad bool) (*route.Route, error) {

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)

		bestScore, exists := dist[item.node]
		if !exists || item.score > bestScore {
			continue
		}
		if required[item.node] != item.arriving {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) || amtOver > r.available(edge) {
				continue
			}

			belief := r.beliefs[edge.key]
			knownBad := belief.upperBad != 0 &&
				amtOver >= belief.upperBad
			if knownBad && !allowKnownBad {
				continue
			}

			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				if fee < 0 || sending > math.MaxInt64-fee {
					continue
				}
				sending += fee
			}

			probability := r.probability(edge, amtOver)
			risk := -math.Log(probability) * riskCostMsat

			staleProbePenalty := 0.0
			if knownBad {
				staleProbePenalty = riskCostMsat * 2.4
			}

			capacityBonus := 0.0
			if edge.capacity > 0 {
				spare := float64(r.available(edge)-amtOver) /
					float64(edge.capacity)
				if spare > 0 {
					capacityBonus = math.Min(
						45000, spare*18000,
					)
				}
			}

			score := item.score + float64(fee) + risk +
				r.routePenalty[edge.key] + staleProbePenalty +
				250 - capacityBonus

			oldScore, seen := dist[edge.key.from]
			if seen && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	if _, exists := next[r.source]; !exists {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	rt, err := r.findRoutePass(amt, false)
	if err == nil {
		return rt, nil
	}

	// Hard liquidity bounds are intentionally retained across payments.
	// If they eliminate every path, probe the least costly stale path once
	// instead of terminally giving up without refreshing the evidence.
	return r.findRoutePass(amt, true)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, exists := next[node]
		if !exists {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edgeByKey) {
			return nil, errors.New("route contains a cycle")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		fee := outgoing.fee(amtOver[i+1])
		if fee < 0 || amtOver[i+1] > math.MaxInt64-fee {
			return nil, errors.New("route amount overflow")
		}

		amtOver[i] = amtOver[i+1] + fee
		expiryOver[i] = expiryOver[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, exists := r.edgeByKey[key]

	return key, exists
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, exists := r.routeEdge(rt, i)
		if exists {
			r.reserved[key] += routeAmount(rt, i)
		}
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, exists := r.routeEdge(rt, i)
		if !exists {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func appendProbe(probes []lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return probes
	}

	seen[value] = true
	return append(probes, value)
}

func (r *candidateRouter) shardProbes(remaining,
	minimum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	maximum := remaining
	if minimum < remaining {
		softMax := lnwire.MilliSatoshi(
			float64(minimum) * maxShardFactor,
		)
		if softMax > minimum && softMax < maximum {
			maximum = softMax
		}
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	probes := make([]lnwire.MilliSatoshi, 0, maxShardProbes)

	probes = appendProbe(probes, seen, minimum, minimum, maximum)
	for _, factor := range []float64{
		1.12, 1.28, 1.48, 1.72, 2.00, 2.20,
	} {
		probes = appendProbe(
			probes, seen,
			lnwire.MilliSatoshi(float64(minimum)*factor),
			minimum, maximum,
		)
	}

	if r.retryHint != 0 {
		probes = appendProbe(
			probes, seen, r.retryHint, minimum, maximum,
		)
	}

	for _, belief := range r.beliefs {
		if belief.lowerOK != 0 {
			for _, factor := range []float64{0.96, 0.82} {
				probes = appendProbe(
					probes, seen,
					lnwire.MilliSatoshi(
						float64(belief.lowerOK) *
							factor,
					),
					minimum, maximum,
				)
			}
		}

		if belief.upperBad != 0 {
			for _, factor := range []float64{0.72, 0.55} {
				probes = appendProbe(
					probes, seen,
					lnwire.MilliSatoshi(
						float64(belief.upperBad) *
							factor,
					),
					minimum, maximum,
				)
			}
		}
	}

	probes = appendProbe(
		probes, seen, maximum, minimum, maximum,
	)
	sort.Slice(probes, func(i, j int) bool {
		return probes[i] < probes[j]
	})

	if len(probes) <= maxShardProbes {
		return probes
	}

	trimmed := make([]lnwire.MilliSatoshi, 0, maxShardProbes)
	for i, probe := range probes {
		if len(trimmed) == maxShardProbes {
			break
		}

		remainingSlots := maxShardProbes - len(trimmed)
		remainingItems := len(probes) - i
		if i == 0 || i == len(probes)-1 ||
			remainingItems <= remainingSlots ||
			i%(len(probes)/maxShardProbes+1) == 0 {

			trimmed = append(trimmed, probe)
		}
	}

	return trimmed
}

func (r *candidateRouter) routeQuality(rt *route.Route,
	delivered, minimum lnwire.MilliSatoshi) float64 {

	logProbability := 0.0
	for i := range rt.Hops {
		key, exists := r.routeEdge(rt, i)
		if !exists {
			return math.Inf(-1)
		}

		edge := r.edgeByKey[key]
		logProbability += math.Log(
			r.probability(edge, routeAmount(rt, i)),
		)
	}

	fee := rt.TotalAmount - delivered
	sizeGain := math.Log(
		math.Max(1, float64(delivered)/float64(minimum)),
	)

	// Reliability dominates. The size term rewards a proven high-liquidity
	// corridor enough to create unequal MPP shards, while avoiding a blind
	// preference for the largest gossip-feasible amount.
	return logProbability + 0.34*sizeGain -
		float64(fee)/riskCostMsat
}

func (r *candidateRouter) chooseRoute(remaining,
	minimum lnwire.MilliSatoshi) (*route.Route, error) {

	probes := r.shardProbes(remaining, minimum)

	var (
		best        *route.Route
		bestQuality = math.Inf(-1)
		lastErr     error
	)

	for _, shard := range probes {
		rt, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		quality := r.routeQuality(rt, shard, minimum)
		if best == nil || quality > bestQuality {
			best = rt
			bestQuality = quality
		}
	}

	if best != nil {
		return best, nil
	}
	if lastErr == nil {
		lastErr = errors.New("no route found")
	}

	return nil, lastErr
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts in flight")
	}

	if amt < r.lastRemaining {
		r.failureCount = 0
		r.retryHint = 0
	}
	r.lastRemaining = amt

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	if partsLeft == 0 {
		return nil, errors.New("maximum parts in flight")
	}

	minimum := ceilDiv(
		amt, lnwire.MilliSatoshi(partsLeft),
	)
	if minimum <= 0 || minimum > amt {
		minimum = amt
	}

	rt, err := r.chooseRoute(amt, minimum)
	if err != nil {
		return nil, err
	}

	r.reserve(rt)
	return rt, nil
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	estimate := amt
	if edge.capacity > amt {
		estimate += (edge.capacity - amt) * 4 / 5
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt * 28 / 100
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, exists := r.routeEdge(rt, i)
			if !exists {
				continue
			}

			r.recordSuccess(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.20
		}

		r.failureCount = 0
		r.retryHint = 0
		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, exists := r.routeEdge(rt, i)
			if exists {
				r.routePenalty[key] += riskCostMsat * 0.45
			}
		}

		r.failureCount++
		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, exists := r.routeEdge(rt, i)
		if exists {
			r.recordSuccess(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.65
		}
	}

	key, exists := r.routeEdge(rt, failIndex)
	if !exists {
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	failedAmount := routeAmount(rt, failIndex)
	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	default:
		r.recordFailure(key, failedAmount)
		r.routePenalty[key] += riskCostMsat

		delivered := deliveredAmount(rt)
		retry := lnwire.MilliSatoshi(
			float64(delivered) * lowerRetryFactor,
		)
		if retry > 0 &&
			(r.retryHint == 0 || retry < r.retryHint) {

			r.retryHint = retry
		}
	}

	r.failureCount++
	if r.failureCount >= 3 {
		r.routePenalty[key] += riskCostMsat * 0.35
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	mu sync.Mutex

	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved     map[edgeKey]lnwire.MilliSatoshi
	edgeFailures map[edgeKey]uint32
	broken       map[edgeKey]bool

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:  make(map[edgeKey]uint32),
		broken:        make(map[edgeKey]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity * 9 / 10
		}

		if belief.estimate > edge.capacity {
			belief.estimate = edge.capacity
		}
		if belief.lowerOK > edge.capacity {
			belief.lowerOK = edge.capacity
		}
		if belief.upperFail > edge.capacity {
			belief.upperFail = 0
		}

		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005

	case p > 0.985:
		return 0.985

	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)

	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := float64(edge.capacity) * 0.08
	if scale < 1 {
		scale = 1
	}

	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))

	confidence := math.Min(0.82, 0.20*float64(belief.samples))
	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)

		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(item.amt) {
				continue
			}

			totalLiquidity := item.amt + r.reserved[edge.key]
			if totalLiquidity > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				totalLiquidity > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee

			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			failurePenalty := 0.16 *
				math.Min(4, float64(r.edgeFailures[edge.key]))

			step := -math.Log(probability) +
				float64(edgeFee)/2_500_000 +
				0.012 + failurePenalty

			candidate := item.score + step
			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(
			r.edges[key], amounts[i],
		)
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: clampRouteProbability(probability),
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func clampRouteProbability(p float64) float64 {
	if p < 0.0001 {
		return 0.0001
	}
	if p > 0.999 {
		return 0.999
	}

	return p
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to

		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New(
				"route contains a cycle",
			)
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))

	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)

		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}
	if minimum > amt {
		minimum = amt
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 18)

	addCandidate(&values, seen, amt, minimum, amt)
	addCandidate(&values, seen, amt*7/8, minimum, amt)
	addCandidate(&values, seen, amt*3/4, minimum, amt)
	addCandidate(&values, seen, amt*2/3, minimum, amt)
	addCandidate(&values, seen, amt*3/5, minimum, amt)
	addCandidate(&values, seen, amt/2, minimum, amt)
	addCandidate(&values, seen, amt*2/5, minimum, amt)
	addCandidate(&values, seen, amt/3, minimum, amt)
	addCandidate(&values, seen, minimum*2, minimum, amt)
	addCandidate(&values, seen, minimum*3/2, minimum, amt)
	addCandidate(&values, seen, minimum, minimum, amt)

	if r.lastFailedAmt > 0 {
		addCandidate(
			&values, seen, r.lastFailedAmt*7/8,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*3/4,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*2/3,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt/2,
			minimum, amt,
		)
	}

	var bounds []lnwire.MilliSatoshi
	for key, belief := range r.beliefs {
		if r.broken[key] {
			continue
		}

		if belief.lowerOK >= minimum && belief.lowerOK <= amt {
			bounds = append(bounds, belief.lowerOK)
		}

		if belief.upperFail > 1 {
			safe := belief.upperFail * 7 / 8
			if safe >= minimum && safe <= amt {
				bounds = append(bounds, safe)
			}
		}

		if belief.estimate >= minimum && belief.estimate <= amt {
			bounds = append(bounds, belief.estimate*7/8)
		}
	}

	sort.Slice(bounds, func(i, j int) bool {
		return bounds[i] > bounds[j]
	})
	if len(bounds) > 6 {
		bounds = bounds[:6]
	}

	for _, bound := range bounds {
		addCandidate(&values, seen, bound, minimum, amt)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	return values
}

func choiceUtility(choice *routeChoice, remaining,
	shard lnwire.MilliSatoshi) float64 {

	probability := clampRouteProbability(choice.probability)
	ratio := float64(remaining) / float64(shard)

	expectedAttempts := 1 / probability
	partCost := 0.22 * math.Max(0, ratio-1)
	feeCost := float64(choice.fee) / 2_000_000

	return expectedAttempts + partCost + feeCost
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	r.mu.Lock()
	defer r.mu.Unlock()

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= 48 {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		choice.utility = choiceUtility(choice, amt, shard)
		if best == nil ||
			choice.utility < best.utility-1e-12 ||
			(math.Abs(choice.utility-best.utility) <= 1e-12 &&
				choice.deliver > best.deliver) {

			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	for i, key := range best.keys {
		r.reserved[key] += best.amounts[i]
	}
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}

		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	failedEstimate := amt / 4
	switch {
	case belief.estimate == 0:
		belief.estimate = failedEstimate

	case belief.estimate >= amt:
		belief.estimate = (
			belief.estimate + 2*failedEstimate
		) / 3

	default:
		belief.estimate = (
			2*belief.estimate + failedEstimate
		) / 3
	}

	if belief.estimate > edge.capacity {
		belief.estimate = edge.capacity
	}
	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnAvailable(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	optimistic := edge.capacity * 9 / 10
	if belief.estimate < amt {
		belief.estimate = amt
	}
	if belief.estimate < optimistic {
		belief.estimate = (
			2*belief.estimate + optimistic
		) / 3
	}

	if belief.upperFail > 0 && belief.upperFail <= belief.lowerOK {
		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSettlement(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10

	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}

	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}

	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func failureEdgeIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) releaseReservations(keys []edgeKey,
	amounts []lnwire.MilliSatoshi) {

	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.mu.Lock()
	defer r.mu.Unlock()

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	r.releaseReservations(keys, amounts)

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSettlement(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	r.lastFailedAmt = delivered

	failIndex := failureEdgeIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(keys) {
		for _, key := range keys {
			if r.edgeFailures[key] < 8 {
				r.edgeFailures[key]++
			}
		}

		return nil
	}

	for i := 0; i < failIndex; i++ {
		key := keys[i]
		r.learnAvailable(key, amounts[i])

		if r.edgeFailures[key] > 0 {
			r.edgeFailures[key]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	if r.edgeFailures[key] < 8 {
		r.edgeFailures[key] += 2
	}

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta   = 40
	maxRouteAttempts = 64
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved      map[edgeKey]lnwire.MilliSatoshi
	edgeFailures  map[edgeKey]uint32
	broken        map[edgeKey]bool
	routeFailures map[string]uint32

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[edgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		beliefs:        make(map[edgeKey]liquidityBelief),
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:   make(map[edgeKey]uint32),
		broken:         make(map[edgeKey]bool),
		routeFailures:  make(map[string]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = normalizeBelief(belief, edge.capacity)
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func normalizeBelief(b liquidityBelief,
	capacity lnwire.MilliSatoshi) liquidityBelief {

	if b.lowerOK > capacity {
		b.lowerOK = capacity
	}
	if b.upperFail > capacity {
		b.upperFail = 0
	}
	if b.estimate > capacity {
		b.estimate = capacity
	}
	if b.upperFail > 0 && b.lowerOK >= b.upperFail {
		b.lowerOK = b.upperFail - 1
	}
	if b.lowerOK < 0 {
		b.lowerOK = 0
	}

	return b
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	estimate := belief.estimate
	if estimate <= 0 {
		estimate = edge.capacity / 2
	}

	scale := float64(edge.capacity) * 0.08
	if scale < 1 {
		scale = 1
	}

	point := 1 / (1 + math.Exp(
		(float64(total)-float64(estimate))/scale,
	))
	confidence := math.Min(0.82, 0.18*float64(belief.samples))

	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
	signature   string
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{r.spec.Target: 0}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: deliver,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		needed := required[item.node]
		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(needed) {
				continue
			}

			total := needed + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, needed)
			edgeFee := edge.fee(needed)
			sending := needed + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = needed
			}

			failurePenalty := 0.20 *
				math.Log1p(float64(r.edgeFailures[edge.key]))
			step := -math.Log(probability) +
				float64(edgeFee)/2_500_000 +
				0.012 + failurePenalty
			candidate := item.score + step

			old, exists := score[edge.key.from]
			if exists && candidate >= old-1e-12 {
				continue
			}

			score[edge.key.from] = candidate
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(r.edges[key], amounts[i])
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
		signature:   routeSignature(keys),
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func routeSignature(keys []edgeKey) string {
	var builder strings.Builder
	for _, key := range keys {
		builder.WriteString(strconv.FormatUint(key.chanID, 10))
		builder.WriteByte('/')
	}

	return builder.String()
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}
	if minimum > amt {
		minimum = amt
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, int(partsLeft)+18)

	// Evaluate every equal-part plan. This lets the route search jointly
	// choose the effective part count instead of relying on a halving ladder.
	for parts := uint32(1); parts <= partsLeft; parts++ {
		shard := (amt + lnwire.MilliSatoshi(parts) - 1) /
			lnwire.MilliSatoshi(parts)
		addCandidate(&values, seen, shard, minimum, amt)
	}

	addCandidate(&values, seen, amt*7/8, minimum, amt)
	addCandidate(&values, seen, amt*4/5, minimum, amt)
	addCandidate(&values, seen, amt*3/4, minimum, amt)
	addCandidate(&values, seen, amt*2/3, minimum, amt)
	addCandidate(&values, seen, amt*3/5, minimum, amt)
	addCandidate(&values, seen, amt/2, minimum, amt)

	if r.lastFailedAmt > 0 {
		addCandidate(
			&values, seen, r.lastFailedAmt*7/8,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*3/4,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*2/3,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt/2,
			minimum, amt,
		)
	}

	type breakpoint struct {
		value lnwire.MilliSatoshi
		score float64
	}

	breakpoints := make([]breakpoint, 0, len(r.beliefs)*2)
	for key, belief := range r.beliefs {
		edge := r.edges[key]
		if edge == nil || r.broken[key] {
			continue
		}

		if belief.upperFail > 1 {
			value := belief.upperFail - 1
			if value >= minimum && value <= amt {
				breakpoints = append(breakpoints, breakpoint{
					value: value,
					score: float64(value) * 2,
				})
			}

			value = belief.upperFail * 3 / 4
			if value >= minimum && value <= amt {
				breakpoints = append(breakpoints, breakpoint{
					value: value,
					score: float64(value) * 1.5,
				})
			}
		}

		available := belief.estimate
		if belief.lowerOK > available {
			available = belief.lowerOK
		}
		if available > edge.capacity {
			available = edge.capacity
		}
		available -= r.reserved[key]
		if available >= minimum && available <= amt {
			breakpoints = append(breakpoints, breakpoint{
				value: available,
				score: float64(available),
			})
		}
	}

	sort.Slice(breakpoints, func(i, j int) bool {
		return breakpoints[i].score > breakpoints[j].score
	})
	if len(breakpoints) > 10 {
		breakpoints = breakpoints[:10]
	}
	for _, point := range breakpoints {
		addCandidate(
			&values, seen, point.value, minimum, amt,
		)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	return values
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxRouteAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		partCount := float64(
			(amt + shard - 1) / shard,
		)
		if partCount > float64(partsLeft) {
			continue
		}

		// Reliability remains the primary objective. The mild part-count
		// term keeps reliable unequal shards preferable to repeated probing,
		// while still allowing a full payment when its probability is good.
		routePenalty := 0.34 * math.Log1p(
			float64(r.routeFailures[choice.signature]),
		)
		choice.utility = -math.Log(choice.probability) +
			0.16*math.Log(partCount) +
			float64(choice.fee)/2_500_000 +
			routePenalty

		if best == nil || choice.utility < best.utility {
			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	for i, key := range best.keys {
		r.reserved[key] += best.amounts[i]
	}
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	edge := r.edges[key]
	if edge != nil {
		belief = normalizeBelief(belief, edge.capacity)
	}

	r.beliefs[key] = belief
	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) observePass(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.estimate < amt {
		belief.estimate = amt
	}

	optimistic := edge.capacity * 4 / 5
	if belief.estimate < optimistic {
		belief.estimate = (belief.estimate + optimistic) / 2
	}
	if belief.upperFail > 0 && belief.upperFail <= belief.lowerOK {
		belief.upperFail = 0
	}
	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	depletedEstimate := amt / 5
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = depletedEstimate
	} else {
		belief.estimate =
			(3*belief.estimate + depletedEstimate) / 4
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = belief.upperFail - 1
	}
	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	if key.from != r.source {
		belief := r.beliefs[key]
		preEstimate := maxMSat(belief.estimate, amt)
		optimistic := edge.capacity * 9 / 10
		if preEstimate < optimistic {
			preEstimate = (preEstimate + optimistic) / 2
		}

		belief.estimate = subtractFloor(preEstimate, amt, 0)
		belief.lowerOK = subtractFloor(
			maxMSat(belief.lowerOK, amt), amt, 0,
		)
		if belief.upperFail > 0 {
			belief.upperFail = subtractFloor(
				belief.upperFail, amt, 1,
			)
		}
		belief.samples++
		r.storeBelief(key, belief)
	}

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}
	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}
	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}
	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func failureEdgeIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) releaseReservations(keys []edgeKey,
	amounts []lnwire.MilliSatoshi) {

	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	r.releaseReservations(keys, amounts)
	signature := routeSignature(keys)

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		delete(r.routeFailures, signature)
		r.lastFailedAmt = 0
		return nil
	}

	r.routeFailures[signature]++
	r.lastFailedAmt =
		rt.Hops[len(rt.Hops)-1].AmtToForward

	failIndex := failureEdgeIndex(
		rt, result.FailureSource,
	)
	if failIndex < 0 || failIndex >= len(keys) {
		// An unattributed failure says nothing reliable about a specific
		// channel. Penalize only this complete route so alternatives are
		// explored without poisoning every edge it contains.
		return nil
	}

	// Every channel before the failing node forwarded the HTLC. Record that
	// amount as passable without applying settlement balance changes.
	for i := 0; i < failIndex; i++ {
		r.observePass(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	r.edgeFailures[key]++

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)
		r.edgeFailures[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta   = 40
	maxRouteAttempts = 48
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type attemptedRoute struct {
	pathHash uint64
	amount   lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved      map[edgeKey]lnwire.MilliSatoshi
	edgeFailures  map[edgeKey]uint32
	policyBroken  map[edgeKey]bool
	attempted     map[attemptedRoute]uint32
	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:  make(map[edgeKey]uint32),
		policyBroken:  make(map[edgeKey]bool),
		attempted:     make(map[attemptedRoute]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005

	case p > 0.985:
		return 0.985

	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := float64(edge.capacity) * 0.08
	if scale < 1 {
		scale = 1
	}

	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))
	confidence := math.Min(0.82, 0.20*float64(belief.samples))

	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

func (r *candidateRouter) edgeAvailable(edge *candidateEdge,
	amt lnwire.MilliSatoshi) bool {

	if r.policyBroken[edge.key] || !edge.usable(amt) {
		return false
	}

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return false
	}

	if edge.key.from == r.source {
		return total <= r.localBalances[edge.key.chanID]
	}

	upper := r.beliefs[edge.key].upperFail
	return upper == 0 || total < upper
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
	pathHash    uint64
}

func hashPath(keys []edgeKey) uint64 {
	hash := uint64(1469598103934665603)
	for _, key := range keys {
		hash ^= key.chanID
		hash *= 1099511628211

		for _, b := range key.from {
			hash ^= uint64(b)
			hash *= 1099511628211
		}
		for _, b := range key.to {
			hash ^= uint64(b)
			hash *= 1099511628211
		}
	}

	return hash
}

func (r *candidateRouter) findRoute(deliver lnwire.MilliSatoshi,
	diversity map[edgeKey]float64) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if !r.edgeAvailable(edge, item.amt) {
				continue
			}

			probability := r.edgeProbability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			failurePenalty := 0.24 *
				math.Log1p(float64(r.edgeFailures[edge.key]))
			capacityRatio := float64(item.amt) /
				float64(edge.capacity)
			capacityPenalty := 0.035 * capacityRatio *
				capacityRatio

			step := -math.Log(probability) +
				float64(edgeFee)/2_500_000 +
				0.012 + failurePenalty + capacityPenalty +
				diversity[edge.key]
			candidate := item.score + step

			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(
			r.edges[key], amounts[i],
		)
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
		pathHash:    hashPath(keys),
	}, nil
}

func (r *candidateRouter) routeAlternatives(
	deliver lnwire.MilliSatoshi) []*routeChoice {

	const alternatives = 5

	diversity := make(map[edgeKey]float64)
	seen := make(map[uint64]bool)
	choices := make([]*routeChoice, 0, alternatives)

	for round := 0; round < alternatives*2; round++ {
		choice, err := r.findRoute(deliver, diversity)
		if err != nil {
			break
		}

		if !seen[choice.pathHash] {
			seen[choice.pathHash] = true
			choices = append(choices, choice)
			if len(choices) == alternatives {
				break
			}
		}

		penalty := 0.30
		if seen[choice.pathHash] {
			penalty = 0.48
		}
		for _, key := range choice.keys {
			diversity[key] += penalty
		}
	}

	return choices
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to

		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New(
				"route contains a cycle",
			)
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))

	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 24)

	addCandidate(&values, seen, amt, minimum, amt)
	addCandidate(&values, seen, amt*7/8, minimum, amt)
	addCandidate(&values, seen, amt*3/4, minimum, amt)
	addCandidate(&values, seen, amt*2/3, minimum, amt)
	addCandidate(&values, seen, amt*3/5, minimum, amt)
	addCandidate(&values, seen, amt/2, minimum, amt)
	addCandidate(&values, seen, amt*2/5, minimum, amt)
	addCandidate(&values, seen, amt/3, minimum, amt)
	addCandidate(&values, seen, minimum*5/2, minimum, amt)
	addCandidate(&values, seen, minimum*2, minimum, amt)
	addCandidate(&values, seen, minimum*3/2, minimum, amt)
	addCandidate(&values, seen, minimum, minimum, amt)

	if r.lastFailedAmt > 0 {
		addCandidate(
			&values, seen, r.lastFailedAmt*3/4,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*5/8,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt/2,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*3/8,
			minimum, amt,
		)
	}

	var bounds []lnwire.MilliSatoshi
	for key, belief := range r.beliefs {
		if r.policyBroken[key] || belief.upperFail <= 1 {
			continue
		}

		for _, numerator := range []lnwire.MilliSatoshi{7, 3, 2} {
			denominator := lnwire.MilliSatoshi(8)
			if numerator == 3 {
				denominator = 4
			}
			if numerator == 2 {
				denominator = 3
			}

			bound := belief.upperFail * numerator / denominator
			if bound >= minimum && bound <= amt {
				bounds = append(bounds, bound)
			}
		}
	}

	sort.Slice(bounds, func(i, j int) bool {
		return bounds[i] > bounds[j]
	})
	if len(bounds) > 8 {
		bounds = bounds[:8]
	}

	for _, bound := range bounds {
		addCandidate(
			&values, seen, bound, minimum, amt,
		)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	return values
}

func ceilParts(total, shard lnwire.MilliSatoshi) uint32 {
	return uint32((total + shard - 1) / shard)
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxRouteAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		partsNeeded := ceilParts(amt, shard)
		if partsNeeded > partsLeft {
			continue
		}

		for _, choice := range r.routeAlternatives(shard) {
			attempt := attemptedRoute{
				pathHash: choice.pathHash,
				amount:   choice.deliver,
			}
			tries := r.attempted[attempt]
			if tries >= 1 {
				continue
			}

			risk := -math.Log(choice.probability)
			partFactor := math.Sqrt(float64(partsNeeded))
			choice.utility = risk*partFactor +
				0.075*float64(partsNeeded-1) +
				float64(choice.fee)/2_500_000 +
				0.20*float64(tries)

			if best == nil || choice.utility < best.utility {
				best = choice
			}
		}
	}

	if best == nil {
		return nil, errors.New("no untried route found")
	}

	for i, key := range best.keys {
		r.reserved[key] += best.amounts[i]
	}

	r.attempted[attemptedRoute{
		pathHash: best.pathHash,
		amount:   best.deliver,
	}]++
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}

		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(key edgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnPassed(key edgeKey,
	amt lnwire.MilliSatoshi) {

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.estimate < amt {
		belief.estimate = amt
	}
	if belief.upperFail > 0 && belief.upperFail <= belief.lowerOK {
		belief.upperFail = 0
	}
	belief.samples++

	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	if key.from == r.source {
		balance := r.localBalances[key.chanID]
		if amt <= balance {
			r.localBalances[key.chanID] = amt - 1
		}
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	failedEstimate := amt / 4
	switch {
	case belief.estimate == 0:
		belief.estimate = failedEstimate

	case belief.estimate >= amt:
		belief.estimate = (
			belief.estimate + 2*failedEstimate
		) / 3

	default:
		belief.estimate = (
			2*belief.estimate + failedEstimate
		) / 3
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}
	belief.samples++

	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	preEstimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	belief.samples++

	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}

	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) releaseReservations(keys []edgeKey,
	amounts []lnwire.MilliSatoshi) {

	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}
}

func failureEdgeIndex(rt *route.Route,
	failureSource route.Vertex) int {

	if failureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == failureSource {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	r.releaseReservations(keys, amounts)

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	failIndex := failureEdgeIndex(rt, result.FailureSource)
	r.lastFailedAmt = rt.Hops[len(rt.Hops)-1].AmtToForward

	if failIndex < 0 || failIndex >= len(keys) {
		return nil
	}

	for i := 0; i < failIndex; i++ {
		r.learnPassed(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	r.edgeFailures[key] += 2

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBroken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved     map[edgeKey]lnwire.MilliSatoshi
	edgeFailures map[edgeKey]uint32
	broken       map[edgeKey]bool

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:  make(map[edgeKey]uint32),
		broken:        make(map[edgeKey]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := math.Max(float64(edge.capacity)*0.10, 1)
	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))

	confidence := math.Min(0.78, 0.22*float64(belief.samples))
	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(item.amt) {
				continue
			}

			total := item.amt + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			step := -math.Log(probability) +
				float64(edgeFee)/2_000_000 +
				0.012 +
				0.22*float64(r.edgeFailures[edge.key])
			candidate := item.score + step

			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(
			r.edges[key], amounts[i],
		)
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to

		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New(
				"route contains a cycle",
			)
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 18)

	addCandidate(&values, seen, amt, minimum, amt)
	addCandidate(&values, seen, amt*7/8, minimum, amt)
	addCandidate(&values, seen, amt*3/4, minimum, amt)
	addCandidate(&values, seen, amt*2/3, minimum, amt)
	addCandidate(&values, seen, amt/2, minimum, amt)
	addCandidate(&values, seen, amt/3, minimum, amt)
	addCandidate(&values, seen, minimum*2, minimum, amt)
	addCandidate(&values, seen, minimum*3/2, minimum, amt)
	addCandidate(&values, seen, minimum, minimum, amt)

	if r.lastFailedAmt > 0 {
		addCandidate(
			&values, seen, r.lastFailedAmt*4/5,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*2/3,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt/2,
			minimum, amt,
		)
	}

	var bounds []lnwire.MilliSatoshi
	for key, belief := range r.beliefs {
		if r.broken[key] {
			continue
		}

		if belief.lowerOK >= minimum && belief.lowerOK <= amt {
			bounds = append(bounds, belief.lowerOK)
		}
		if belief.upperFail > 1 {
			bounds = append(bounds, belief.upperFail*4/5)
			bounds = append(bounds, belief.upperFail*2/3)
		}
		if belief.samples > 0 && belief.estimate > 0 {
			bounds = append(bounds, belief.estimate*4/5)
		}
	}

	sort.Slice(bounds, func(i, j int) bool {
		return bounds[i] > bounds[j]
	})
	if len(bounds) > 6 {
		bounds = bounds[:6]
	}

	for _, bound := range bounds {
		addCandidate(
			&values, seen, bound, minimum, amt,
		)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	return values
}

func (r *candidateRouter) reserveChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		r.reserved[key] += choice.amounts[i]
	}
}

func (r *candidateRouter) releaseChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		value := r.reserved[key]
		if value <= choice.amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = value - choice.amounts[i]
		}
	}
}

func choiceCost(choice *routeChoice) float64 {
	return -math.Log(choice.probability) +
		float64(choice.fee)/2_000_000
}

func (r *candidateRouter) evaluatePlan(first *routeChoice,
	total lnwire.MilliSatoshi, partsLeft uint32) (float64, bool) {

	partCount := uint32(
		(total + first.deliver - 1) / first.deliver,
	)
	if partCount == 0 {
		partCount = 1
	}
	if partCount > partsLeft {
		return 0, false
	}

	choices := []*routeChoice{first}
	r.reserveChoice(first)

	defer func() {
		for i := len(choices) - 1; i >= 0; i-- {
			r.releaseChoice(choices[i])
		}
	}()

	score := choiceCost(first)
	remaining := total - first.deliver

	for slots := partCount - 1; slots > 0; slots-- {
		shard := (remaining + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)

		choice, err := r.findRoute(shard)
		if err != nil {
			return 0, false
		}

		choices = append(choices, choice)
		r.reserveChoice(choice)
		score += choiceCost(choice)
		remaining -= shard
	}

	if remaining != 0 {
		return 0, false
	}

	// This prices the expected reliability of the complete route set.
	// The small per-part charge avoids unnecessary fragmentation when
	// similarly reliable plans exist.
	score += 0.065 * float64(partCount)

	return score, true
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= 48 {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		utility, ok := r.evaluatePlan(
			choice, amt, partsLeft,
		)
		if !ok {
			continue
		}
		choice.utility = utility

		if best == nil || choice.utility < best.utility {
			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.reserveChoice(best)
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func normalizeBelief(edge *candidateEdge,
	belief *liquidityBelief) {

	if belief.estimate < 0 {
		belief.estimate = 0
	}
	if belief.estimate > edge.capacity {
		belief.estimate = edge.capacity
	}
	if belief.lowerOK > edge.capacity {
		belief.lowerOK = edge.capacity
	}
	if belief.upperFail > edge.capacity {
		belief.upperFail = 0
	}
	if belief.upperFail > 0 &&
		belief.lowerOK >= belief.upperFail {

		belief.upperFail = 0
	}
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	edge := r.edges[key]
	if edge != nil {
		normalizeBelief(edge, &belief)
	}

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = amt / 3
	} else {
		belief.estimate = (2*belief.estimate + amt/3) / 3
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnProbeSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.estimate < amt {
		belief.estimate = amt
	}

	optimistic := edge.capacity * 4 / 5
	if belief.estimate < optimistic {
		belief.estimate =
			(2*belief.estimate + optimistic) / 3
	}

	if belief.upperFail > 0 && belief.upperFail <= amt {
		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}

	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}

	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func failureEdgeIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	keys, amounts := routeEdgeData(rt)
	for i, key := range keys {
		value := r.reserved[key]
		if value <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = value - amounts[i]
		}
	}

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	if len(rt.Hops) == 0 {
		return nil
	}

	r.lastFailedAmt =
		rt.Hops[len(rt.Hops)-1].AmtToForward

	failIndex := failureEdgeIndex(
		rt, result.FailureSource,
	)
	if failIndex < 0 || failIndex >= len(keys) {
		for _, key := range keys {
			r.edgeFailures[key]++
		}

		return nil
	}

	// Every edge before the reported failure forwarded the HTLC. Since
	// the failed attempt unwinds, this is evidence without a balance
	// shift.
	for i := 0; i < failIndex; i++ {
		r.learnProbeSuccess(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex] + r.reserved[key]
	r.edgeFailures[key] += 2

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	maxAttempts    = 48
	maxPlanParts   = 16
	planBeamWidth  = 12
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved     map[edgeKey]lnwire.MilliSatoshi
	edgeFailures map[edgeKey]uint32
	broken       map[edgeKey]bool

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:  make(map[edgeKey]uint32),
		broken:        make(map[edgeKey]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func reservedAmount(reservations map[edgeKey]lnwire.MilliSatoshi,
	key edgeKey) lnwire.MilliSatoshi {

	if reservations == nil {
		return 0
	}

	return reservations[key]
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi) float64 {

	total := amt + reservedAmount(reservations, edge.key)
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := float64(edge.capacity) * 0.10
	if scale < 1 {
		scale = 1
	}

	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))
	confidence := math.Min(0.78, 0.22*float64(belief.samples))

	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(deliver lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(item.amt) {
				continue
			}

			reserved := reservedAmount(reservations, edge.key)
			if item.amt+reserved > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				item.amt+reserved >
					r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(
				edge, item.amt, reservations,
			)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			failurePenalty := 0.20 *
				float64(r.edgeFailures[edge.key])
			step := -math.Log(probability) +
				float64(edgeFee)/2_500_000 +
				0.012 + failurePenalty
			candidate := item.score + step

			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(
			r.edges[key], amounts[i], reservations,
		)
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to

		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func cloneReservations(
	source map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	clone := make(map[edgeKey]lnwire.MilliSatoshi, len(source))
	for key, amount := range source {
		clone[key] = amount
	}

	return clone
}

func reserveChoice(reservations map[edgeKey]lnwire.MilliSatoshi,
	choice *routeChoice) {

	for i, key := range choice.keys {
		reservations[key] += choice.amounts[i]
	}
}

func addAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	maximum lnwire.MilliSatoshi) {

	if value < 1_000 {
		value = 1_000
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) planningAmounts(
	remaining lnwire.MilliSatoshi, slots uint32,
	reservations map[edgeKey]lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 20)

	addAmount(&values, seen, remaining, remaining)
	if slots > 1 {
		slotsMSat := lnwire.MilliSatoshi(slots)
		balanced := (remaining + slotsMSat - 1) / slotsMSat

		addAmount(&values, seen, remaining*4/5, remaining)
		addAmount(&values, seen, remaining*3/4, remaining)
		addAmount(&values, seen, remaining*2/3, remaining)
		addAmount(&values, seen, remaining/2, remaining)
		addAmount(&values, seen, remaining*2/5, remaining)
		addAmount(&values, seen, remaining/3, remaining)
		addAmount(&values, seen, remaining/4, remaining)
		addAmount(&values, seen, balanced*3/2, remaining)
		addAmount(&values, seen, balanced*5/4, remaining)
		addAmount(&values, seen, balanced, remaining)
	}

	if r.lastFailedAmt > 0 {
		addAmount(
			&values, seen, r.lastFailedAmt*4/5, remaining,
		)
		addAmount(
			&values, seen, r.lastFailedAmt*2/3, remaining,
		)
		addAmount(
			&values, seen, r.lastFailedAmt/2, remaining,
		)
	}

	var breakpoints []lnwire.MilliSatoshi
	for key, edge := range r.edges {
		if r.broken[key] {
			continue
		}

		reserved := reservedAmount(reservations, key)
		if reserved >= edge.capacity {
			continue
		}

		belief := r.beliefs[key]
		available := edge.capacity - reserved

		if belief.lowerOK > reserved {
			breakpoints = append(
				breakpoints, belief.lowerOK-reserved,
			)
		}
		if belief.upperFail > reserved+1 {
			breakpoints = append(
				breakpoints,
				(belief.upperFail-reserved)*3/4,
			)
		}
		if belief.estimate > reserved {
			breakpoints = append(
				breakpoints,
				(belief.estimate-reserved)*9/10,
			)
		}

		breakpoints = append(breakpoints, available*4/5)
	}

	sort.Slice(breakpoints, func(i, j int) bool {
		return breakpoints[i] > breakpoints[j]
	})

	added := 0
	for _, amount := range breakpoints {
		if amount < 1_000 || amount > remaining {
			continue
		}

		before := len(values)
		addAmount(&values, seen, amount, remaining)
		if len(values) != before {
			added++
		}
		if added == 8 {
			break
		}
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	return values
}

func (r *candidateRouter) incrementalRisk(choice *routeChoice,
	reservations map[edgeKey]lnwire.MilliSatoshi) float64 {

	risk := 0.0
	for i, key := range choice.keys {
		edge := r.edges[key]
		oldAmount := reservedAmount(reservations, key)

		oldProbability := 1.0
		if oldAmount > 0 {
			oldProbability = r.edgeProbability(
				edge, 0, reservations,
			)
		}

		newProbability := r.edgeProbability(
			edge, choice.amounts[i], reservations,
		)
		ratio := newProbability / oldProbability
		if ratio > 1 {
			ratio = 1
		}
		if ratio < 0.005 {
			ratio = 0.005
		}

		risk += -math.Log(ratio)
	}

	return risk
}

type planState struct {
	remaining    lnwire.MilliSatoshi
	reservations map[edgeKey]lnwire.MilliSatoshi
	first        *routeChoice
	score        float64
	parts        uint32
	rank         float64
}

func (r *candidateRouter) planRouteSet(
	amount lnwire.MilliSatoshi, partsLeft uint32) *routeChoice {

	if partsLeft == 0 {
		return nil
	}
	if partsLeft > maxPlanParts {
		partsLeft = maxPlanParts
	}

	states := []*planState{{
		remaining:    amount,
		reservations: cloneReservations(r.reserved),
	}}

	var best *planState

	for depth := uint32(0); depth < partsLeft; depth++ {
		nextStates := make([]*planState, 0, planBeamWidth*8)

		for _, state := range states {
			if state.remaining == 0 {
				if best == nil || state.score < best.score {
					best = state
				}
				continue
			}

			slots := partsLeft - depth
			for _, shard := range r.planningAmounts(
				state.remaining, slots, state.reservations,
			) {
				if shard < state.remaining && slots == 1 {
					continue
				}

				choice, err := r.findRoute(
					shard, state.reservations,
				)
				if err != nil {
					continue
				}

				reservations := cloneReservations(
					state.reservations,
				)
				stepRisk := r.incrementalRisk(
					choice, state.reservations,
				)
				reserveChoice(reservations, choice)

				first := state.first
				if first == nil {
					first = choice
				}

				remaining := state.remaining - shard
				score := state.score + stepRisk +
					float64(choice.fee)/3_000_000 +
					0.025

				child := &planState{
					remaining:    remaining,
					reservations: reservations,
					first:        first,
					score:        score,
					parts:        state.parts + 1,
				}
				child.rank = child.score +
					float64(child.remaining)/
						float64(amount)

				if remaining == 0 {
					if best == nil || score < best.score {
						best = child
					}
				}

				nextStates = append(nextStates, child)
			}
		}

		if len(nextStates) == 0 {
			break
		}

		sort.Slice(nextStates, func(i, j int) bool {
			if nextStates[i].rank == nextStates[j].rank {
				return nextStates[i].remaining <
					nextStates[j].remaining
			}

			return nextStates[i].rank < nextStates[j].rank
		})

		if len(nextStates) > planBeamWidth {
			nextStates = nextStates[:planBeamWidth]
		}
		states = nextStates
	}

	if best != nil {
		return best.first
	}

	return nil
}

func (r *candidateRouter) fallbackRoute(
	amount lnwire.MilliSatoshi,
	partsLeft uint32) *routeChoice {

	var best *routeChoice
	bestScore := math.Inf(1)

	for _, shard := range r.planningAmounts(
		amount, partsLeft, r.reserved,
	) {
		choice, err := r.findRoute(shard, r.reserved)
		if err != nil {
			continue
		}

		parts := math.Ceil(
			float64(amount) / float64(shard),
		)
		score := r.incrementalRisk(choice, r.reserved) +
			0.08*parts +
			float64(choice.fee)/2_500_000

		if score < bestScore {
			best = choice
			bestScore = score
		}
	}

	return best
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	best := r.planRouteSet(amt, partsLeft)
	if best == nil {
		best = r.fallbackRoute(amt, partsLeft)
	}
	if best == nil {
		return nil, errors.New("no route found")
	}

	reserveChoice(r.reserved, best)
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = amt / 3
	} else {
		belief.estimate = (2*belief.estimate + amt/3) / 3
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnProbeSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && belief.upperFail <= belief.lowerOK {
		belief.upperFail = 0
	}

	optimistic := edge.capacity * 9 / 10
	if belief.estimate < amt {
		belief.estimate = amt
	}
	if belief.estimate < optimistic {
		belief.estimate = (belief.estimate + optimistic) / 2
	}
	if belief.estimate > edge.capacity {
		belief.estimate = edge.capacity
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}

	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}

	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) releaseReservations(keys []edgeKey,
	amounts []lnwire.MilliSatoshi) {

	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}
}

func failureEdgeIndex(rt *route.Route,
	failureSource route.Vertex) int {

	if failureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == failureSource {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	r.releaseReservations(keys, amounts)

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	r.lastFailedAmt = delivered

	failIndex := failureEdgeIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(keys) {
		for _, key := range keys {
			r.edgeFailures[key]++
		}

		return nil
	}

	// Every edge before the failing edge forwarded the HTLC. This proves
	// liquidity for the attempted amount, but the failed HTLC rolled back,
	// so these observations must not shift channel balances.
	for i := 0; i < failIndex; i++ {
		r.learnProbeSuccess(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	r.edgeFailures[key] += 3

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	minProbability = 0.003
	maxProbability = 0.995

	// Reliability is the primary routing objective. Fees remain relevant,
	// but should not make a cheap, low-probability route dominate a much
	// more reliable route.
	riskCostMsat = 300000.0

	// Candidate shard sizes form a geometric ladder. Route selection then
	// jointly chooses the shard and path with the greatest expected
	// progress.
	shardStep = 0.72

	maxShardCandidates = 18
	minShardMsat       = lnwire.MilliSatoshi(10_000)
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(
	amt lnwire.MilliSatoshi) bool {

	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type amountPenalty struct {
	threshold lnwire.MilliSatoshi
	cost      float64
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]liquidityBelief
	blocked       map[candidateEdgeKey]bool
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	penalties     map[candidateEdgeKey]amountPenalty

	initialShard lnwire.MilliSatoshi
	lastFailed  lnwire.MilliSatoshi
	lastRemain  lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		beliefs:       make(map[candidateEdgeKey]liquidityBelief),
		blocked:       make(map[candidateEdgeKey]bool),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		penalties:     make(map[candidateEdgeKey]amountPenalty),
		lastRemain:    spec.Amount,
	}

	parts := spec.MaxParts
	if parts == 0 {
		parts = 1
	}
	r.initialShard = ceilDiv(
		spec.Amount, lnwire.MilliSatoshi(parts),
	)

	ctx := context.Background()
	seen := map[route.Vertex]bool{
		source: true,
	}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, ok := r.edgeByKey[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}

	return (a + b - 1) / b
}

func clampProbability(p float64) float64 {
	if p < minProbability {
		return minProbability
	}
	if p > maxProbability {
		return maxProbability
	}

	return p
}

func bimodalPrior(
	amt, capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)

	// The first mode describes tiny payments that can pass even when the
	// directed side is nearly depleted. The second describes channels
	// whose balance is concentrated on the usable side.
	lowMode := 0.50 * math.Exp(-x/0.024)
	highMode := 0.48 / (1 + math.Exp(15*(x-0.77)))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) availableLocal(
	edge *candidateEdge) lnwire.MilliSatoshi {

	available := r.localBalances[edge.key.chanID]
	reserved := r.reserved[edge.key]
	if reserved >= available {
		return 0
	}

	return available - reserved
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if amt > r.availableLocal(edge) {
			return minProbability
		}

		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		return minProbability
	}
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.065, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(belief.estimate))/width,
	))

	// Bounds carry the strongest evidence. Between them, the estimate is
	// useful but the bimodal prior remains dominant enough to prevent a
	// single observation from overfitting the route choice.
	return clampProbability(0.60*prior + 0.40*point)
}

func (r *candidateRouter) edgePenalty(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) float64 {

	penalty, ok := r.penalties[key]
	if !ok || penalty.cost <= 0 {
		return 0
	}

	if penalty.threshold <= 0 || amt >= penalty.threshold {
		return penalty.cost
	}

	// A liquidity failure is evidence against the attempted amount, not
	// against every smaller shard. Penalty strength falls quadratically
	// below the failed amount.
	ratio := float64(amt) / float64(penalty.threshold)
	return penalty.cost * ratio * ratio * 0.20
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]

	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)

		bestScore, ok := dist[item.node]
		if !ok || item.score > bestScore {
			continue
		}
		if item.arriving != required[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) {
				continue
			}

			reserved := r.reserved[edge.key]
			if reserved >= edge.capacity ||
				amtOver > edge.capacity-reserved {

				continue
			}

			if edge.key.from == r.source &&
				amtOver > r.availableLocal(edge) {

				continue
			}

			probability := r.probability(edge, amtOver)
			belief := r.beliefs[edge.key]
			if belief.upperBad != 0 &&
				amtOver >= belief.upperBad {

				continue
			}

			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			} else if sending > r.availableLocal(edge) {
				continue
			}

			risk := -math.Log(probability) * riskCostMsat
			score := item.score + float64(fee) + risk +
				r.edgePenalty(edge.key, amtOver) + 200

			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge

			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to

		if len(path) > len(r.edgeByKey) {
			return nil, errors.New("route contains a cycle")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, ok := r.edgeByKey[key]

	return key, ok
}

func routeAmount(
	rt *route.Route, index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(
	rt *route.Route) lnwire.MilliSatoshi {

	if len(rt.Hops) == 0 {
		return 0
	}

	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func routeFee(rt *route.Route) lnwire.MilliSatoshi {
	delivered := deliveredAmount(rt)
	if rt.TotalAmount <= delivered {
		return 0
	}

	return rt.TotalAmount - delivered
}

func (r *candidateRouter) routeProbability(
	rt *route.Route) float64 {

	probability := 1.0
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			return minProbability
		}

		edge := r.edgeByKey[key]
		if edge == nil {
			return minProbability
		}

		probability *= r.probability(
			edge, routeAmount(rt, i),
		)
	}

	return clampProbability(probability)
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		r.reserved[key] += routeAmount(rt, i)
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func addShardCandidate(candidates map[lnwire.MilliSatoshi]struct{},
	value, remaining lnwire.MilliSatoshi) {

	if value <= 0 {
		return
	}
	if value > remaining {
		value = remaining
	}

	minimum := minShardMsat
	if remaining < minimum {
		minimum = remaining
	}
	if value < minimum {
		return
	}

	candidates[value] = struct{}{}
}

func (r *candidateRouter) shardCandidates(
	remaining lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	candidates := make(map[lnwire.MilliSatoshi]struct{})
	addShardCandidate(candidates, remaining, remaining)
	addShardCandidate(candidates, r.initialShard, remaining)

	if r.lastFailed > 0 {
		addShardCandidate(
			candidates,
			lnwire.MilliSatoshi(
				float64(r.lastFailed)*shardStep,
			),
			remaining,
		)
		addShardCandidate(
			candidates,
			r.lastFailed/2,
			remaining,
		)
	}

	// A compact geometric ladder covers both large single-path attempts
	// and deliberately unequal MPP shards. Each amount is evaluated with
	// its own best path, making the choice a joint amount-route decision.
	value := remaining
	for i := 0; i < maxShardCandidates; i++ {
		addShardCandidate(candidates, value, remaining)

		next := lnwire.MilliSatoshi(
			float64(value) * shardStep,
		)
		if next >= value {
			next = value - 1
		}
		if next < minShardMsat {
			break
		}
		value = next
	}

	// Evidence-derived boundaries are particularly valuable after a
	// failure because they probe just below a channel's known cliff.
	for _, belief := range r.beliefs {
		if belief.upperBad != 0 {
			addShardCandidate(
				candidates,
				lnwire.MilliSatoshi(
					float64(belief.upperBad)*0.67,
				),
				remaining,
			)
		}
		if belief.lowerOK != 0 {
			addShardCandidate(
				candidates, belief.lowerOK, remaining,
			)
		}
		if belief.estimate != 0 {
			addShardCandidate(
				candidates,
				lnwire.MilliSatoshi(
					float64(belief.estimate)*0.82,
				),
				remaining,
			)
		}
	}

	values := make([]lnwire.MilliSatoshi, 0, len(candidates))
	for candidate := range candidates {
		values = append(values, candidate)
	}
	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	return values
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if inFlightHtlcs >= r.spec.MaxParts &&
		r.spec.MaxParts != 0 {

		return nil, errors.New("maximum parts in flight")
	}

	if amt < r.lastRemain {
		r.lastFailed = 0
	}
	r.lastRemain = amt

	var (
		bestRoute *route.Route
		bestScore = -1.0
		lastErr   error
	)

	for _, shard := range r.shardCandidates(amt) {
		rt, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		probability := r.routeProbability(rt)
		fee := float64(routeFee(rt))

		// Expected progress rewards large shards, while the exponent makes
		// reliability more important than raw size. A modest fee term
		// breaks ties without steering traffic toward fragile cheap paths.
		progress := float64(shard) *
			math.Pow(probability, 1.35)
		feeCost := fee * 25
		score := progress - feeCost

		if score > bestScore {
			bestScore = score
			bestRoute = rt
		}
	}

	if bestRoute == nil {
		if lastErr == nil {
			lastErr = errors.New("no route found")
		}

		return nil, lastErr
	}

	r.reserve(bestRoute)
	return bestRoute, nil
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(
	key candidateEdgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordSuccess(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]

	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	// In a bimodal channel, passing a meaningful amount is evidence that
	// the directed balance lies in the high mode.
	estimate := amt
	remaining := edge.capacity - amt
	if remaining > 0 {
		estimate += remaining * 3 / 4
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]

	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	// A liquidity miss in a bimodal channel strongly favors the depleted
	// mode, while still permitting useful retries below the failed amount.
	estimate := amt * 30 / 100
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(
	rt *route.Route, source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) addPenalty(
	key candidateEdgeKey, amt lnwire.MilliSatoshi,
	cost float64) {

	current := r.penalties[key]

	if current.threshold == 0 ||
		amt < current.threshold {

		current.threshold = amt
	}
	current.cost += cost
	if current.cost > riskCostMsat*4 {
		current.cost = riskCostMsat * 4
	}

	r.penalties[key] = current
}

func (r *candidateRouter) rewardEdge(
	key candidateEdgeKey) {

	penalty, ok := r.penalties[key]
	if !ok {
		return
	}

	penalty.cost *= 0.20
	if penalty.cost < 1 {
		delete(r.penalties, key)
		return
	}

	r.penalties[key] = penalty
}

func (r *candidateRouter) ReportAttempt(
	_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			r.recordSuccess(key, routeAmount(rt, i))
			r.rewardEdge(key)
		}

		r.lastFailed = 0
		return nil
	}

	delivered := deliveredAmount(rt)
	if delivered > 0 {
		r.lastFailed = delivered
	}

	failIndex := r.failureIndex(
		rt, result.FailureSource,
	)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if ok {
				r.addPenalty(
					key, routeAmount(rt, i),
					riskCostMsat/3,
				)
			}
		}

		return nil
	}

	// Every edge before the failing node carried the HTLC successfully.
	for i := 0; i < failIndex; i++ {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		r.recordSuccess(key, routeAmount(rt, i))
		r.rewardEdge(key)
	}

	key, ok := r.routeEdge(rt, failIndex)
	if !ok {
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		// These failures are deterministic for the advertised policy and
		// constructed route, so retrying this directed edge is wasteful.
		r.blocked[key] = true

	case lnwire.CodeTemporaryChannelFailure:
		r.recordFailure(
			key, routeAmount(rt, failIndex),
		)
		r.addPenalty(
			key, routeAmount(rt, failIndex),
			riskCostMsat,
		)

	default:
		// Unknown failures should encourage route exploration without
		// creating a permanent liquidity bound from ambiguous evidence.
		r.addPenalty(
			key, routeAmount(rt, failIndex),
			riskCostMsat/2,
		)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta    = uint32(40)
	riskCostMsat      = 300000.0
	minProbability    = 0.003
	maxProbability    = 0.995
	lowerRetryFactor  = 0.62
	minShardMsat      = lnwire.MilliSatoshi(10_000)
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedCandidateBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]liquidityBelief
	failedNow     map[candidateEdgeKey]lnwire.MilliSatoshi
	blocked       map[candidateEdgeKey]bool
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	used          map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty  map[candidateEdgeKey]float64

	baseShard lnwire.MilliSatoshi
	lastFailed lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeByKey:      make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]liquidityBelief),
		failedNow:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		blocked:        make(map[candidateEdgeKey]bool),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		used:           make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:   make(map[candidateEdgeKey]float64),
	}

	parts := spec.MaxParts
	if parts == 0 {
		parts = 1
	}

	switch {
	case spec.Amount < 25_000_000:
		parts = 1
	case spec.Amount < 100_000_000 && parts > 2:
		parts = 2
	case spec.Amount < 300_000_000 && parts > 4:
		parts = 4
	}

	r.baseShard = ceilDiv(
		spec.Amount, lnwire.MilliSatoshi(parts),
	)

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedCandidateBeliefs.Lock()
	for key, belief := range sharedCandidateBeliefs.values {
		if _, ok := r.edgeByKey[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedCandidateBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}

	return (a + b - 1) / b
}

func subtractFloor(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b >= a {
		return 0
	}

	return a - b
}

func clampProbability(p float64) float64 {
	if p < minProbability {
		return minProbability
	}
	if p > maxProbability {
		return maxProbability
	}

	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.51 * math.Exp(-x/0.024)
	highMode := 0.475 / (1 + math.Exp(15*(x-0.80)))

	return clampProbability(0.004 + lowMode + highMode)
}

func (r *candidateRouter) available(edge *candidateEdge) lnwire.MilliSatoshi {
	available := edge.capacity
	available = subtractFloor(available, r.used[edge.key])
	available = subtractFloor(available, r.reserved[edge.key])

	if edge.key.from == r.source {
		local := r.localBalances[edge.key.chanID]
		local = subtractFloor(local, r.used[edge.key])
		local = subtractFloor(local, r.reserved[edge.key])
		if local < available {
			available = local
		}
	}

	return available
}

func (r *candidateRouter) adjustedBelief(
	key candidateEdgeKey) liquidityBelief {

	belief := r.beliefs[key]
	consumed := r.used[key]

	belief.lowerOK = subtractFloor(belief.lowerOK, consumed)
	belief.estimate = subtractFloor(belief.estimate, consumed)

	if belief.upperBad != 0 {
		if consumed >= belief.upperBad {
			belief.upperBad = 1
		} else {
			belief.upperBad -= consumed
		}
	}

	return belief
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	available := r.available(edge)
	if amt > available {
		return minProbability
	}
	if edge.key.from == r.source {
		return maxProbability
	}

	if upper := r.failedNow[edge.key]; upper != 0 && amt >= upper {
		return minProbability
	}

	belief := r.adjustedBelief(edge.key)
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, available)
	if belief.estimate == 0 && belief.upperBad == 0 {
		return prior
	}

	estimate := belief.estimate
	if estimate == 0 && belief.upperBad != 0 {
		estimate = belief.upperBad * 35 / 100
	}

	width := math.Max(float64(edge.capacity)*0.06, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(estimate))/width,
	))

	if belief.upperBad != 0 && amt >= belief.upperBad {
		point *= 0.08
	}

	return clampProbability(0.48*prior + 0.52*point)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]

	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)

		bestScore, ok := dist[item.node]
		if !ok || item.score > bestScore {
			continue
		}
		if item.arriving != required[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) ||
				amtOver > r.available(edge) {

				continue
			}

			if upper := r.failedNow[edge.key]; upper != 0 &&
				amtOver >= upper {

				continue
			}

			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			} else if sending > r.available(edge) {
				continue
			}

			probability := r.probability(edge, amtOver)
			risk := -math.Log(probability) * riskCostMsat

			utilization := float64(amtOver) /
				math.Max(float64(r.available(edge)), 1)
			capacityCost := utilization * utilization * 20_000

			score := item.score + float64(fee) + risk +
				capacityCost + r.routePenalty[edge.key] + 200

			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge

			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	score, ok := dist[r.source]
	if !ok {
		return nil, 0, errors.New("no route found")
	}
	if _, ok := next[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, score, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to

		if len(path) > len(r.edgeByKey) {
			return nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, ok := r.edgeByKey[key]

	return key, ok
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}

	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.reserved[key] += routeAmount(rt, i)
		}
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func appendShardCandidate(values []lnwire.MilliSatoshi,
	value, floor, ceiling lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if value < floor {
		value = floor
	}
	if value > ceiling {
		value = ceiling
	}
	if value <= 0 {
		return values
	}

	for _, existing := range values {
		diff := existing - value
		if diff < 0 {
			diff = -diff
		}
		if diff <= 1 {
			return values
		}
	}

	return append(values, value)
}

func (r *candidateRouter) shardCandidates(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	floor := ceilDiv(
		amt, lnwire.MilliSatoshi(partsLeft)*2,
	)
	if floor < minShardMsat {
		floor = minShardMsat
	}
	if floor > amt {
		floor = amt
	}

	target := r.baseShard
	if target <= 0 || target > amt {
		target = ceilDiv(amt, lnwire.MilliSatoshi(partsLeft))
	}

	var values []lnwire.MilliSatoshi
	values = appendShardCandidate(values, target, floor, amt)

	if r.lastFailed != 0 {
		retry := lnwire.MilliSatoshi(
			float64(r.lastFailed) * lowerRetryFactor,
		)
		values = appendShardCandidate(values, retry, floor, amt)
	}

	equal := ceilDiv(amt, lnwire.MilliSatoshi(partsLeft))
	values = appendShardCandidate(values, equal, floor, amt)

	for _, factor := range []float64{0.82, 0.68, 0.54} {
		next := lnwire.MilliSatoshi(float64(target) * factor)
		values = appendShardCandidate(values, next, floor, amt)
	}

	values = appendShardCandidate(values, floor, floor, amt)

	return values
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts in flight")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	candidates := r.shardCandidates(amt, partsLeft)

	var (
		bestRoute *route.Route
		bestScore = math.Inf(1)
		lastErr   error
	)

	floor := candidates[len(candidates)-1]
	for _, shard := range candidates {
		rt, score, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		sizeCredit := 35_000 * math.Log1p(
			float64(shard) / math.Max(float64(floor), 1),
		)
		adjusted := score - sizeCredit

		if adjusted < bestScore {
			bestScore = adjusted
			bestRoute = rt
		}
	}

	if bestRoute == nil {
		if lastErr == nil {
			lastErr = errors.New("no route found")
		}

		return nil, lastErr
	}

	r.reserve(bestRoute)
	return bestRoute, nil
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedCandidateBeliefs.Lock()
	sharedCandidateBeliefs.values[key] = belief
	sharedCandidateBeliefs.Unlock()
}

func (r *candidateRouter) recordSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	estimate := amt
	remaining := subtractFloor(edge.capacity, amt)
	estimate += remaining * 4 / 5

	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) consumeBelief(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	belief.lowerOK = subtractFloor(belief.lowerOK, amt)
	belief.estimate = subtractFloor(belief.estimate, amt)

	if belief.upperBad != 0 {
		if amt >= belief.upperBad {
			belief.upperBad = 1
		} else {
			belief.upperBad -= amt
		}
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt * 30 / 100
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.failedNow[key] = amt
	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			amt := routeAmount(rt, i)
			r.recordSuccess(key, amt)
			r.routePenalty[key] *= 0.15
		}

		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			amt := routeAmount(rt, i)
			r.consumeBelief(key, amt)
			r.used[key] += amt
		}

		r.lastFailed = 0
		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if ok {
				r.routePenalty[key] += riskCostMsat * 0.35
			}
		}

		r.lastFailed = deliveredAmount(rt)
		if r.lastFailed > 0 {
			r.baseShard = lnwire.MilliSatoshi(
				float64(r.lastFailed) * lowerRetryFactor,
			)
		}

		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.recordSuccess(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.5
		}
	}

	key, ok := r.routeEdge(rt, failIndex)
	if !ok {
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	default:
		failedAmt := routeAmount(rt, failIndex)
		r.recordFailure(key, failedAmt)
		r.routePenalty[key] += riskCostMsat

		r.lastFailed = deliveredAmount(rt)
		if r.lastFailed > 0 {
			retry := lnwire.MilliSatoshi(
				float64(r.lastFailed) * lowerRetryFactor,
			)
			if retry > 0 {
				r.baseShard = retry
			}
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta   = uint32(40)
	riskCostMsat     = 260000.0
	minProbability   = 0.003
	maxProbability   = 0.995
	lowerRetryFactor = 0.64
	minShardMsat     = lnwire.MilliSatoshi(10_000)
	maxPlanCandidates = 18
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return true
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]liquidityBelief
	blocked       map[candidateEdgeKey]bool
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty  map[candidateEdgeKey]float64

	baseShard           lnwire.MilliSatoshi
	lastRemaining       lnwire.MilliSatoshi
	consecutiveFailures uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		beliefs:       make(map[candidateEdgeKey]liquidityBelief),
		blocked:       make(map[candidateEdgeKey]bool),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:  make(map[candidateEdgeKey]float64),
		lastRemaining: spec.Amount,
	}

	parts := spec.MaxParts
	if parts == 0 {
		parts = 1
	}
	r.baseShard = ceilDiv(spec.Amount, lnwire.MilliSatoshi(parts))

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, ok := r.edgeByKey[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}
	return (a + b - 1) / b
}

func clampProbability(p float64) float64 {
	if p < minProbability {
		return minProbability
	}
	if p > maxProbability {
		return maxProbability
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.51 * math.Exp(-x/0.026)
	highMode := 0.475 / (1 + math.Exp(15*(x-0.79)))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) available(edge *candidateEdge) lnwire.MilliSatoshi {
	available := edge.capacity
	if edge.key.from == r.source {
		available = r.localBalances[edge.key.chanID]
	}

	reserved := r.reserved[edge.key]
	if reserved >= available {
		return 0
	}
	return available - reserved
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if amt > r.available(edge) {
		return minProbability
	}
	if edge.key.from == r.source {
		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		return minProbability
	}
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.07, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(belief.estimate))/width,
	))

	return clampProbability(0.52*prior + 0.48*point)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		bestScore, ok := dist[item.node]
		if !ok || item.score > bestScore {
			continue
		}
		if item.arriving != required[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) || amtOver > r.available(edge) {
				continue
			}

			probability := r.probability(edge, amtOver)
			belief := r.beliefs[edge.key]
			if probability <= minProbability &&
				belief.upperBad != 0 &&
				amtOver >= belief.upperBad {

				continue
			}

			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			}

			if sending > r.available(edge) {
				continue
			}

			risk := -math.Log(probability) * riskCostMsat
			score := item.score + float64(fee) + risk +
				r.routePenalty[edge.key] + 200

			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edgeByKey) {
			return nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, ok := r.edgeByKey[key]

	return key, ok
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.reserved[key] += routeAmount(rt, i)
		}
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func (r *candidateRouter) routeProbability(rt *route.Route) float64 {
	probability := 1.0
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			return minProbability
		}

		edge := r.edgeByKey[key]
		probability *= r.probability(edge, routeAmount(rt, i))
	}

	return clampProbability(probability)
}

func addCandidate(values map[lnwire.MilliSatoshi]struct{},
	value, floor, ceiling lnwire.MilliSatoshi) {

	if value < floor || value > ceiling || value <= 0 {
		return
	}
	values[value] = struct{}{}
}

func (r *candidateRouter) shardCandidates(amt,
	equal lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	floor := equal / 3
	if floor < minShardMsat {
		floor = minShardMsat
	}
	if floor > amt {
		floor = amt
	}

	values := make(map[lnwire.MilliSatoshi]struct{})
	addCandidate(values, amt, floor, amt)
	addCandidate(values, equal, floor, amt)
	addCandidate(values, r.baseShard, floor, amt)
	addCandidate(values, equal*2, floor, amt)
	addCandidate(values, equal*3/2, floor, amt)
	addCandidate(values, equal*4/3, floor, amt)
	addCandidate(values, equal*5/4, floor, amt)
	addCandidate(values, equal*3/4, floor, amt)
	addCandidate(values, equal*2/3, floor, amt)
	addCandidate(values, equal/2, floor, amt)
	addCandidate(values, amt*4/5, floor, amt)
	addCandidate(values, amt*2/3, floor, amt)
	addCandidate(values, amt/2, floor, amt)
	addCandidate(values, amt/3, floor, amt)
	addCandidate(values, floor, floor, amt)

	var bestOK lnwire.MilliSatoshi
	var bestRetry lnwire.MilliSatoshi
	for key, belief := range r.beliefs {
		if r.blocked[key] {
			continue
		}

		if belief.lowerOK >= floor && belief.lowerOK <= amt &&
			belief.lowerOK > bestOK {

			bestOK = belief.lowerOK
		}

		if belief.upperBad != 0 {
			retry := belief.upperBad * 62 / 100
			if retry >= floor && retry <= amt && retry > bestRetry {
				bestRetry = retry
			}
		}
	}

	addCandidate(values, bestOK, floor, amt)
	addCandidate(values, bestRetry, floor, amt)

	candidates := make([]lnwire.MilliSatoshi, 0, len(values))
	for value := range values {
		candidates = append(candidates, value)
	}
	sort.Slice(candidates, func(i, j int) bool {
		return candidates[i] > candidates[j]
	})

	if len(candidates) <= maxPlanCandidates {
		return candidates
	}

	trimmed := append(
		[]lnwire.MilliSatoshi(nil),
		candidates[:maxPlanCandidates-2]...,
	)
	trimmed = append(
		trimmed,
		candidates[len(candidates)-2],
		candidates[len(candidates)-1],
	)

	return trimmed
}

func (r *candidateRouter) planRoute(amt,
	equal lnwire.MilliSatoshi) (*route.Route, error) {

	candidates := r.shardCandidates(amt, equal)

	var bestRoute *route.Route
	bestUtility := math.Inf(-1)
	var lastErr error

	for _, shard := range candidates {
		rt, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		probability := r.routeProbability(rt)
		fees := rt.TotalAmount - deliveredAmount(rt)
		progress := math.Log(
			math.Max(float64(shard)/float64(equal), 0.05),
		)

		utility := math.Log(probability) + 0.48*progress -
			float64(fees)/750000.0

		if shard < equal {
			utility += 0.30 * progress
		}
		if probability >= 0.70 {
			utility += 0.18
		}
		if shard == amt && probability >= 0.45 {
			utility += 0.20
		}

		if bestRoute == nil || utility > bestUtility {
			bestRoute = rt
			bestUtility = utility
		}
	}

	if bestRoute != nil {
		return bestRoute, nil
	}
	if lastErr == nil {
		lastErr = errors.New("no route found")
	}

	return nil, lastErr
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts in flight")
	}

	if amt < r.lastRemaining {
		r.consecutiveFailures = 0
	}
	r.lastRemaining = amt

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	if partsLeft == 0 {
		return nil, errors.New("maximum parts in flight")
	}

	equal := ceilDiv(amt, lnwire.MilliSatoshi(partsLeft))
	if partsLeft == 1 {
		equal = amt
	}

	rt, err := r.planRoute(amt, equal)
	if err != nil {
		return nil, err
	}

	r.reserve(rt)
	return rt, nil
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	estimate := amt + (edge.capacity-amt)*4/5
	if estimate > edge.capacity {
		estimate = edge.capacity
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt * 30 / 100
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.estimate < belief.lowerOK {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			r.recordSuccess(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.20
		}

		delivered := deliveredAmount(rt)
		if delivered > r.baseShard {
			r.baseShard = delivered
		}
		r.consecutiveFailures = 0

		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if ok {
				r.routePenalty[key] += riskCostMsat / 2
			}
		}
		r.consecutiveFailures++
		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.recordSuccess(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.70
		}
	}

	key, ok := r.routeEdge(rt, failIndex)
	if !ok {
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	default:
		failedAmount := routeAmount(rt, failIndex)
		r.recordFailure(key, failedAmount)
		r.routePenalty[key] += riskCostMsat

		retry := deliveredAmount(rt) * 62 / 100
		if retry >= minShardMsat &&
			(r.baseShard == 0 || retry < r.baseShard) {

			r.baseShard = retry
		}
	}

	r.consecutiveFailures++
	if r.consecutiveFailures >= 3 {
		for edgeKey, penalty := range r.routePenalty {
			if edgeKey == key {
				continue
			}
			r.routePenalty[edgeKey] = penalty * 0.85
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta  = 40
	maxRouteAttempts = 72
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved       map[edgeKey]lnwire.MilliSatoshi
	edgeFailures   map[edgeKey]uint32
	policyFailures map[edgeKey]bool
	routeFailures  map[string]uint32
	lastFailedAmt  lnwire.MilliSatoshi
	attempts       uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:          source,
		spec:            spec,
		incomingEdges:   make(map[route.Vertex][]*candidateEdge),
		edges:           make(map[edgeKey]*candidateEdge),
		localBalances:   make(map[uint64]lnwire.MilliSatoshi),
		beliefs:         make(map[edgeKey]liquidityBelief),
		reserved:        make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:    make(map[edgeKey]uint32),
		policyFailures:  make(map[edgeKey]bool),
		routeFailures:   make(map[string]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}
		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := math.Max(float64(edge.capacity)*0.09, 1)
	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))

	confidence := math.Min(0.80, 0.20*float64(belief.samples))
	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
	signature   string
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		requiredAtNode := deliver
		if item.node != r.spec.Target {
			pathEdge := next[item.node]
			if pathEdge == nil {
				continue
			}

			requiredAtNode = requiredAmount(
				item.node, r.spec.Target, deliver, next,
			)
			if requiredAtNode <= 0 {
				continue
			}
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.policyFailures[edge.key] ||
				!edge.usable(requiredAtNode) {

				continue
			}

			total := requiredAtNode + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, requiredAtNode)
			edgeFee := edge.fee(requiredAtNode)
			sending := requiredAtNode + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = requiredAtNode
			}

			reservationRatio := float64(r.reserved[edge.key]) /
				math.Max(float64(edge.capacity), 1)
			failurePenalty := 0.55 *
				math.Min(float64(r.edgeFailures[edge.key]), 6)

			step := -math.Log(probability) +
				float64(edgeFee)/2_500_000 +
				0.012 +
				failurePenalty +
				0.70*reservationRatio

			candidate := item.score + step
			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
			})

			_ = sending
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(r.edges[key], amounts[i])
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
		signature:   routeSignature(keys, deliver),
	}, nil
}

func requiredAmount(node, target route.Vertex,
	deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) lnwire.MilliSatoshi {

	var path []*candidateEdge
	for node != target {
		edge := next[node]
		if edge == nil {
			return 0
		}
		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(next)+1 {
			return 0
		}
	}

	amt := deliver
	for i := len(path) - 1; i > 0; i-- {
		amt += path[i].fee(amt)
	}

	return amt
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	last := len(path) - 1
	amounts[last] = deliver
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func routeSignature(keys []edgeKey,
	deliver lnwire.MilliSatoshi) string {

	var builder strings.Builder
	for _, key := range keys {
		builder.WriteString(strconv.FormatUint(key.chanID, 10))
		builder.WriteByte('/')
	}
	builder.WriteByte('@')
	builder.WriteString(strconv.FormatInt(int64(deliver), 10))

	return builder.String()
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	partCount := lnwire.MilliSatoshi(partsLeft)
	minimum := (amt + partCount - 1) / partCount
	if minimum < 1_000 {
		minimum = 1_000
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 20)

	addCandidate(&values, seen, minimum, minimum, amt)
	addCandidate(&values, seen, minimum*5/4, minimum, amt)
	addCandidate(&values, seen, minimum*3/2, minimum, amt)
	addCandidate(&values, seen, minimum*2, minimum, amt)
	addCandidate(&values, seen, amt/2, minimum, amt)
	addCandidate(&values, seen, amt*2/3, minimum, amt)
	addCandidate(&values, seen, amt*3/4, minimum, amt)
	addCandidate(&values, seen, amt, minimum, amt)

	if r.lastFailedAmt > 0 {
		addCandidate(
			&values, seen, r.lastFailedAmt/2, minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*3/5, minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*2/3, minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*3/4, minimum, amt,
		)
	}

	var bounds []lnwire.MilliSatoshi
	for key, belief := range r.beliefs {
		if r.policyFailures[key] || belief.upperFail <= 1 {
			continue
		}

		for _, factor := range []lnwire.MilliSatoshi{1, 2, 3} {
			bound := belief.upperFail * factor / 4
			if bound >= minimum && bound <= amt {
				bounds = append(bounds, bound)
			}
		}
	}

	sort.Slice(bounds, func(i, j int) bool {
		return bounds[i] > bounds[j]
	})
	if len(bounds) > 8 {
		bounds = bounds[:8]
	}
	for _, bound := range bounds {
		addCandidate(&values, seen, bound, minimum, amt)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] < values[j]
	})

	return values
}

func ceilParts(total, shard lnwire.MilliSatoshi) uint32 {
	if shard <= 0 {
		return math.MaxUint32
	}

	return uint32((total + shard - 1) / shard)
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxRouteAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		partsNeeded := ceilParts(amt, shard)
		if partsNeeded > partsLeft {
			continue
		}

		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		risk := -math.Log(choice.probability)
		repeatPenalty := 1.35 *
			float64(r.routeFailures[choice.signature])
		partPenalty := 0.075 * float64(partsNeeded-1)
		feePenalty := float64(choice.fee) / 2_500_000

		// Prefer reliable, deliberately sized shards. The low part penalty
		// lets reliability dominate while still avoiding needless splits.
		choice.utility = risk + repeatPenalty +
			partPenalty + feePenalty

		if best == nil || choice.utility < best.utility {
			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	for i, key := range best.keys {
		r.reserved[key] += best.amounts[i]
	}
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnForwarded(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.estimate < amt {
		belief.estimate = amt
	}

	optimistic := edge.capacity * 4 / 5
	if belief.estimate < optimistic {
		belief.estimate = (belief.estimate + optimistic) / 2
	}
	if belief.upperFail > 0 && belief.upperFail <= belief.lowerOK {
		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	depletedEstimate := amt / 4
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = depletedEstimate
	} else {
		belief.estimate =
			(3*belief.estimate + depletedEstimate) / 4
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}
	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}
	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]

	// A successful transfer is strong evidence for the liquid mode. Before
	// applying the transfer, infer that a substantial fraction of capacity
	// was available in this direction.
	inferredBefore := maxMSat(belief.lowerOK, amt)
	liquidMode := edge.capacity * 4 / 5
	if inferredBefore < liquidMode {
		inferredBefore = liquidMode
	}

	estimateBefore := maxMSat(belief.estimate, inferredBefore)
	belief.lowerOK = subtractFloor(inferredBefore, amt, 0)
	belief.estimate = subtractFloor(estimateBefore, amt, 0)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	if belief.upperFail > 0 &&
		belief.lowerOK >= belief.upperFail {

		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}
	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func failureEdgeIndex(rt *route.Route,
	failureSource route.Vertex) int {

	if failureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes != failureSource {
			continue
		}

		// A node reports failure for its outgoing channel. The final
		// recipient has no outgoing route edge.
		return i + 1
	}

	return -1
}

func (r *candidateRouter) releaseReservation(keys []edgeKey,
	amounts []lnwire.MilliSatoshi) {

	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	r.releaseReservation(keys, amounts)

	signature := routeSignature(
		keys, rt.Hops[len(rt.Hops)-1].AmtToForward,
	)

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		delete(r.routeFailures, signature)
		r.lastFailedAmt = 0
		return nil
	}

	r.routeFailures[signature]++
	r.lastFailedAmt =
		rt.Hops[len(rt.Hops)-1].AmtToForward

	failIndex := failureEdgeIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(keys) {
		return nil
	}

	// A failure returned by a downstream node proves that every preceding
	// channel carried the HTLC. Record that evidence without shifting
	// liquidity because the failed HTLC is rolled back.
	for i := 0; i < failIndex; i++ {
		r.learnForwarded(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.edgeFailures[key]++
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.edgeFailures[key] += 2
		r.policyFailures[key] = true

	default:
		r.edgeFailures[key]++
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi
	baseFee  lnwire.MilliSatoshi
	feeRate  lnwire.MilliSatoshi
	delta    uint16
	minHTLC  lnwire.MilliSatoshi
	maxHTLC  lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feeRate/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incoming map[route.Vertex][]*candidateEdge
	edges    map[edgeKey]*candidateEdge
	local    map[uint64]lnwire.MilliSatoshi
	beliefs  map[edgeKey]liquidityBelief

	reserved map[edgeKey]lnwire.MilliSatoshi
	failures map[edgeKey]uint32
	broken   map[edgeKey]bool

	lastFailed lnwire.MilliSatoshi
	attempts   uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:   source,
		spec:     spec,
		incoming: make(map[route.Vertex][]*candidateEdge),
		edges:    make(map[edgeKey]*candidateEdge),
		local:    make(map[uint64]lnwire.MilliSatoshi),
		beliefs:  make(map[edgeKey]liquidityBelief),
		reserved: make(map[edgeKey]lnwire.MilliSatoshi),
		failures: make(map[edgeKey]uint32),
		broken:   make(map[edgeKey]bool),
	}
	for id, balance := range localBalances {
		r.local[id] = balance
	}

	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	ctx := context.Background()

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: policy.FeeBaseMSat,
					feeRate: policy.FeeProportionalMillionths,
					delta:   policy.TimeLockDelta,
					minHTLC: policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incoming[node] = append(r.incoming[node], edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	low := 0.50 * math.Exp(-18*x)
	high := 0.495 / (1 + math.Exp(22*(x-0.88)))
	return clampProbability(low + high)
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}
	if edge.key.from == r.source {
		if total <= r.local[edge.key.chanID] {
			return 0.999
		}
		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := math.Max(1, float64(edge.capacity)*0.08)
	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))
	confidence := math.Min(0.82, 0.24*float64(belief.samples))

	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type pathItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type pathQueue []*pathItem

func (q pathQueue) Len() int           { return len(q) }
func (q pathQueue) Less(i, j int) bool { return q[i].score < q[j].score }
func (q pathQueue) Swap(i, j int)      { q[i], q[j] = q[j], q[i] }

func (q *pathQueue) Push(value any) {
	*q = append(*q, value.(*pathItem))
}

func (q *pathQueue) Pop() any {
	old := *q
	item := old[len(old)-1]
	*q = old[:len(old)-1]
	return item
}

type routeChoice struct {
	rt          *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 || r.source == r.spec.Target {
		return nil, errors.New("invalid route request")
	}

	scores := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)
	queue := &pathQueue{}
	heap.Push(queue, &pathItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for queue.Len() > 0 {
		item := heap.Pop(queue).(*pathItem)
		best, ok := scores[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incoming[item.node] {
			if r.broken[edge.key] || !edge.usable(item.amt) {
				continue
			}

			total := item.amt + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.local[edge.key.chanID] {

				continue
			}

			probability := r.probability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			step := -math.Log(probability) +
				float64(edgeFee)/2_500_000 +
				0.012 +
				0.42*float64(r.failures[edge.key])
			candidate := item.score + step

			old, exists := scores[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			scores[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(queue, &pathItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.probability(r.edges[key], amounts[i])
	}

	return &routeChoice{
		rt:          rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, errors.New("incomplete route")
		}
		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route cycle")
		}
	}
	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.delta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}
	if minimum > amt {
		minimum = amt
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 18)

	for _, value := range []lnwire.MilliSatoshi{
		amt,
		amt * 4 / 5,
		amt * 2 / 3,
		amt / 2,
		minimum * 2,
		minimum * 3 / 2,
		minimum,
	} {
		addAmount(&values, seen, value, minimum, amt)
	}

	if r.lastFailed > 0 {
		for _, value := range []lnwire.MilliSatoshi{
			r.lastFailed * 2 / 3,
			r.lastFailed / 2,
			r.lastFailed * 2 / 5,
			r.lastFailed / 3,
			r.lastFailed / 4,
		} {
			addAmount(&values, seen, value, minimum, amt)
		}
	}

	var bounds []lnwire.MilliSatoshi
	for key, belief := range r.beliefs {
		if r.broken[key] {
			continue
		}
		if belief.lowerOK >= minimum && belief.lowerOK <= amt {
			bounds = append(bounds, belief.lowerOK)
		}
		if belief.upperFail > 1 {
			bounds = append(
				bounds,
				belief.upperFail*2/3,
				belief.upperFail/2,
				belief.upperFail/3,
			)
		}
	}

	sort.Slice(bounds, func(i, j int) bool {
		return bounds[i] > bounds[j]
	})
	if len(bounds) > 7 {
		bounds = bounds[:7]
	}
	for _, value := range bounds {
		addAmount(&values, seen, value, minimum, amt)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})
	return values
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= 48 {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		partsNeeded := math.Ceil(
			float64(amt) / float64(shard),
		)
		if partsNeeded > float64(partsLeft) {
			continue
		}

		choice.utility =
			-math.Log(choice.probability)*partsNeeded +
				0.11*(partsNeeded-1) +
				float64(choice.fee)*partsNeeded/2_500_000 +
				0.18*math.Log(float64(shard)/float64(amt))

		if best == nil || choice.utility < best.utility {
			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	for i, key := range best.keys {
		r.reserved[key] += best.amounts[i]
	}
	r.attempts++

	return best.rt, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief
	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	depleted := amt / 4
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = depleted
	} else {
		belief.estimate = (3*belief.estimate + depleted) / 4
	}
	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnProbeSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	if key.from == r.source || r.edges[key] == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.estimate < amt {
		belief.estimate = amt
	}
	if belief.upperFail > 0 && belief.upperFail <= amt {
		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}
	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}
	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	estimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if estimate < optimistic {
		estimate = (estimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(estimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}
	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}
	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}
	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	keys, amounts := routeEdgeData(rt)
	for i, key := range keys {
		if r.reserved[key] <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amounts[i]
		}
	}

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])
			if key.from == r.source {
				balance := r.local[key.chanID]
				if amounts[i] >= balance {
					r.local[key.chanID] = 0
				} else {
					r.local[key.chanID] =
						balance - amounts[i]
				}
			}
			if r.failures[key] > 0 {
				r.failures[key]--
			}
		}

		r.lastFailed = 0
		return nil
	}

	r.lastFailed = rt.Hops[len(rt.Hops)-1].AmtToForward

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	if failIndex < 0 || failIndex >= len(keys) {
		for _, key := range keys {
			if r.failures[key] < 3 {
				r.failures[key]++
			}
		}
		return nil
	}

	for i := 0; i < failIndex; i++ {
		r.learnProbeSuccess(keys[i], amounts[i])
		if r.failures[keys[i]] > 0 {
			r.failures[keys[i]]--
		}
	}

	key := keys[failIndex]
	if r.failures[key] < 12 {
		r.failures[key] += 2
	}

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, amounts[failIndex])

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	maxAttempts    = 72
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved     map[edgeKey]lnwire.MilliSatoshi
	edgeFailures map[edgeKey]uint32
	broken       map[edgeKey]bool
	tried        map[string]bool

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:  make(map[edgeKey]uint32),
		broken:        make(map[edgeKey]bool),
		tried:         make(map[string]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, exists := r.edges[key]; exists {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, exists := sharedBeliefs.values[key]
		if !exists {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(probability float64) float64 {
	switch {
	case probability < 0.005:
		return 0.005
	case probability > 0.985:
		return 0.985
	default:
		return probability
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	ratio := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-18*ratio)
	highMode := 0.495 / (1 + math.Exp(22*(ratio-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := float64(edge.capacity) * 0.10
	if scale < 1 {
		scale = 1
	}

	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))
	confidence := math.Min(0.80, 0.20*float64(belief.samples))

	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(deliver lnwire.MilliSatoshi,
	diversity map[edgeKey]float64) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, exists := score[item.node]
		if !exists || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(item.amt) {
				continue
			}

			total := item.amt + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			failurePenalty := math.Min(
				0.75,
				0.12*float64(r.edgeFailures[edge.key]),
			)
			step := -math.Log(probability) +
				float64(edgeFee)/2_500_000 +
				0.012 +
				failurePenalty +
				diversity[edge.key]

			candidate := item.score + step
			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, exists := next[r.source]; !exists {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(r.edges[key], amounts[i])
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, exists := next[node]
		if !exists {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) baseCandidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) ([]lnwire.MilliSatoshi,
	lnwire.MilliSatoshi) {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}, amt
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}
	if minimum > amt {
		minimum = amt
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 24)

	addCandidate(&values, seen, amt, minimum, amt)
	addCandidate(&values, seen, amt*7/8, minimum, amt)
	addCandidate(&values, seen, amt*3/4, minimum, amt)
	addCandidate(&values, seen, amt*2/3, minimum, amt)
	addCandidate(&values, seen, amt*3/5, minimum, amt)
	addCandidate(&values, seen, amt/2, minimum, amt)
	addCandidate(&values, seen, amt*2/5, minimum, amt)
	addCandidate(&values, seen, amt/3, minimum, amt)
	addCandidate(&values, seen, minimum*2, minimum, amt)
	addCandidate(&values, seen, minimum*3/2, minimum, amt)
	addCandidate(&values, seen, minimum*5/4, minimum, amt)
	addCandidate(&values, seen, minimum, minimum, amt)

	if r.lastFailedAmt > 0 {
		addCandidate(
			&values, seen, r.lastFailedAmt*4/5,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*2/3,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt/2,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt/3,
			minimum, amt,
		)
	}

	var bounds []lnwire.MilliSatoshi
	for key, belief := range r.beliefs {
		if r.broken[key] {
			continue
		}

		switch {
		case belief.upperFail > 1:
			bounds = append(
				bounds,
				belief.upperFail*4/5,
				belief.upperFail*2/3,
			)

		case belief.lowerOK > 0:
			bounds = append(bounds, belief.lowerOK)
		}
	}

	sort.Slice(bounds, func(i, j int) bool {
		return bounds[i] > bounds[j]
	})
	if len(bounds) > 8 {
		bounds = bounds[:8]
	}

	for _, bound := range bounds {
		addCandidate(
			&values, seen, bound, minimum, amt,
		)
	}

	return values, minimum
}

func (r *candidateRouter) edgePlanningLimit(
	edge *candidateEdge) lnwire.MilliSatoshi {

	reserved := r.reserved[edge.key]
	var limit lnwire.MilliSatoshi

	if edge.key.from == r.source {
		limit = r.localBalances[edge.key.chanID]
	} else {
		belief := r.beliefs[edge.key]

		switch {
		case belief.upperFail > 1:
			limit = belief.upperFail - 1

		case belief.lowerOK > 0:
			limit = maxMSat(
				belief.lowerOK,
				belief.estimate,
			)

		case belief.samples > 0 && belief.estimate > 0:
			limit = belief.estimate

		default:
			limit = edge.capacity * 4 / 5
		}
	}

	if limit > edge.capacity {
		limit = edge.capacity
	}
	if edge.maxHTLC > 0 && limit > edge.maxHTLC {
		limit = edge.maxHTLC
	}
	if reserved >= limit {
		return 0
	}

	return limit - reserved
}

func (r *candidateRouter) pathBudget(
	choice *routeChoice) lnwire.MilliSatoshi {

	if choice == nil || choice.deliver <= 0 {
		return 0
	}

	budget := float64(math.MaxInt64)
	proven := true

	for i, key := range choice.keys {
		edge := r.edges[key]
		if edge == nil || choice.amounts[i] <= 0 {
			return 0
		}

		limit := r.edgePlanningLimit(edge)
		if limit <= 0 {
			return 0
		}

		belief := r.beliefs[key]
		if key.from != r.source &&
			(belief.lowerOK == 0 ||
				limit > belief.lowerOK) {

			proven = false
		}

		deliverLimit := float64(choice.deliver) *
			float64(limit) / float64(choice.amounts[i])
		if deliverLimit < budget {
			budget = deliverLimit
		}
	}

	if math.IsInf(budget, 0) || budget <= 0 {
		return 0
	}

	// Unknown corridors are sized below their inferred high-liquidity
	// mode. Proven corridors can be filled more aggressively.
	if proven {
		budget *= 0.97
	} else {
		budget *= 0.82
	}

	if budget > float64(math.MaxInt64) {
		budget = float64(math.MaxInt64)
	}

	return lnwire.MilliSatoshi(budget)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	values, minimum := r.baseCandidateAmounts(amt, partsLeft)
	seen := make(map[lnwire.MilliSatoshi]bool, len(values)+12)
	for _, value := range values {
		seen[value] = true
	}

	// Probe the smallest feasible shard to discover several distinct
	// corridors, then turn each corridor's inferred bottleneck into an
	// unequal shard candidate.
	diversity := make(map[edgeKey]float64)
	for i := 0; i < 6; i++ {
		choice, err := r.findRoute(minimum, diversity)
		if err != nil {
			break
		}

		budget := r.pathBudget(choice)
		addCandidate(
			&values, seen, budget, minimum, amt,
		)
		addCandidate(
			&values, seen, budget*4/5, minimum, amt,
		)

		for _, key := range choice.keys {
			diversity[key] += 0.85
		}
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	if len(values) > 24 {
		values = values[:24]
		if !seen[minimum] {
			values[len(values)-1] = minimum
		}
	}

	return values
}

func routeSignature(choice *routeChoice) string {
	var builder strings.Builder
	builder.Grow(24 + len(choice.keys)*20)
	builder.WriteString(strconv.FormatInt(
		int64(choice.deliver), 10,
	))

	for _, key := range choice.keys {
		builder.WriteByte('/')
		builder.WriteString(strconv.FormatUint(key.chanID, 10))
	}

	return builder.String()
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice
	var repeated *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		diversity := make(map[edgeKey]float64)

		for alternative := 0; alternative < 5; alternative++ {
			choice, err := r.findRoute(shard, diversity)
			if err != nil {
				break
			}

			needed := math.Ceil(
				float64(amt) / float64(shard),
			)
			choice.utility = -math.Log(choice.probability) +
				0.055*(needed-1) +
				float64(choice.fee)/2_500_000

			signature := routeSignature(choice)
			if r.tried[signature] {
				choice.utility += 4.0
				if repeated == nil ||
					choice.utility < repeated.utility {

					repeated = choice
				}
			} else if best == nil ||
				choice.utility < best.utility {

				best = choice
			}

			for _, key := range choice.keys {
				diversity[key] += 0.95
			}
		}
	}

	if best == nil {
		best = repeated
	}
	if best == nil {
		return nil, errors.New("no route found")
	}

	r.tried[routeSignature(best)] = true
	for i, key := range best.keys {
		r.reserved[key] += best.amounts[i]
	}
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	failedEstimate := amt / 4
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = failedEstimate
	} else {
		belief.estimate =
			(3*belief.estimate + failedEstimate) / 4
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}
	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnProbeSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	optimistic := edge.capacity * 9 / 10
	if belief.estimate < optimistic {
		if belief.estimate < amt {
			belief.estimate = amt
		}
		belief.estimate =
			(belief.estimate + optimistic) / 2
	}

	if belief.upperFail > 0 &&
		belief.upperFail <= belief.lowerOK {

		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := belief.estimate
	if preEstimate < amt {
		preEstimate = amt
	}

	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}

	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}

	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	keys, amounts := routeEdgeData(rt)
	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	r.lastFailedAmt =
		rt.Hops[len(rt.Hops)-1].AmtToForward

	if failIndex < 0 || failIndex >= len(keys) {
		return nil
	}

	// Every edge before the failure carried the HTLC successfully. Since
	// the failed attempt unwinds, this is evidence without a net liquidity
	// shift.
	for i := 0; i < failIndex; i++ {
		r.learnProbeSuccess(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	r.edgeFailures[key] += 2

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved map[edgeKey]lnwire.MilliSatoshi

	// paymentUpper records failures observed by this router. Unlike shared
	// beliefs, these bounds are fresh enough to exclude an amount outright.
	// A new payment receives a new router and can cheaply refresh stale shared
	// evidence if background traffic has moved liquidity.
	paymentUpper map[edgeKey]lnwire.MilliSatoshi
	edgeFailures map[edgeKey]uint32
	broken       map[edgeKey]bool

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		paymentUpper:  make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:  make(map[edgeKey]uint32),
		broken:        make(map[edgeKey]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}
		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := float64(edge.capacity) * 0.08
	if scale < 1 {
		scale = 1
	}
	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))

	confidence := math.Min(0.82, 0.20*float64(belief.samples))
	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

func (r *candidateRouter) freshlyImpossible(edge *candidateEdge,
	amt lnwire.MilliSatoshi) bool {

	upper := r.paymentUpper[edge.key]
	return upper > 0 && amt+r.reserved[edge.key] >= upper
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(item.amt) {
				continue
			}
			if r.freshlyImpossible(edge, item.amt) {
				continue
			}

			total := item.amt + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			// Reliability is the primary cost. Capacity enters through the
			// bimodal probability, while fees and hop count break close
			// reliability ties. Only the actually failing edge accumulates
			// the explicit failure penalty.
			step := -math.Log(probability) +
				float64(edgeFee)/3_000_000 +
				0.012 +
				0.24*float64(r.edgeFailures[edge.key])
			candidate := item.score + step

			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(r.edges[key], amounts[i])
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 20)

	// Include both balanced allocations and deliberately unequal shards.
	// The latter allow a large corridor to carry most of the payment while
	// preserving enough part slots for smaller parallel corridors.
	addCandidate(&values, seen, amt, minimum, amt)
	addCandidate(&values, seen, amt*7/8, minimum, amt)
	addCandidate(&values, seen, amt*4/5, minimum, amt)
	addCandidate(&values, seen, amt*3/4, minimum, amt)
	addCandidate(&values, seen, amt*2/3, minimum, amt)
	addCandidate(&values, seen, amt*3/5, minimum, amt)
	addCandidate(&values, seen, amt/2, minimum, amt)
	addCandidate(&values, seen, amt*2/5, minimum, amt)
	addCandidate(&values, seen, amt/3, minimum, amt)
	addCandidate(&values, seen, minimum*2, minimum, amt)
	addCandidate(&values, seen, minimum*3/2, minimum, amt)
	addCandidate(&values, seen, minimum*5/4, minimum, amt)
	addCandidate(&values, seen, minimum, minimum, amt)

	if r.lastFailedAmt > 0 {
		addCandidate(
			&values, seen, r.lastFailedAmt*4/5,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*2/3,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt/2,
			minimum, amt,
		)
	}

	// Fresh failure bounds are especially useful breakpoints. Shared bounds
	// are also considered, but they do not exclude routes because background
	// traffic may have invalidated them between payments.
	var bounds []lnwire.MilliSatoshi
	for key, upper := range r.paymentUpper {
		if r.broken[key] || upper <= 1 {
			continue
		}
		for _, factor := range []lnwire.MilliSatoshi{9, 4, 2} {
			denominator := lnwire.MilliSatoshi(10)
			if factor == 4 {
				denominator = 5
			}
			if factor == 2 {
				denominator = 3
			}
			bound := upper * factor / denominator
			if bound >= minimum && bound <= amt {
				bounds = append(bounds, bound)
			}
		}
	}

	for key, belief := range r.beliefs {
		if r.broken[key] || belief.upperFail <= 1 {
			continue
		}
		bound := belief.upperFail * 4 / 5
		if bound >= minimum && bound <= amt {
			bounds = append(bounds, bound)
		}
	}

	sort.Slice(bounds, func(i, j int) bool {
		return bounds[i] > bounds[j]
	})
	if len(bounds) > 6 {
		bounds = bounds[:6]
	}
	for _, bound := range bounds {
		addCandidate(&values, seen, bound, minimum, amt)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})
	return values
}

func (r *candidateRouter) reserveChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		r.reserved[key] += choice.amounts[i]
	}
}

func (r *candidateRouter) releaseChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		reserved := r.reserved[key]
		if reserved <= choice.amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - choice.amounts[i]
		}
	}
}

// continuationScore performs a bounded one-step route-set lookahead. It tests
// whether the remainder has a plausible route after the candidate's liquidity
// is reserved. This favors unequal allocations across genuinely independent
// corridors instead of discovering every split through failed attempts.
func (r *candidateRouter) continuationScore(choice *routeChoice,
	remaining lnwire.MilliSatoshi, partsLeft uint32) float64 {

	if remaining <= choice.deliver {
		return 0
	}
	if partsLeft <= 1 {
		return 20
	}

	after := remaining - choice.deliver
	slots := partsLeft - 1
	nextMinimum := (after + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)
	if nextMinimum < 1_000 {
		nextMinimum = 1_000
	}

	r.reserveChoice(choice)
	defer r.releaseChoice(choice)

	nextChoice, err := r.findRoute(nextMinimum)
	if err != nil {
		return 8
	}

	// Reward a continuation that uses few of the same directed channels.
	overlap := 0
	used := make(map[edgeKey]bool, len(choice.keys))
	for _, key := range choice.keys {
		used[key] = true
	}
	for _, key := range nextChoice.keys {
		if used[key] {
			overlap++
		}
	}

	return 0.30*-math.Log(nextChoice.probability) +
		0.16*float64(overlap) +
		float64(nextChoice.fee)/6_000_000
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= 48 {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		// Estimate the cost of covering the entire remainder with similarly
		// reliable shards. This prevents a small shard from looking cheap
		// merely because it exposes less liquidity.
		shardsNeeded := float64(amt) / float64(shard)
		risk := -math.Log(choice.probability) * shardsNeeded
		fees := float64(choice.fee) * shardsNeeded / 3_000_000
		partCost := 0.06 * shardsNeeded
		lookahead := r.continuationScore(
			choice, amt, partsLeft,
		)

		choice.utility = risk + fees + partCost + lookahead
		if best == nil || choice.utility < best.utility {
			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.reserveChoice(best)
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	fresh := r.paymentUpper[key]
	if fresh == 0 || amt < fresh {
		r.paymentUpper[key] = amt
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = amt / 4
	} else {
		belief.estimate = (3*belief.estimate + amt/4) / 4
	}
	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}
	belief.samples++
	r.storeBelief(key, belief)
}

// learnProbeSuccess records that an edge accepted an HTLC before a downstream
// failure. Since the attempt did not settle, no liquidity is shifted.
func (r *candidateRouter) learnProbeSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.estimate < amt {
		belief.estimate = amt
	}

	// Under the bimodal model, accepting a meaningful probe is evidence for
	// the liquid mode, but the proven lower bound remains authoritative.
	optimistic := edge.capacity * 4 / 5
	if belief.estimate < optimistic {
		belief.estimate = (belief.estimate + optimistic) / 2
	}
	if belief.upperFail > 0 && belief.upperFail <= belief.lowerOK {
		belief.upperFail = 0
	}
	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}
	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}
	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	if belief.lowerOK >= belief.upperFail && belief.upperFail > 0 {
		belief.upperFail = 0
	}
	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}
	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	keys, amounts := routeEdgeData(rt)
	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	r.lastFailedAmt = rt.Hops[len(rt.Hops)-1].AmtToForward

	if failIndex < 0 || failIndex >= len(keys) {
		// Unknown attribution should mildly discourage the whole path, but
		// must not create false hard liquidity bounds.
		for _, key := range keys {
			r.edgeFailures[key]++
		}
		return nil
	}

	// Every edge before the failing edge accepted the HTLC. Preserve that
	// positive evidence without applying settlement liquidity movement.
	for i := 0; i < failIndex; i++ {
		r.learnProbeSuccess(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	r.edgeFailures[key] += 2

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		// The route was built from the advertised directional policy. Avoid
		// repeating a policy-invalid edge for the remainder of this payment.
		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta   = 40
	maxRouteAttempts = 96
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved       map[edgeKey]lnwire.MilliSatoshi
	edgeFailures   map[edgeKey]uint32
	lastFailureAmt map[edgeKey]lnwire.MilliSatoshi
	broken         map[edgeKey]bool
	routeTries     map[uint64]uint32

	lastFailedDeliver lnwire.MilliSatoshi
	attempts          uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:          source,
		spec:            spec,
		incomingEdges:   make(map[route.Vertex][]*candidateEdge),
		edges:           make(map[edgeKey]*candidateEdge),
		localBalances:   make(map[uint64]lnwire.MilliSatoshi),
		beliefs:         make(map[edgeKey]liquidityBelief),
		reserved:        make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:    make(map[edgeKey]uint32),
		lastFailureAmt:  make(map[edgeKey]lnwire.MilliSatoshi),
		broken:          make(map[edgeKey]bool),
		routeTries:      make(map[uint64]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}

		normalizeBelief(&belief, edge.capacity)
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func normalizeBelief(belief *liquidityBelief,
	capacity lnwire.MilliSatoshi) {

	if belief.lowerOK > capacity {
		belief.lowerOK = capacity
	}
	if belief.estimate > capacity {
		belief.estimate = capacity
	}
	if belief.upperFail > capacity {
		belief.upperFail = 0
	}
	if belief.upperFail > 0 &&
		belief.lowerOK >= belief.upperFail {

		belief.lowerOK = belief.upperFail - 1
	}
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	estimate := belief.estimate
	if estimate == 0 {
		estimate = edge.capacity / 2
	}

	scale := float64(edge.capacity) * 0.08
	if belief.upperFail > belief.lowerOK {
		interval := float64(belief.upperFail - belief.lowerOK)
		if interval/3 < scale {
			scale = interval / 3
		}
	}
	if scale < 1 {
		scale = 1
	}

	point := 1 / (1 + math.Exp(
		(float64(total)-float64(estimate))/scale,
	))

	confidence := math.Min(0.82, 0.20*float64(belief.samples))
	probability := (1-confidence)*prior + confidence*point

	return clampProbability(probability)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
	fingerprint uint64
}

func (r *candidateRouter) failurePenalty(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	failures := r.edgeFailures[edge.key]
	if failures == 0 {
		return 0
	}

	failedAmt := r.lastFailureAmt[edge.key]
	if failedAmt == 0 {
		return 0.20 * float64(failures)
	}

	ratio := float64(amt) / float64(failedAmt)
	switch {
	case ratio >= 0.90:
		return 0.55 * float64(failures)
	case ratio >= 0.55:
		return 0.22 * float64(failures)
	case ratio >= 0.30:
		return 0.08 * float64(failures)
	default:
		return 0.02 * float64(failures)
	}
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(item.amt) {
				continue
			}

			total := item.amt + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			step := -math.Log(probability) +
				float64(edgeFee)/2_500_000 +
				0.012 +
				r.failurePenalty(edge, item.amt)
			candidate := item.score + step

			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(
			r.edges[key], amounts[i],
		)
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
		fingerprint: routeFingerprint(keys, deliver),
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New(
				"route contains a cycle",
			)
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func appendEdgeBreakpoints(values *[]lnwire.MilliSatoshi,
	edge *candidateEdge, belief liquidityBelief) {

	capacity := edge.capacity
	if edge.maxHTLC > 0 && edge.maxHTLC < capacity {
		capacity = edge.maxHTLC
	}

	*values = append(
		*values,
		capacity*9/10,
		capacity*3/4,
	)

	if belief.lowerOK > 0 {
		*values = append(
			*values,
			belief.lowerOK,
			belief.lowerOK*9/10,
		)
	}
	if belief.estimate > 0 {
		*values = append(
			*values,
			belief.estimate*9/10,
			belief.estimate*3/4,
		)
	}
	if belief.upperFail > 1 {
		*values = append(
			*values,
			(belief.upperFail-1)*2/3,
			(belief.upperFail-1)/2,
			(belief.upperFail-1)/3,
		)
	}
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 32)

	addCandidate(&values, seen, amt, minimum, amt)
	addCandidate(&values, seen, amt*4/5, minimum, amt)
	addCandidate(&values, seen, amt*2/3, minimum, amt)
	addCandidate(&values, seen, amt/2, minimum, amt)
	addCandidate(&values, seen, amt/3, minimum, amt)
	addCandidate(&values, seen, minimum*3, minimum, amt)
	addCandidate(&values, seen, minimum*2, minimum, amt)
	addCandidate(&values, seen, minimum*3/2, minimum, amt)
	addCandidate(&values, seen, minimum, minimum, amt)

	if r.lastFailedDeliver > 0 {
		addCandidate(
			&values, seen, r.lastFailedDeliver*3/5,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedDeliver*2/5,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedDeliver/4,
			minimum, amt,
		)
	}

	var breakpoints []lnwire.MilliSatoshi
	for _, edge := range r.incomingEdges[r.spec.Target] {
		if !r.broken[edge.key] {
			appendEdgeBreakpoints(
				&breakpoints, edge, r.beliefs[edge.key],
			)
		}
	}
	for _, edge := range r.edges {
		if edge.key.from != r.source || r.broken[edge.key] {
			continue
		}

		available := r.localBalances[edge.key.chanID] -
			r.reserved[edge.key]
		if available > 0 {
			breakpoints = append(
				breakpoints,
				available*9/10,
				available*3/4,
			)
		}
	}

	sort.Slice(breakpoints, func(i, j int) bool {
		return breakpoints[i] > breakpoints[j]
	})

	added := 0
	for _, breakpoint := range breakpoints {
		before := len(values)
		addCandidate(
			&values, seen, breakpoint, minimum, amt,
		)
		if len(values) > before {
			added++
		}
		if added >= 16 {
			break
		}
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	return values
}

func routeFingerprint(keys []edgeKey,
	deliver lnwire.MilliSatoshi) uint64 {

	const (
		offset = uint64(1469598103934665603)
		prime  = uint64(1099511628211)
	)

	hash := offset
	mix := func(value uint64) {
		for i := 0; i < 8; i++ {
			hash ^= value & 0xff
			hash *= prime
			value >>= 8
		}
	}

	mix(uint64(deliver))
	for _, key := range keys {
		mix(key.chanID)
	}

	return hash
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxRouteAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		requiredParts := uint32(
			(amt + shard - 1) / shard,
		)
		if requiredParts > partsLeft {
			continue
		}

		// Approximate the risk of completing the remaining payment with
		// similarly sized parts. This avoids repeatedly choosing the
		// smallest legal shard merely because one tiny attempt is safe.
		partCount := float64(requiredParts)
		risk := -math.Log(choice.probability)
		feeCost := partCount *
			float64(choice.fee) / 2_500_000
		retryCost := 0.65 * float64(
			r.routeTries[choice.fingerprint],
		)

		choice.utility = partCount*(risk+0.045) +
			feeCost + retryCost

		// Prefer an exact final shard when choices have similar expected
		// completion cost.
		if shard == amt {
			choice.utility -= 0.03
		}

		if best == nil || choice.utility < best.utility {
			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	for i, key := range best.keys {
		r.reserved[key] += best.amounts[i]
	}
	r.routeTries[best.fingerprint]++
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(key edgeKey,
	belief liquidityBelief) {

	edge := r.edges[key]
	if edge != nil {
		normalizeBelief(&belief, edge.capacity)
	}

	r.beliefs[key] = belief
	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	// Under a bimodal prior, a miss is evidence that this direction is
	// likely in its depleted mode. Retain lower-amount retries, but move
	// the point estimate substantially below the failed amount.
	depletedEstimate := amt / 5
	if belief.estimate == 0 ||
		depletedEstimate < belief.estimate {

		belief.estimate = depletedEstimate
	} else {
		belief.estimate =
			(3*belief.estimate + depletedEstimate) / 4
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = belief.upperFail - 1
	}
	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnPass(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	optimistic := edge.capacity * 9 / 10
	if belief.estimate < amt {
		belief.estimate = amt
	}
	if belief.estimate < optimistic {
		belief.estimate =
			(belief.estimate + optimistic) / 2
	}

	if belief.upperFail > 0 && belief.upperFail <= amt {
		belief.upperFail = 0
	}
	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSettlement(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}
	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) releaseReservation(keys []edgeKey,
	amounts []lnwire.MilliSatoshi) {

	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}
}

func failureEdgeIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	r.releaseReservation(keys, amounts)

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSettlement(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		r.lastFailedDeliver = 0
		return nil
	}

	deliver := rt.Hops[len(rt.Hops)-1].AmtToForward
	r.lastFailedDeliver = deliver

	failIndex := failureEdgeIndex(
		rt, result.FailureSource,
	)
	if failIndex < 0 || failIndex >= len(keys) {
		return nil
	}

	// Every edge before the failure source successfully forwarded the
	// attempt. Since the failed HTLC unwinds, this proves a lower bound
	// without moving channel liquidity.
	for i := 0; i < failIndex; i++ {
		r.learnPass(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)
		r.edgeFailures[key]++
		r.lastFailureAmt[key] = failedAmt

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
		r.edgeFailures[key] += 3
		r.lastFailureAmt[key] = failedAmt
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved      map[edgeKey]lnwire.MilliSatoshi
	edgeFailures  map[edgeKey]uint32
	broken        map[edgeKey]bool
	routeFailures map[uint64]uint32

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[edgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		beliefs:        make(map[edgeKey]liquidityBelief),
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:   make(map[edgeKey]uint32),
		broken:         make(map[edgeKey]bool),
		routeFailures:  make(map[uint64]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}
		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := float64(edge.capacity) * 0.08
	if scale < 1 {
		scale = 1
	}
	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))

	confidence := math.Min(0.82, 0.24*float64(belief.samples))
	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	fingerprint uint64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(deliver lnwire.MilliSatoshi,
	banned map[edgeKey]bool) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if banned[edge.key] || r.broken[edge.key] {
				continue
			}

			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			if !edge.usable(sending) {
				continue
			}

			total := sending + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, sending)
			step := -math.Log(probability) +
				float64(edgeFee)/2_500_000 +
				0.012 +
				0.38*float64(r.edgeFailures[edge.key])
			candidate := item.score + step

			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		edge := r.edges[key]
		if edge == nil || !edge.usable(amounts[i]) {
			return nil, errors.New("route violates edge constraints")
		}
		probability *= r.edgeProbability(edge, amounts[i])
	}

	fingerprint := routeFingerprint(keys, deliver)
	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		fingerprint: fingerprint,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		if !edge.usable(amounts[i]) {
			return nil, nil, nil, errors.New(
				"constructed amount violates policy",
			)
		}

		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func routeFingerprint(keys []edgeKey,
	amt lnwire.MilliSatoshi) uint64 {

	hash := uint64(1469598103934665603)
	mix := func(value uint64) {
		hash ^= value
		hash *= 1099511628211
	}

	mix(uint64(amt))
	for _, key := range keys {
		mix(key.chanID)
		for _, value := range key.from {
			mix(uint64(value))
		}
		for _, value := range key.to {
			mix(uint64(value))
		}
	}

	return hash
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := lnwire.MilliSatoshi(1_000)
	if amt < minimum {
		minimum = amt
	}

	average := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 20)

	addCandidate(&values, seen, amt, minimum, amt)
	addCandidate(&values, seen, amt*7/8, minimum, amt)
	addCandidate(&values, seen, amt*3/4, minimum, amt)
	addCandidate(&values, seen, amt*2/3, minimum, amt)
	addCandidate(&values, seen, amt/2, minimum, amt)
	addCandidate(&values, seen, average*3/2, minimum, amt)
	addCandidate(&values, seen, average*5/4, minimum, amt)
	addCandidate(&values, seen, average, minimum, amt)
	addCandidate(&values, seen, average*3/4, minimum, amt)
	addCandidate(&values, seen, average/2, minimum, amt)
	addCandidate(&values, seen, amt/4, minimum, amt)
	addCandidate(&values, seen, amt/8, minimum, amt)

	if r.lastFailedAmt > 0 {
		addCandidate(
			&values, seen, r.lastFailedAmt*3/4,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*2/3,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt/2,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt/3,
			minimum, amt,
		)
	}

	var breakpoints []lnwire.MilliSatoshi
	for key, belief := range r.beliefs {
		if r.broken[key] {
			continue
		}

		if belief.lowerOK > 0 {
			breakpoints = append(
				breakpoints, belief.lowerOK*9/10,
			)
		}
		if belief.upperFail > 1 {
			breakpoints = append(
				breakpoints,
				belief.upperFail*2/3,
				belief.upperFail/2,
			)
		}
		if belief.samples > 0 && belief.estimate > 0 {
			breakpoints = append(
				breakpoints, belief.estimate*3/4,
			)
		}
	}

	sort.Slice(breakpoints, func(i, j int) bool {
		di := absMSat(breakpoints[i] - average)
		dj := absMSat(breakpoints[j] - average)
		return di < dj
	})
	if len(breakpoints) > 6 {
		breakpoints = breakpoints[:6]
	}

	for _, value := range breakpoints {
		addCandidate(
			&values, seen, value, minimum, amt,
		)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})
	return values
}

func absMSat(value lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if value < 0 {
		return -value
	}
	return value
}

func samePath(a, b []edgeKey) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func (r *candidateRouter) routeAlternatives(
	deliver lnwire.MilliSatoshi) []*routeChoice {

	base, err := r.findRoute(deliver, nil)
	if err != nil {
		return nil
	}

	choices := []*routeChoice{base}
	limit := len(base.keys)
	if limit > 7 {
		limit = 7
	}

	for i := 0; i < limit; i++ {
		banned := map[edgeKey]bool{
			base.keys[i]: true,
		}
		choice, err := r.findRoute(deliver, banned)
		if err != nil {
			continue
		}

		duplicate := false
		for _, existing := range choices {
			if samePath(existing.keys, choice.keys) {
				duplicate = true
				break
			}
		}
		if duplicate {
			continue
		}

		choices = append(choices, choice)
		if len(choices) >= 4 {
			break
		}
	}

	return choices
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= 48 {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	average := float64(amt) / float64(partsLeft)
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		for _, choice := range r.routeAlternatives(shard) {
			probabilityCost := -math.Log(choice.probability)
			feeCost := float64(choice.fee) / 2_500_000
			routeRetryCost := 1.35 *
				float64(r.routeFailures[choice.fingerprint])

			shardSize := float64(shard)
			partsPressure := 0.0
			if shardSize < average {
				deficit := (average - shardSize) / average
				partsPressure = 0.55 * deficit * deficit
			} else {
				partsPressure = 0.10 *
					math.Log1p(shardSize/average-1)
			}

			progressReward := 0.16 *
				math.Log1p(shardSize/average)
			choice.utility = probabilityCost + feeCost +
				routeRetryCost + partsPressure -
				progressReward

			if best == nil || choice.utility < best.utility {
				best = choice
			}
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	for i, key := range best.keys {
		r.reserved[key] += best.amounts[i]
	}
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnPass(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.estimate < amt {
		belief.estimate = amt
	}
	if belief.upperFail > 0 && belief.upperFail <= amt {
		belief.upperFail = 0
	}
	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	failureEstimate := amt / 4
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = failureEstimate
	} else {
		belief.estimate = (
			3*belief.estimate + failureEstimate,
		) / 4
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}
	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}
	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}
	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}
	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}
	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}
	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) releaseReservation(keys []edgeKey,
	amounts []lnwire.MilliSatoshi) {

	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	keys, amounts := routeEdgeData(rt)
	r.releaseReservation(keys, amounts)

	deliver := rt.Hops[len(rt.Hops)-1].AmtToForward
	fingerprint := routeFingerprint(keys, deliver)

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		delete(r.routeFailures, fingerprint)
		r.lastFailedAmt = 0
		return nil
	}

	r.routeFailures[fingerprint]++
	r.lastFailedAmt = deliver

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	if failIndex < 0 || failIndex >= len(keys) {
		for _, key := range keys {
			r.edgeFailures[key]++
		}
		return nil
	}

	for i := 0; i < failIndex; i++ {
		r.learnPass(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)
		r.edgeFailures[key] += 3

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
		r.edgeFailures[key] += 8

	default:
		r.edgeFailures[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	riskCostMsat   = 300000.0
	minProbability = 0.003
	maxProbability = 0.995

	lowerRetryFactor = 0.62
	minShardMsat     = lnwire.MilliSatoshi(10_000)
	maxShardQuotes   = 24
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return true
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]liquidityBelief
	blocked       map[candidateEdgeKey]bool
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty  map[candidateEdgeKey]float64

	preferredShard      lnwire.MilliSatoshi
	lastRemaining       lnwire.MilliSatoshi
	consecutiveFailures uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		beliefs:       make(map[candidateEdgeKey]liquidityBelief),
		blocked:       make(map[candidateEdgeKey]bool),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:  make(map[candidateEdgeKey]float64),
		lastRemaining: spec.Amount,
	}

	parts := spec.MaxParts
	if parts == 0 {
		parts = 1
	}
	r.preferredShard = ceilDiv(
		spec.Amount, lnwire.MilliSatoshi(parts),
	)

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, ok := r.edgeByKey[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}
	return (a + b - 1) / b
}

func clampProbability(p float64) float64 {
	switch {
	case p < minProbability:
		return minProbability
	case p > maxProbability:
		return maxProbability
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.51 * math.Exp(-x/0.024)
	highMode := 0.475 / (1 + math.Exp(15*(x-0.79)))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	reserved := r.reserved[edge.key]
	if reserved >= edge.capacity || amt > edge.capacity-reserved {
		return minProbability
	}

	effective := amt + reserved
	if edge.key.from == r.source {
		available := r.localBalances[edge.key.chanID]
		if reserved >= available || amt > available-reserved {
			return minProbability
		}
		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && effective >= belief.upperBad {
		return minProbability
	}
	if reserved == 0 && belief.lowerOK != 0 &&
		amt <= belief.lowerOK {

		return maxProbability
	}

	prior := bimodalPrior(effective, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.065, 1)
	point := 1 / (1 + math.Exp(
		(float64(effective)-float64(belief.estimate))/width,
	))

	weight := 0.48
	if belief.lowerOK != 0 || belief.upperBad != 0 {
		weight = 0.62
	}

	return clampProbability(
		(1-weight)*prior + weight*point,
	)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		bestScore, ok := dist[item.node]
		if !ok || item.score > bestScore {
			continue
		}
		if item.arriving != required[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) {
				continue
			}

			reserved := r.reserved[edge.key]
			if reserved >= edge.capacity ||
				amtOver > edge.capacity-reserved {

				continue
			}

			probability := r.probability(edge, amtOver)
			belief := r.beliefs[edge.key]
			if probability <= minProbability &&
				belief.upperBad != 0 &&
				amtOver+reserved >= belief.upperBad {

				continue
			}

			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			} else {
				available := r.localBalances[edge.key.chanID]
				if reserved >= available ||
					sending > available-reserved {

					continue
				}
			}

			risk := -math.Log(probability) * riskCostMsat
			congestion := 0.0
			if reserved > 0 {
				congestion = 90000 *
					float64(reserved) /
					float64(edge.capacity)
			}

			score := item.score + float64(fee) + risk +
				congestion + r.routePenalty[edge.key] + 200

			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	score, ok := dist[r.source]
	if !ok {
		return nil, 0, errors.New("no route found")
	}
	if _, ok := next[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, score, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edgeByKey) {
			return nil, errors.New("route contains a cycle")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, ok := r.edgeByKey[key]

	return key, ok
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.reserved[key] += routeAmount(rt, i)
		}
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func addShardCandidate(values map[lnwire.MilliSatoshi]struct{},
	value, remaining, minimum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > remaining {
		value = remaining
	}
	if value > 0 {
		values[value] = struct{}{}
	}
}

func distanceFromIdeal(value,
	ideal lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value > ideal {
		return value - ideal
	}
	return ideal - value
}

func (r *candidateRouter) shardCandidates(
	remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	ideal := ceilDiv(
		remaining, lnwire.MilliSatoshi(partsLeft),
	)
	minimum := minShardMsat
	if remaining < minimum {
		minimum = remaining
	}

	values := make(map[lnwire.MilliSatoshi]struct{})
	ratios := []float64{
		0.42, 0.55, 0.68, 0.82, 1.0, 1.18, 1.42, 1.75, 2.2,
	}
	for _, ratio := range ratios {
		addShardCandidate(
			values,
			lnwire.MilliSatoshi(float64(ideal)*ratio),
			remaining, minimum,
		)
	}

	addShardCandidate(
		values, r.preferredShard, remaining, minimum,
	)

	for _, belief := range r.beliefs {
		if belief.lowerOK != 0 {
			addShardCandidate(
				values, belief.lowerOK*97/100,
				remaining, minimum,
			)
		}
		if belief.upperBad != 0 {
			addShardCandidate(
				values,
				lnwire.MilliSatoshi(
					float64(belief.upperBad)*
						lowerRetryFactor,
				),
				remaining, minimum,
			)
		}
		if belief.estimate != 0 {
			addShardCandidate(
				values, belief.estimate*82/100,
				remaining, minimum,
			)
		}
	}

	for key, edge := range r.edgeByKey {
		if key.from != r.source && key.to != r.spec.Target {
			continue
		}

		available := edge.capacity
		if key.from == r.source {
			available = r.localBalances[key.chanID]
		}
		if reserved := r.reserved[key]; reserved < available {
			available -= reserved
		} else {
			continue
		}

		addShardCandidate(
			values, available*72/100, remaining, minimum,
		)
		addShardCandidate(
			values, available*90/100, remaining, minimum,
		)
	}

	candidates := make([]lnwire.MilliSatoshi, 0, len(values))
	for value := range values {
		candidates = append(candidates, value)
	}

	sort.Slice(candidates, func(i, j int) bool {
		di := distanceFromIdeal(candidates[i], ideal)
		dj := distanceFromIdeal(candidates[j], ideal)
		if di == dj {
			return candidates[i] > candidates[j]
		}
		return di < dj
	})

	if len(candidates) > maxShardQuotes {
		candidates = candidates[:maxShardQuotes]
	}

	return candidates
}

func allocationPenalty(shard, ideal,
	remaining lnwire.MilliSatoshi) float64 {

	difference := float64(distanceFromIdeal(shard, ideal))
	weight := 0.0015
	if shard < ideal {
		weight = 0.0022
	}

	penalty := difference * weight
	progress := float64(shard) / math.Max(float64(remaining), 1)
	penalty -= progress * 45000

	return penalty
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts in flight")
	}

	if amt < r.lastRemaining {
		r.consecutiveFailures = 0
	}
	r.lastRemaining = amt

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	if partsLeft == 0 {
		return nil, errors.New("maximum parts in flight")
	}

	ideal := ceilDiv(amt, lnwire.MilliSatoshi(partsLeft))
	candidates := r.shardCandidates(amt, partsLeft)

	var (
		bestRoute *route.Route
		bestScore = math.Inf(1)
		lastErr   error
	)

	for _, shard := range candidates {
		rt, routeScore, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		score := routeScore + allocationPenalty(
			shard, ideal, amt,
		)
		if score < bestScore {
			bestScore = score
			bestRoute = rt
		}
	}

	if bestRoute == nil {
		if lastErr == nil {
			lastErr = errors.New("no route found")
		}
		return nil, lastErr
	}

	r.reserve(bestRoute)
	return bestRoute, nil
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	estimate := amt + (edge.capacity-amt)*4/5
	if estimate > edge.capacity {
		estimate = edge.capacity
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt * 30 / 100
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			r.recordSuccess(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.20
		}

		delivered := deliveredAmount(rt)
		if delivered > 0 {
			r.preferredShard = delivered
		}
		r.consecutiveFailures = 0

		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if ok {
				r.routePenalty[key] += riskCostMsat / 3
			}
		}
		r.consecutiveFailures++
		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.recordSuccess(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.65
		}
	}

	key, ok := r.routeEdge(rt, failIndex)
	if !ok {
		r.consecutiveFailures++
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	default:
		failedAmount := routeAmount(rt, failIndex)
		r.recordFailure(key, failedAmount)
		r.routePenalty[key] += riskCostMsat * 0.72

		delivered := deliveredAmount(rt)
		retry := lnwire.MilliSatoshi(
			float64(delivered) * lowerRetryFactor,
		)
		if retry >= minShardMsat {
			r.preferredShard = retry
		}
	}

	r.consecutiveFailures++
	if r.consecutiveFailures >= 3 {
		for penaltyKey, penalty := range r.routePenalty {
			if penaltyKey != key {
				r.routePenalty[penaltyKey] = penalty * 0.85
			}
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved     map[edgeKey]lnwire.MilliSatoshi
	edgeFailures map[edgeKey]uint32
	broken       map[edgeKey]bool

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:  make(map[edgeKey]uint32),
		broken:        make(map[edgeKey]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, exists := r.edges[key]; exists {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, exists := sharedBeliefs.values[key]
		if !exists {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005

	case p > 0.985:
		return 0.985

	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeAvailable(edge *candidateEdge,
	amt lnwire.MilliSatoshi) bool {

	if r.broken[edge.key] || !edge.usable(amt) {
		return false
	}

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return false
	}

	if edge.key.from == r.source {
		return total <= r.localBalances[edge.key.chanID]
	}

	belief := r.beliefs[edge.key]

	// A failed amount remains unavailable, but smaller probes are allowed.
	// This prevents repeated identical attempts without permanently
	// blacklisting the channel.
	return belief.upperFail == 0 || total < belief.upperFail
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := float64(edge.capacity) * 0.08
	if scale < 1 {
		scale = 1
	}

	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))
	confidence := math.Min(0.82, 0.20*float64(belief.samples))

	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, exists := score[item.node]
		if !exists || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if !r.edgeAvailable(edge, item.amt) {
				continue
			}

			probability := r.edgeProbability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee

			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			step := -math.Log(probability) +
				float64(edgeFee)/2_500_000 +
				0.012 +
				0.22*float64(r.edgeFailures[edge.key])
			candidate := item.score + step

			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, exists := next[r.source]; !exists {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(r.edges[key], amounts[i])
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, exists := next[node]
		if !exists {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to

		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))

	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 26)

	addCandidate(&values, seen, amt, minimum, amt)
	addCandidate(&values, seen, amt*7/8, minimum, amt)
	addCandidate(&values, seen, amt*3/4, minimum, amt)
	addCandidate(&values, seen, amt*2/3, minimum, amt)
	addCandidate(&values, seen, amt/2, minimum, amt)
	addCandidate(&values, seen, amt/3, minimum, amt)
	addCandidate(&values, seen, minimum*2, minimum, amt)
	addCandidate(&values, seen, minimum*3/2, minimum, amt)
	addCandidate(&values, seen, minimum, minimum, amt)

	if r.lastFailedAmt > 0 {
		addCandidate(
			&values, seen, r.lastFailedAmt*4/5,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*2/3,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt/2,
			minimum, amt,
		)
	}

	breakpoints := make([]lnwire.MilliSatoshi, 0, len(r.edges)*2)
	for key, edge := range r.edges {
		if r.broken[key] {
			continue
		}

		available := edge.capacity - r.reserved[key]
		if key.from == r.source {
			available = r.localBalances[key.chanID] -
				r.reserved[key]
		}
		if available >= minimum {
			breakpoints = append(
				breakpoints,
				available*7/8,
				available*3/4,
			)
		}

		belief := r.beliefs[key]
		if belief.lowerOK >= minimum {
			breakpoints = append(
				breakpoints, belief.lowerOK,
			)
		}
		if belief.estimate >= minimum {
			breakpoints = append(
				breakpoints, belief.estimate*9/10,
			)
		}
		if belief.upperFail > minimum {
			breakpoints = append(
				breakpoints, belief.upperFail*4/5,
			)
		}
	}

	sort.Slice(breakpoints, func(i, j int) bool {
		return breakpoints[i] > breakpoints[j]
	})

	added := 0
	for _, value := range breakpoints {
		before := len(values)
		addCandidate(&values, seen, value, minimum, amt)
		if len(values) != before {
			added++
		}
		if added >= 14 {
			break
		}
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	return values
}

func choiceCost(choice *routeChoice) float64 {
	return -math.Log(choice.probability) +
		float64(choice.fee)/2_500_000
}

func (r *candidateRouter) reserveChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		r.reserved[key] += choice.amounts[i]
	}
}

func (r *candidateRouter) releaseChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		value := r.reserved[key]
		if value <= choice.amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = value - choice.amounts[i]
		}
	}
}

func (r *candidateRouter) projectedRemainderCost(
	remaining lnwire.MilliSatoshi, slots uint32) (float64, bool) {

	if remaining <= 0 {
		return 0, true
	}
	if slots == 0 {
		return 0, false
	}

	best := math.Inf(1)
	for _, shard := range r.candidateAmounts(remaining, slots) {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		count := math.Ceil(
			float64(remaining) / float64(shard),
		)
		if count > float64(slots) {
			continue
		}

		cost := choiceCost(choice)*count +
			0.05*(count-1)
		if cost < best {
			best = cost
		}
	}

	return best, !math.IsInf(best, 1)
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= 48 {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		utility := choiceCost(choice)
		remaining := amt - shard

		if remaining > 0 {
			if partsLeft <= 1 {
				continue
			}

			r.reserveChoice(choice)
			remainderCost, feasible := r.projectedRemainderCost(
				remaining, partsLeft-1,
			)
			r.releaseChoice(choice)

			if !feasible {
				continue
			}

			utility += remainderCost
			utility += 0.035 *
				(float64(amt)/float64(shard) - 1)
		}

		choice.utility = utility
		if best == nil ||
			choice.utility < best.utility-1e-12 ||
			(math.Abs(choice.utility-best.utility) <= 1e-12 &&
				choice.deliver > best.deliver) {

			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no jointly feasible route set found")
	}

	r.reserveChoice(best)
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = amt / 4
	} else {
		belief.estimate = (3*belief.estimate + amt/4) / 4
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnPass(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.estimate < amt {
		belief.estimate = amt
	}
	if belief.upperFail > 0 && belief.upperFail <= amt {
		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}

	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}

	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	keys, amounts := routeEdgeData(rt)
	for i, key := range keys {
		value := r.reserved[key]
		if value <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = value - amounts[i]
		}
	}

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	if failIndex < 0 || failIndex >= len(keys) {
		r.lastFailedAmt =
			rt.Hops[len(rt.Hops)-1].AmtToForward

		return nil
	}

	// Every edge before the failing node carried the HTLC successfully.
	// Record that evidence without shifting liquidity because a failed HTLC
	// is rolled back.
	for i := 0; i < failIndex; i++ {
		r.learnPass(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	r.lastFailedAmt =
		rt.Hops[len(rt.Hops)-1].AmtToForward
	r.edgeFailures[key]++

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	riskCostMsat   = 260000.0
	minProbability = 0.003
	maxProbability = 0.995

	lowerRetryFactor = 0.68
	maxNodeLabels    = 12
	maxShardQuotes   = 12
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(
	amt lnwire.MilliSatoshi) bool {

	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]liquidityBelief
	blocked       map[candidateEdgeKey]bool
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	unknownCost   map[candidateEdgeKey]float64

	baseShard           lnwire.MilliSatoshi
	lastRemaining       lnwire.MilliSatoshi
	consecutiveFailures uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		beliefs:       make(map[candidateEdgeKey]liquidityBelief),
		blocked:       make(map[candidateEdgeKey]bool),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		unknownCost:   make(map[candidateEdgeKey]float64),
		lastRemaining: spec.Amount,
	}

	desiredParts := uint32(1)
	switch {
	case spec.Amount > 1_000_000_000:
		desiredParts = 6
	case spec.Amount > 250_000_000:
		desiredParts = 4
	case spec.Amount > 50_000_000:
		desiredParts = 2
	}

	if spec.MaxParts != 0 && desiredParts > spec.MaxParts {
		desiredParts = spec.MaxParts
	}
	if desiredParts == 0 {
		desiredParts = 1
	}

	r.baseShard = ceilDiv(
		spec.Amount, lnwire.MilliSatoshi(desiredParts),
	)

	ctx := context.Background()
	seen := map[route.Vertex]bool{
		source: true,
	}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, exists := r.edgeByKey[key]; exists {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, exists := r.edgeByKey[key]; exists {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}

	return a/b + boolMSat(a%b != 0)
}

func boolMSat(value bool) lnwire.MilliSatoshi {
	if value {
		return 1
	}

	return 0
}

func scaledAmount(amt lnwire.MilliSatoshi,
	factor float64) lnwire.MilliSatoshi {

	if amt <= 0 || factor <= 0 {
		return 0
	}

	value := float64(amt) * factor
	if value >= float64(math.MaxInt64) {
		return lnwire.MilliSatoshi(math.MaxInt64)
	}

	return lnwire.MilliSatoshi(value)
}

func clampProbability(probability float64) float64 {
	if probability < minProbability {
		return minProbability
	}
	if probability > maxProbability {
		return maxProbability
	}

	return probability
}

func bimodalPrior(amt,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	ratio := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-ratio/0.025)
	highMode := 0.48 / (
		1 + math.Exp(14*(ratio-0.78)),
	)

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) availableLocal(
	key candidateEdgeKey) lnwire.MilliSatoshi {

	available := r.localBalances[key.chanID]
	reserved := r.reserved[key]
	if reserved >= available {
		return 0
	}

	return available - reserved
}

func (r *candidateRouter) availableCapacity(
	edge *candidateEdge) lnwire.MilliSatoshi {

	reserved := r.reserved[edge.key]
	if reserved >= edge.capacity {
		return 0
	}

	return edge.capacity - reserved
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if amt > r.availableLocal(edge.key) {
			return minProbability
		}

		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		return minProbability
	}
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.07, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(belief.estimate))/width,
	))

	return clampProbability(0.52*prior + 0.48*point)
}

type pathLabel struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64

	edge  *candidateEdge
	child *pathLabel

	active bool
	index  int
}

type labelQueue []*pathLabel

func (q labelQueue) Len() int {
	return len(q)
}

func (q labelQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q labelQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *labelQueue) Push(value any) {
	label := value.(*pathLabel)
	label.index = len(*q)
	*q = append(*q, label)
}

func (q *labelQueue) Pop() any {
	old := *q
	last := len(old) - 1
	label := old[last]
	old[last] = nil
	label.index = -1
	*q = old[:last]

	return label
}

func labelDominates(a, b *pathLabel) bool {
	return a.score <= b.score && a.amount <= b.amount
}

func admitLabel(labels map[route.Vertex][]*pathLabel,
	candidate *pathLabel) bool {

	nodeLabels := labels[candidate.node]
	for _, existing := range nodeLabels {
		if existing.active && labelDominates(existing, candidate) {
			return false
		}
	}

	activeCount := 0
	for _, existing := range nodeLabels {
		if !existing.active {
			continue
		}

		if labelDominates(candidate, existing) {
			existing.active = false
			continue
		}

		activeCount++
	}

	if activeCount >= maxNodeLabels {
		var worst *pathLabel
		for _, existing := range nodeLabels {
			if !existing.active {
				continue
			}
			if worst == nil || existing.score > worst.score {
				worst = existing
			}
		}

		if worst != nil && candidate.score >= worst.score {
			return false
		}
		if worst != nil {
			worst.active = false
		}
	}

	candidate.active = true
	labels[candidate.node] = append(nodeLabels, candidate)

	return true
}

func (r *candidateRouter) findPath(
	amt lnwire.MilliSatoshi) ([]*candidateEdge, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	target := &pathLabel{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}

	labels := map[route.Vertex][]*pathLabel{
		r.spec.Target: {target},
	}
	pq := &labelQueue{}
	heap.Push(pq, target)

	var sourceLabel *pathLabel

	for pq.Len() != 0 {
		current := heap.Pop(pq).(*pathLabel)
		if !current.active {
			continue
		}
		if current.node == r.source {
			sourceLabel = current
			break
		}

		for _, edge := range r.incomingEdges[current.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOverEdge := current.amount
			if !edge.usable(amtOverEdge) {
				continue
			}
			if amtOverEdge > r.availableCapacity(edge) {
				continue
			}

			probability := r.probability(edge, amtOverEdge)
			belief := r.beliefs[edge.key]
			if belief.upperBad != 0 &&
				amtOverEdge >= belief.upperBad {

				continue
			}

			sending := amtOverEdge
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from == r.source {
				if sending > r.availableLocal(edge.key) {
					continue
				}
			} else {
				fee = edge.fee(amtOverEdge)
				if fee > lnwire.MilliSatoshi(
					math.MaxInt64,
				)-sending {

					continue
				}
				sending += fee
			}

			score := current.score + float64(fee) +
				(-math.Log(probability) * riskCostMsat) +
				r.unknownCost[edge.key] + 200

			next := &pathLabel{
				node:   edge.key.from,
				amount: sending,
				score:  score,
				edge:   edge,
				child:  current,
			}
			if !admitLabel(labels, next) {
				continue
			}

			heap.Push(pq, next)
		}
	}

	if sourceLabel == nil {
		return nil, 0, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, 8)
	for label := sourceLabel; label != nil &&
		label.node != r.spec.Target; label = label.child {

		if label.edge == nil || label.child == nil {
			return nil, 0, errors.New("broken path label")
		}

		path = append(path, label.edge)
		if len(path) > len(r.edgeByKey) {
			return nil, 0, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, 0, errors.New("empty route")
	}

	return path, sourceLabel.score, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		fee := forwardingEdge.fee(amtOver[i+1])
		if fee > lnwire.MilliSatoshi(
			math.MaxInt64,
		)-amtOver[i+1] {

			return nil, errors.New("route amount overflow")
		}

		amtOver[i] = amtOver[i+1] + fee
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	path, score, err := r.findPath(amt)
	if err != nil {
		return nil, 0, err
	}

	rt, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, 0, err
	}

	return rt, score, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, exists := r.edgeByKey[key]

	return key, exists
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(
	rt *route.Route) lnwire.MilliSatoshi {

	if len(rt.Hops) == 0 {
		return 0
	}

	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, exists := r.routeEdge(rt, i)
		if !exists {
			continue
		}

		r.reserved[key] += routeAmount(rt, i)
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, exists := r.routeEdge(rt, i)
		if !exists {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func appendShardCandidate(candidates *[]lnwire.MilliSatoshi,
	value, minimum, maximum lnwire.MilliSatoshi) {

	if value < minimum || value > maximum || value <= 0 {
		return
	}

	*candidates = append(*candidates, value)
}

func uniqueShardCandidates(
	values []lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	sort.Slice(values, func(i, j int) bool {
		return values[i] < values[j]
	})

	result := values[:0]
	for _, value := range values {
		if len(result) != 0 &&
			result[len(result)-1] == value {

			continue
		}
		result = append(result, value)
	}

	if len(result) <= maxShardQuotes {
		return result
	}

	sampled := make([]lnwire.MilliSatoshi, 0, maxShardQuotes)
	for i := 0; i < maxShardQuotes; i++ {
		index := i * (len(result) - 1) /
			(maxShardQuotes - 1)
		value := result[index]
		if len(sampled) == 0 ||
			sampled[len(sampled)-1] != value {

			sampled = append(sampled, value)
		}
	}

	return sampled
}

func (r *candidateRouter) shardCandidates(
	remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	minimum := ceilDiv(
		remaining, lnwire.MilliSatoshi(partsLeft),
	)

	base := r.baseShard
	if base < minimum {
		base = minimum
	}
	if base > remaining {
		base = remaining
	}

	values := make([]lnwire.MilliSatoshi, 0, 16)
	appendShardCandidate(
		&values, minimum, minimum, remaining,
	)
	appendShardCandidate(
		&values, base, minimum, remaining,
	)

	for _, factor := range []float64{
		1.18, 1.42, 1.75, 2.15, 2.75,
	} {
		appendShardCandidate(
			&values, scaledAmount(base, factor),
			minimum, remaining,
		)
	}

	if partsLeft <= 3 {
		appendShardCandidate(
			&values, remaining, minimum, remaining,
		)
	}

	var largestKnownOK lnwire.MilliSatoshi
	var largestEstimate lnwire.MilliSatoshi
	var lowerRetry lnwire.MilliSatoshi

	for _, belief := range r.beliefs {
		if belief.lowerOK >= minimum &&
			belief.lowerOK <= remaining &&
			belief.lowerOK > largestKnownOK {

			largestKnownOK = belief.lowerOK
		}

		if belief.estimate >= minimum &&
			belief.estimate <= remaining &&
			belief.estimate > largestEstimate {

			largestEstimate = belief.estimate
		}

		if belief.upperBad != 0 {
			retry := scaledAmount(
				belief.upperBad, lowerRetryFactor,
			)
			if retry >= minimum && retry <= remaining &&
				retry > lowerRetry {

				lowerRetry = retry
			}
		}
	}

	appendShardCandidate(
		&values, largestKnownOK, minimum, remaining,
	)
	appendShardCandidate(
		&values, largestEstimate, minimum, remaining,
	)
	appendShardCandidate(
		&values, lowerRetry, minimum, remaining,
	)

	return uniqueShardCandidates(values)
}

func (r *candidateRouter) routeQuality(
	rt *route.Route,
	searchScore float64,
	minimum lnwire.MilliSatoshi) float64 {

	delivered := deliveredAmount(rt)
	if delivered <= 0 {
		return math.Inf(-1)
	}

	logProbability := 0.0
	fees := rt.TotalAmount - delivered

	for i := range rt.Hops {
		key, exists := r.routeEdge(rt, i)
		if !exists {
			return math.Inf(-1)
		}

		edge := r.edgeByKey[key]
		probability := r.probability(
			edge, routeAmount(rt, i),
		)
		logProbability += math.Log(probability)
	}

	sizeGain := math.Log(
		float64(delivered) / float64(minimum),
	)

	return logProbability + 0.88*sizeGain -
		float64(fees)/5_000_000 -
		searchScore/50_000_000
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 {
		return nil, errors.New("multipart limit is zero")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts in flight")
	}

	if amt < r.lastRemaining {
		r.consecutiveFailures = 0
	}
	r.lastRemaining = amt

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	minimum := ceilDiv(
		amt, lnwire.MilliSatoshi(partsLeft),
	)

	var bestRoute *route.Route
	bestQuality := math.Inf(-1)
	var lastErr error

	for _, shard := range r.shardCandidates(
		amt, partsLeft,
	) {
		rt, score, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		quality := r.routeQuality(rt, score, minimum)
		if bestRoute == nil || quality > bestQuality {
			bestRoute = rt
			bestQuality = quality
		}
	}

	if bestRoute == nil {
		if lastErr == nil {
			lastErr = errors.New("no route found")
		}

		return nil, lastErr
	}

	r.reserve(bestRoute)

	return bestRoute, nil
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(
	key candidateEdgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordSuccess(
	key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	estimate := amt
	remaining := edge.capacity - amt
	if remaining > 0 {
		estimate += remaining * 3 / 4
	}
	if estimate > edge.capacity {
		estimate = edge.capacity
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(
	key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt * 35 / 100
	if belief.estimate == 0 ||
		estimate < belief.estimate {

		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(
	rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) penalizeUnknownRoute(
	rt *route.Route) {

	for i := range rt.Hops {
		key, exists := r.routeEdge(rt, i)
		if !exists {
			continue
		}

		r.unknownCost[key] += riskCostMsat / 3
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64,
	rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("attempt route is nil")
	}

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, exists := r.routeEdge(rt, i)
			if !exists {
				continue
			}

			r.recordSuccess(key, routeAmount(rt, i))
			r.unknownCost[key] *= 0.20
		}

		r.consecutiveFailures = 0
		return nil
	}

	failIndex := r.failureIndex(
		rt, result.FailureSource,
	)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		r.penalizeUnknownRoute(rt)
		r.consecutiveFailures++
		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, exists := r.routeEdge(rt, i)
		if !exists {
			continue
		}

		r.recordSuccess(key, routeAmount(rt, i))
		r.unknownCost[key] *= 0.50
	}

	key, exists := r.routeEdge(rt, failIndex)
	if !exists {
		r.consecutiveFailures++
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	case lnwire.CodeTemporaryChannelFailure:
		r.recordFailure(
			key, routeAmount(rt, failIndex),
		)

	default:
		r.recordFailure(
			key, routeAmount(rt, failIndex),
		)
		r.unknownCost[key] += riskCostMsat / 2
	}

	r.consecutiveFailures++

	delivered := deliveredAmount(rt)
	retry := scaledAmount(
		delivered, lowerRetryFactor,
	)
	if retry > 0 && retry < r.baseShard {
		r.baseShard = retry
	}

	return nil
}

func (r *candidateRouter) String() string {
	return fmt.Sprintf(
		"candidateRouter(source=%v,target=%v)",
		r.source, r.spec.Target,
	)
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	riskCostMsat   = 275000.0
	minProbability = 0.003
	maxProbability = 0.995

	minShardMsat = lnwire.MilliSatoshi(10_000)
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedCandidateBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	localSpent    map[uint64]lnwire.MilliSatoshi

	beliefs      map[candidateEdgeKey]liquidityBelief
	blocked      map[candidateEdgeKey]bool
	reserved     map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty map[candidateEdgeKey]float64

	baseShard           lnwire.MilliSatoshi
	lastRemaining       lnwire.MilliSatoshi
	consecutiveFailures uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeByKey:      make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		localSpent:     make(map[uint64]lnwire.MilliSatoshi),
		beliefs:        make(map[candidateEdgeKey]liquidityBelief),
		blocked:        make(map[candidateEdgeKey]bool),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:   make(map[candidateEdgeKey]float64),
		lastRemaining:  spec.Amount,
	}

	parts := spec.MaxParts
	if parts == 0 {
		parts = 1
	}
	switch {
	case spec.Amount <= 50_000_000 && parts > 1:
		parts = 1
	case spec.Amount <= 250_000_000 && parts > 3:
		parts = 3
	case spec.Amount <= 1_000_000_000 && parts > 6:
		parts = 6
	case parts > 10:
		parts = 10
	}
	r.baseShard = ceilDiv(
		spec.Amount, lnwire.MilliSatoshi(parts),
	)

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, exists := r.edgeByKey[key]; exists {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedCandidateBeliefs.Lock()
	for key, belief := range sharedCandidateBeliefs.values {
		if _, exists := r.edgeByKey[key]; exists {
			r.beliefs[key] = belief
		}
	}
	sharedCandidateBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}
	return (a + b - 1) / b
}

func clampProbability(p float64) float64 {
	switch {
	case p < minProbability:
		return minProbability
	case p > maxProbability:
		return maxProbability
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.51 * math.Exp(-x/0.026)
	highMode := 0.475 / (1 + math.Exp(15*(x-0.79)))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) localAvailable(
	key candidateEdgeKey) lnwire.MilliSatoshi {

	available := r.localBalances[key.chanID]
	spent := r.localSpent[key.chanID]
	if spent >= available {
		return 0
	}
	available -= spent

	reserved := r.reserved[key]
	if reserved >= available {
		return 0
	}

	return available - reserved
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if amt > r.localAvailable(edge.key) {
			return minProbability
		}
		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		return minProbability
	}
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.065, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(belief.estimate))/width,
	))

	weight := 0.52
	if belief.lowerOK != 0 || belief.upperBad != 0 {
		weight = 0.68
	}

	return clampProbability(
		(1-weight)*prior + weight*point,
	)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)

		bestScore, exists := dist[item.node]
		if !exists || item.score > bestScore {
			continue
		}
		if item.arriving != required[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) {
				continue
			}

			reserved := r.reserved[edge.key]
			if reserved >= edge.capacity ||
				amtOver > edge.capacity-reserved {

				continue
			}

			if edge.key.from == r.source &&
				amtOver > r.localAvailable(edge.key) {

				continue
			}

			probability := r.probability(edge, amtOver)
			belief := r.beliefs[edge.key]
			if probability <= minProbability &&
				belief.upperBad != 0 {

				continue
			}

			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			}

			risk := -math.Log(probability) * riskCostMsat
			score := item.score + float64(fee) + risk +
				r.routePenalty[edge.key] + 200

			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	score, exists := dist[r.source]
	if !exists {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, score, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, exists := next[node]
		if !exists {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edgeByKey) {
			return nil, errors.New("route contains a cycle")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amounts[i] = amounts[i+1] +
			forwardingEdge.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < last {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, exists := r.edgeByKey[key]

	return key, exists
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) routeProbability(rt *route.Route) float64 {
	probability := 1.0

	for i := range rt.Hops {
		key, exists := r.routeEdge(rt, i)
		if !exists {
			return minProbability
		}

		edge := r.edgeByKey[key]
		probability *= r.probability(
			edge, routeAmount(rt, i),
		)
	}

	return clampProbability(probability)
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, exists := r.routeEdge(rt, i)
		if exists {
			r.reserved[key] += routeAmount(rt, i)
		}
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, exists := r.routeEdge(rt, i)
		if !exists {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func appendCandidate(candidates *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, amt,
	limit lnwire.MilliSatoshi) {

	if amt <= 0 || amt > limit || seen[amt] {
		return
	}
	if amt < minShardMsat && limit >= minShardMsat {
		return
	}

	seen[amt] = true
	*candidates = append(*candidates, amt)
}

func (r *candidateRouter) shardCandidates(
	amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	seen := make(map[lnwire.MilliSatoshi]bool)
	candidates := make([]lnwire.MilliSatoshi, 0, 28)

	appendCandidate(&candidates, seen, amt, amt)
	appendCandidate(&candidates, seen, r.baseShard, amt)

	divisor := partsLeft
	if divisor == 0 {
		divisor = 1
	}
	average := ceilDiv(amt, lnwire.MilliSatoshi(divisor))
	appendCandidate(&candidates, seen, average, amt)

	for _, ratio := range []struct {
		numerator   int64
		denominator int64
	}{
		{5, 6},
		{3, 4},
		{2, 3},
		{1, 2},
		{2, 5},
		{1, 3},
		{1, 4},
	} {
		value := lnwire.MilliSatoshi(
			int64(amt) * ratio.numerator /
				ratio.denominator,
		)
		appendCandidate(&candidates, seen, value, amt)
	}

	appendCandidate(
		&candidates, seen, r.baseShard*4/5, amt,
	)
	appendCandidate(
		&candidates, seen, r.baseShard*2/3, amt,
	)
	appendCandidate(
		&candidates, seen, r.baseShard/2, amt,
	)

	addedEvidence := 0
	for key, belief := range r.beliefs {
		if addedEvidence >= 16 {
			break
		}
		if r.blocked[key] {
			continue
		}

		before := len(candidates)
		if belief.lowerOK != 0 {
			appendCandidate(
				&candidates, seen,
				belief.lowerOK*97/100, amt,
			)
		}
		if belief.estimate != 0 {
			appendCandidate(
				&candidates, seen,
				belief.estimate*9/10, amt,
			)
		}
		if belief.upperBad > minShardMsat {
			appendCandidate(
				&candidates, seen,
				belief.upperBad*2/3, amt,
			)
			appendCandidate(
				&candidates, seen,
				belief.upperBad*9/20, amt,
			)
		}
		if len(candidates) != before {
			addedEvidence++
		}
	}

	if amt < minShardMsat {
		appendCandidate(&candidates, seen, amt, amt)
	}

	return candidates
}

func routeFees(rt *route.Route) lnwire.MilliSatoshi {
	delivered := deliveredAmount(rt)
	if rt.TotalAmount <= delivered {
		return 0
	}
	return rt.TotalAmount - delivered
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if inFlightHtlcs >= r.spec.MaxParts &&
		r.spec.MaxParts != 0 {

		return nil, errors.New("maximum parts in flight")
	}

	if amt < r.lastRemaining {
		r.consecutiveFailures = 0
	}
	r.lastRemaining = amt

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	candidates := r.shardCandidates(amt, partsLeft)

	var (
		bestRoute   *route.Route
		bestUtility = math.Inf(-1)
		lastErr     error
	)

	for _, shard := range candidates {
		rt, pathScore, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		probability := r.routeProbability(rt)
		fees := routeFees(rt)

		utility := math.Log(float64(shard)+1) +
			1.85*math.Log(probability) -
			float64(fees)/2_000_000 -
			pathScore/(riskCostMsat*45)

		if shard == amt {
			utility += 0.42
		}
		if shard >= amt*3/4 {
			utility += 0.08
		}
		if r.consecutiveFailures >= 2 &&
			shard < r.baseShard {

			utility += 0.18
		}

		if utility > bestUtility {
			bestUtility = utility
			bestRoute = rt
		}
	}

	if bestRoute == nil {
		if lastErr == nil {
			lastErr = errors.New("no route found")
		}
		return nil, lastErr
	}

	r.reserve(bestRoute)
	return bestRoute, nil
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	edge := r.edgeByKey[key]
	if edge != nil {
		if belief.lowerOK > edge.capacity {
			belief.lowerOK = edge.capacity
		}
		if belief.estimate > edge.capacity {
			belief.estimate = edge.capacity
		}
		if belief.upperBad > edge.capacity {
			belief.upperBad = edge.capacity
		}
	}

	r.beliefs[key] = belief

	sharedCandidateBeliefs.Lock()
	sharedCandidateBeliefs.values[key] = belief
	sharedCandidateBeliefs.Unlock()
}

func (r *candidateRouter) recordProbeSuccess(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	inferred := amt
	if edge.capacity > amt {
		inferred += (edge.capacity - amt) * 4 / 5
	}
	if inferred > belief.estimate {
		belief.estimate = inferred
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt * 3 / 10
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.estimate < belief.lowerOK {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) consumeLiquidity(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil {
		return
	}
	if key.from == r.source {
		r.localSpent[key.chanID] += amt
		return
	}

	belief := r.beliefs[key]
	preEstimate := belief.estimate
	if preEstimate < amt {
		preEstimate = amt
	}
	if preEstimate == amt && edge.capacity > amt {
		preEstimate += (edge.capacity - amt) * 4 / 5
	}

	if preEstimate > amt {
		belief.estimate = preEstimate - amt
	} else {
		belief.estimate = 0
	}

	if belief.lowerOK > amt {
		belief.lowerOK -= amt
	} else {
		belief.lowerOK = 0
	}

	if belief.upperBad > amt {
		belief.upperBad -= amt
	} else {
		belief.upperBad = 0
	}

	r.saveBelief(key, belief)
	r.creditReverse(key, amt)
}

func (r *candidateRouter) creditReverse(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	reverse := candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	edge := r.edgeByKey[reverse]
	if edge == nil || reverse.from == r.source {
		return
	}

	belief := r.beliefs[reverse]
	if belief.estimate+amt > edge.capacity {
		belief.estimate = edge.capacity
	} else {
		belief.estimate += amt
	}

	if belief.lowerOK+amt > edge.capacity {
		belief.lowerOK = edge.capacity
	} else {
		belief.lowerOK += amt
	}

	if belief.upperBad != 0 {
		if belief.upperBad+amt > edge.capacity {
			belief.upperBad = 0
		} else {
			belief.upperBad += amt
		}
	}

	r.saveBelief(reverse, belief)
}

func (r *candidateRouter) failureIndex(
	rt *route.Route, source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, exists := r.routeEdge(rt, i)
			if !exists {
				continue
			}

			amt := routeAmount(rt, i)
			r.recordProbeSuccess(key, amt)
			r.consumeLiquidity(key, amt)
			r.routePenalty[key] *= 0.2
		}

		r.consecutiveFailures = 0
		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, exists := r.routeEdge(rt, i)
			if exists {
				r.routePenalty[key] += riskCostMsat / 3
			}
		}
		r.consecutiveFailures++
		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, exists := r.routeEdge(rt, i)
		if exists {
			r.recordProbeSuccess(
				key, routeAmount(rt, i),
			)
			r.routePenalty[key] *= 0.7
		}
	}

	key, exists := r.routeEdge(rt, failIndex)
	if !exists {
		r.consecutiveFailures++
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	default:
		failedAmount := routeAmount(rt, failIndex)
		r.recordFailure(key, failedAmount)
		r.routePenalty[key] += riskCostMsat

		retry := failedAmount * 2 / 3
		if retry > minShardMsat &&
			(retry < r.baseShard || r.baseShard == 0) {

			r.baseShard = retry
		}
	}

	r.consecutiveFailures++
	if r.consecutiveFailures >= 3 {
		delivered := deliveredAmount(rt)
		retry := delivered * 9 / 20
		if retry >= minShardMsat &&
			retry < r.baseShard {

			r.baseShard = retry
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta   = uint32(40)
	riskCostMsat     = 250000.0
	minProbability   = 0.003
	maxProbability   = 0.995
	lowerRetryFactor = 0.68
	maxShardChoices  = 96
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]liquidityBelief
	blocked       map[candidateEdgeKey]bool
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty  map[candidateEdgeKey]float64

	baseShard           lnwire.MilliSatoshi
	lastRemaining       lnwire.MilliSatoshi
	consecutiveFailures uint32
	failureCeiling      lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[candidateEdgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[candidateEdgeKey]liquidityBelief),
		blocked:       make(map[candidateEdgeKey]bool),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:  make(map[candidateEdgeKey]float64),
		lastRemaining: spec.Amount,
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	parts := uint32(1)
	switch {
	case spec.Amount > 1_000_000_000:
		parts = 6
	case spec.Amount > 250_000_000:
		parts = 4
	case spec.Amount > 50_000_000:
		parts = 2
	}
	if parts > spec.MaxParts {
		parts = spec.MaxParts
	}
	if parts == 0 {
		parts = 1
	}
	r.baseShard = ceilDiv(
		spec.Amount, lnwire.MilliSatoshi(parts),
	)

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, ok := r.edgeByKey[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}
	return (a + b - 1) / b
}

func clampAmount(amt, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if amt < 0 {
		return 0
	}
	if amt > capacity {
		return capacity
	}
	return amt
}

func clampProbability(p float64) float64 {
	if p < minProbability {
		return minProbability
	}
	if p > maxProbability {
		return maxProbability
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-x/0.025)
	highMode := 0.48 / (1 + math.Exp(14*(x-0.78)))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) availableLocal(
	key candidateEdgeKey) lnwire.MilliSatoshi {

	available := r.localBalances[key.chanID]
	reserved := r.reserved[key]
	if reserved >= available {
		return 0
	}
	return available - reserved
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if amt > r.availableLocal(edge.key) {
			return minProbability
		}
		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		return minProbability
	}
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.07, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(belief.estimate))/width,
	))

	weight := 0.48
	if belief.lowerOK != 0 || belief.upperBad != 0 {
		weight = 0.64
	}

	return clampProbability(
		(1-weight)*prior + weight*point,
	)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		bestScore, ok := dist[item.node]
		if !ok || item.score > bestScore {
			continue
		}
		if item.arriving != required[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) {
				continue
			}

			reserved := r.reserved[edge.key]
			if reserved >= edge.capacity ||
				amtOver > edge.capacity-reserved {

				continue
			}

			if edge.key.from == r.source &&
				amtOver > r.availableLocal(edge.key) {

				continue
			}

			belief := r.beliefs[edge.key]
			if belief.upperBad != 0 &&
				amtOver >= belief.upperBad {

				continue
			}

			probability := r.probability(edge, amtOver)
			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			}

			risk := -math.Log(probability) * riskCostMsat
			score := item.score + float64(fee) + risk +
				r.routePenalty[edge.key] + 250

			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edgeByKey) {
			return nil, errors.New("route contains a cycle")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, ok := r.edgeByKey[key]
	return key, ok
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.reserved[key] += routeAmount(rt, i)
		}
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func appendShardChoice(choices *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, candidate, minimum,
	maximum lnwire.MilliSatoshi) {

	if candidate < minimum || candidate > maximum ||
		candidate <= 0 || seen[candidate] ||
		len(*choices) >= maxShardChoices {

		return
	}

	seen[candidate] = true
	*choices = append(*choices, candidate)
}

func (r *candidateRouter) shardChoices(amt,
	minNeeded lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	choices := make([]lnwire.MilliSatoshi, 0, 32)
	seen := make(map[lnwire.MilliSatoshi]bool)

	appendChoice := func(candidate lnwire.MilliSatoshi) {
		appendShardChoice(
			&choices, seen, candidate, minNeeded, amt,
		)
	}

	appendChoice(minNeeded)
	appendChoice(amt)
	appendChoice(r.baseShard)

	for parts := uint32(1); parts <= partsLeft; parts++ {
		appendChoice(ceilDiv(
			amt, lnwire.MilliSatoshi(parts),
		))
	}

	for _, ratio := range []int64{
		90, 82, 74, 68, 60, 52, 45, 38,
	} {
		appendChoice(amt * lnwire.MilliSatoshi(ratio) / 100)
	}

	for _, belief := range r.beliefs {
		if len(choices) >= maxShardChoices {
			break
		}

		appendChoice(belief.lowerOK)
		appendChoice(belief.lowerOK * 9 / 10)
		appendChoice(belief.estimate * 4 / 5)
		if belief.upperBad != 0 {
			appendChoice(belief.upperBad * 2 / 3)
			if belief.upperBad > 1 {
				appendChoice(belief.upperBad - 1)
			}
		}
	}

	if r.failureCeiling != 0 {
		filtered := choices[:0]
		for _, choice := range choices {
			if choice <= r.failureCeiling ||
				choice == minNeeded {

				filtered = append(filtered, choice)
			}
		}
		choices = filtered
	}

	return choices
}

func (r *candidateRouter) routeQuality(rt *route.Route,
	minNeeded lnwire.MilliSatoshi) float64 {

	delivered := deliveredAmount(rt)
	if delivered <= 0 {
		return math.Inf(1)
	}

	negativeLogProbability := 0.0
	penalty := 0.0
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			return math.Inf(1)
		}

		edge := r.edgeByKey[key]
		probability := r.probability(
			edge, routeAmount(rt, i),
		)
		negativeLogProbability -= math.Log(probability)
		penalty += r.routePenalty[key] / riskCostMsat
	}

	fee := rt.TotalAmount - delivered
	feeCost := 60000 * float64(fee) / float64(delivered)

	sizeBenefit := 0.0
	if minNeeded > 0 && delivered > minNeeded {
		sizeBenefit = 0.20 * math.Log(
			float64(delivered) / float64(minNeeded),
		)
	}

	hopCost := 0.004 * float64(len(rt.Hops))
	return negativeLogProbability + feeCost + penalty +
		hopCost - sizeBenefit
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts in flight")
	}

	if amt < r.lastRemaining {
		r.consecutiveFailures = 0
		r.failureCeiling = 0
	}
	r.lastRemaining = amt

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	minNeeded := ceilDiv(
		amt, lnwire.MilliSatoshi(partsLeft),
	)

	choices := r.shardChoices(amt, minNeeded, partsLeft)
	var (
		bestRoute   *route.Route
		bestQuality = math.Inf(1)
		lastErr     error
	)

	for _, shard := range choices {
		rt, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		quality := r.routeQuality(rt, minNeeded)
		if quality < bestQuality {
			bestQuality = quality
			bestRoute = rt
		}
	}

	if bestRoute == nil {
		if lastErr == nil {
			lastErr = errors.New("no route found")
		}
		return nil, lastErr
	}

	r.reserve(bestRoute)
	return bestRoute, nil
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	edge := r.edgeByKey[key]
	if edge != nil {
		belief.lowerOK = clampAmount(
			belief.lowerOK, edge.capacity,
		)
		belief.estimate = clampAmount(
			belief.estimate, edge.capacity,
		)
		if belief.upperBad > edge.capacity {
			belief.upperBad = 0
		}
	}

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordPass(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	estimate := amt + (edge.capacity-amt)*4/5
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) settleLiquidity(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil {
		return
	}

	if key.from == r.source {
		balance := r.localBalances[key.chanID]
		if amt >= balance {
			r.localBalances[key.chanID] = 0
		} else {
			r.localBalances[key.chanID] = balance - amt
		}
		return
	}

	belief := r.beliefs[key]
	provenBefore := belief.lowerOK
	if amt > provenBefore {
		provenBefore = amt
	}

	if provenBefore > amt {
		belief.lowerOK = provenBefore - amt
	} else {
		belief.lowerOK = 0
	}

	if belief.upperBad > amt {
		belief.upperBad -= amt
	} else {
		belief.upperBad = 0
	}

	preEstimate := belief.estimate
	minimumEstimate := amt + (edge.capacity-amt)*4/5
	if preEstimate < minimumEstimate {
		preEstimate = minimumEstimate
	}
	if preEstimate > amt {
		belief.estimate = preEstimate - amt
	} else {
		belief.estimate = 0
	}

	r.saveBelief(key, belief)

	reverseKey := candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edgeByKey[reverseKey]
	if reverseEdge == nil || reverseKey.from == r.source {
		return
	}

	reverse := r.beliefs[reverseKey]
	if reverse.lowerOK < amt {
		reverse.lowerOK = amt
	}
	reverse.estimate = clampAmount(
		reverse.estimate+amt, reverseEdge.capacity,
	)
	if reverse.estimate < reverse.lowerOK {
		reverse.estimate = reverse.lowerOK
	}
	if reverse.upperBad != 0 &&
		reverse.upperBad <= reverse.lowerOK {

		reverse.upperBad = 0
	}

	r.saveBelief(reverseKey, reverse)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt * 35 / 100
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			amt := routeAmount(rt, i)
			r.recordPass(key, amt)
			r.settleLiquidity(key, amt)
			r.routePenalty[key] *= 0.20
		}

		r.consecutiveFailures = 0
		r.failureCeiling = 0
		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if ok {
				r.routePenalty[key] += riskCostMsat / 2
			}
		}
		r.consecutiveFailures++
		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.recordPass(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.75
		}
	}

	key, ok := r.routeEdge(rt, failIndex)
	if !ok {
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	default:
		failedAmount := routeAmount(rt, failIndex)
		r.recordFailure(key, failedAmount)
		r.routePenalty[key] += riskCostMsat
	}

	r.consecutiveFailures++
	if r.consecutiveFailures >= 2 {
		delivered := deliveredAmount(rt)
		ceiling := lnwire.MilliSatoshi(
			float64(delivered) * lowerRetryFactor,
		)
		if ceiling > 0 &&
			(r.failureCeiling == 0 ||
				ceiling < r.failureCeiling) {

			r.failureCeiling = ceiling
		}
		if ceiling > 0 && ceiling < r.baseShard {
			r.baseShard = ceiling
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta   = uint32(40)
	riskCostMsat     = 280000.0
	minProbability   = 0.003
	maxProbability   = 0.995
	diversityCost    = 1800000.0
	minimumShard     = lnwire.MilliSatoshi(10_000)
	maxPlanCorridors = 10
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return true
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type pathCandidate struct {
	edges     []*candidateEdge
	hardLimit lnwire.MilliSatoshi
	safeLimit lnwire.MilliSatoshi
	score     float64
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	localSpent    map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]liquidityBelief
	blocked       map[candidateEdgeKey]bool
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty  map[candidateEdgeKey]float64

	lastRemaining       lnwire.MilliSatoshi
	consecutiveFailures uint32
	retryHint           lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeByKey:      make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		localSpent:     make(map[uint64]lnwire.MilliSatoshi),
		beliefs:        make(map[candidateEdgeKey]liquidityBelief),
		blocked:        make(map[candidateEdgeKey]bool),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:   make(map[candidateEdgeKey]float64),
		lastRemaining:  spec.Amount,
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, ok := r.edgeByKey[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}
	return (a + b - 1) / b
}

func subtractFloor(value, amount lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if amount >= value {
		return 0
	}
	return value - amount
}

func clampProbability(p float64) float64 {
	if p < minProbability {
		return minProbability
	}
	if p > maxProbability {
		return maxProbability
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-x/0.025)
	highMode := 0.48 / (1 + math.Exp(14*(x-0.78)))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) localAvailable(
	key candidateEdgeKey) lnwire.MilliSatoshi {

	available := r.localBalances[key.chanID]
	available = subtractFloor(available, r.localSpent[key.chanID])
	available = subtractFloor(available, r.reserved[key])

	return available
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if amt > r.localAvailable(edge.key) {
			return minProbability
		}
		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		return minProbability
	}
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.06, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(belief.estimate))/width,
	))

	weight := 0.48
	if belief.lowerOK != 0 || belief.upperBad != 0 {
		weight = 0.66
	}

	return clampProbability((1-weight)*prior + weight*point)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findPath(amt lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]int) ([]*candidateEdge, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)
	settled := make(map[route.Vertex]bool)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		score:    0,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)

		bestScore, ok := dist[item.node]
		if !ok || item.score != bestScore {
			continue
		}
		if item.arriving != required[item.node] {
			continue
		}
		if settled[item.node] {
			continue
		}
		settled[item.node] = true

		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if settled[edge.key.from] || r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) {
				continue
			}

			reserved := r.reserved[edge.key]
			if reserved >= edge.capacity ||
				amtOver > edge.capacity-reserved {

				continue
			}

			if edge.key.from == r.source &&
				amtOver > r.localAvailable(edge.key) {

				continue
			}

			belief := r.beliefs[edge.key]
			if belief.upperBad != 0 && amtOver >= belief.upperBad {
				continue
			}

			probability := r.probability(edge, amtOver)
			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			}

			risk := -math.Log(probability) * riskCostMsat
			cost := float64(fee) + risk +
				r.routePenalty[edge.key] + 1000

			if count := diversity[edge.key]; count != 0 {
				cost += float64(count) * diversityCost
			}
			if cost < 1 {
				cost = 1
			}

			score := item.score + cost
			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	score, ok := dist[r.source]
	if !ok || !settled[r.source] {
		return nil, 0, errors.New("no route found")
	}

	visited := make(map[route.Vertex]bool)
	path := make([]*candidateEdge, 0)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, 0, errors.New("route contains a cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok || edge.key.from != node {
			return nil, 0, fmt.Errorf("broken path at %v", node)
		}
		if visited[edge.key.to] && edge.key.to != r.spec.Target {
			return nil, 0, errors.New("route contains a cycle")
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, 0, errors.New("empty route")
	}

	return path, score, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		if !edge.usable(amtOver[i]) {
			return nil, errors.New("path cannot carry amount")
		}

		forward := amt
		expiry := finalCltvDelta
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, ok := r.edgeByKey[key]

	return key, ok
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) routeFeasible(rt *route.Route) bool {
	visited := map[route.Vertex]bool{
		rt.SourcePubKey: true,
	}

	for i, hop := range rt.Hops {
		if visited[hop.PubKeyBytes] {
			return false
		}
		visited[hop.PubKeyBytes] = true

		key, ok := r.routeEdge(rt, i)
		if !ok || r.blocked[key] {
			return false
		}

		edge := r.edgeByKey[key]
		amt := routeAmount(rt, i)
		if edge == nil || !edge.usable(amt) {
			return false
		}

		if edge.key.from == r.source {
			if amt > r.localAvailable(key) {
				return false
			}
			continue
		}

		reserved := r.reserved[key]
		if reserved >= edge.capacity ||
			amt > edge.capacity-reserved {

			return false
		}

		belief := r.beliefs[key]
		if belief.upperBad != 0 && amt >= belief.upperBad {
			return false
		}
	}

	return true
}

func (r *candidateRouter) pathLimit(path []*candidateEdge,
	maxAmount lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	low := lnwire.MilliSatoshi(0)
	high := maxAmount

	for low < high {
		mid := low + (high-low+1)/2
		rt, err := r.buildRoute(mid, path)
		if err == nil && r.routeFeasible(rt) {
			low = mid
		} else {
			high = mid - 1
		}
	}

	return low
}

func (r *candidateRouter) pathProbability(path []*candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	rt, err := r.buildRoute(amt, path)
	if err != nil || !r.routeFeasible(rt) {
		return 0
	}

	probability := 1.0
	for i, edge := range path {
		probability *= r.probability(edge, routeAmount(rt, i))
	}

	return probability
}

func (r *candidateRouter) safePathLimit(path []*candidateEdge,
	hardLimit lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if hardLimit <= 0 {
		return 0
	}

	hops := len(path)
	threshold := 0.10
	if hops <= 2 {
		threshold = 0.16
	} else if hops >= 5 {
		threshold = 0.055
	}

	if r.pathProbability(path, hardLimit) >= threshold {
		return hardLimit
	}

	low := lnwire.MilliSatoshi(0)
	high := hardLimit
	for low < high {
		mid := low + (high-low+1)/2
		if r.pathProbability(path, mid) >= threshold {
			low = mid
		} else {
			high = mid - 1
		}
	}

	return low
}

func pathID(path []*candidateEdge) string {
	id := ""
	for _, edge := range path {
		id += fmt.Sprintf(
			"%d:%x:%x/", edge.key.chanID, edge.key.from,
			edge.key.to,
		)
	}
	return id
}

func appendUniqueAmount(values []lnwire.MilliSatoshi,
	value, maximum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if value <= 0 || value > maximum {
		return values
	}
	for _, existing := range values {
		if existing == value {
			return values
		}
	}
	return append(values, value)
}

func (r *candidateRouter) probeAmounts(remaining lnwire.MilliSatoshi,
	parts uint32) []lnwire.MilliSatoshi {

	if parts == 0 {
		parts = 1
	}

	average := ceilDiv(
		remaining, lnwire.MilliSatoshi(parts),
	)

	var probes []lnwire.MilliSatoshi
	probes = appendUniqueAmount(probes, average, remaining)
	probes = appendUniqueAmount(probes, average*2/3, remaining)
	probes = appendUniqueAmount(probes, average/2, remaining)
	probes = appendUniqueAmount(probes, remaining/4, remaining)
	probes = appendUniqueAmount(probes, 50_000_000, remaining)
	probes = appendUniqueAmount(probes, 5_000_000, remaining)
	probes = appendUniqueAmount(probes, 100_000, remaining)
	probes = appendUniqueAmount(probes, minimumShard, remaining)

	sort.Slice(probes, func(i, j int) bool {
		return probes[i] > probes[j]
	})

	return probes
}

func (r *candidateRouter) planPaths(remaining lnwire.MilliSatoshi,
	parts uint32) []pathCandidate {

	count := int(parts)
	if count < 1 {
		count = 1
	}
	if count > maxPlanCorridors {
		count = maxPlanCorridors
	}

	probes := r.probeAmounts(remaining, parts)
	diversity := make(map[candidateEdgeKey]int)
	seen := make(map[string]bool)
	plans := make([]pathCandidate, 0, count)

	for round := 0; round < count*3 && len(plans) < count; round++ {
		var (
			bestPath  []*candidateEdge
			bestScore = math.Inf(1)
		)

		for _, probe := range probes {
			path, score, err := r.findPath(probe, diversity)
			if err != nil {
				continue
			}

			id := pathID(path)
			if seen[id] {
				continue
			}

			normalized := score / math.Max(
				float64(probe), 1,
			)
			if normalized < bestScore {
				bestPath = path
				bestScore = normalized
			}
		}

		if len(bestPath) == 0 {
			break
		}

		id := pathID(bestPath)
		seen[id] = true
		for _, edge := range bestPath {
			diversity[edge.key]++
		}

		hardLimit := r.pathLimit(bestPath, remaining)
		if hardLimit <= 0 {
			continue
		}

		safeLimit := r.safePathLimit(bestPath, hardLimit)
		if safeLimit < minimumShard && hardLimit >= minimumShard {
			safeLimit = minimumShard
		}

		plans = append(plans, pathCandidate{
			edges:     bestPath,
			hardLimit: hardLimit,
			safeLimit: safeLimit,
			score:     bestScore,
		})
	}

	sort.SliceStable(plans, func(i, j int) bool {
		pi := r.pathProbability(
			plans[i].edges,
			maxAmount(minimumShard, plans[i].safeLimit),
		)
		pj := r.pathProbability(
			plans[j].edges,
			maxAmount(minimumShard, plans[j].safeLimit),
		)

		if math.Abs(pi-pj) > 0.04 {
			return pi > pj
		}
		if plans[i].safeLimit != plans[j].safeLimit {
			return plans[i].safeLimit > plans[j].safeLimit
		}
		if plans[i].hardLimit != plans[j].hardLimit {
			return plans[i].hardLimit > plans[j].hardLimit
		}
		return plans[i].score < plans[j].score
	})

	return plans
}

func maxAmount(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}
	return b
}

func sumPlanLimits(plans []pathCandidate,
	safe bool) lnwire.MilliSatoshi {

	total := lnwire.MilliSatoshi(0)
	for _, plan := range plans {
		limit := plan.hardLimit
		if safe {
			limit = plan.safeLimit
		}
		total += limit
	}
	return total
}

func plannedAllocation(remaining lnwire.MilliSatoshi,
	plans []pathCandidate) lnwire.MilliSatoshi {

	if len(plans) == 0 {
		return 0
	}

	useSafe := sumPlanLimits(plans, true) >= remaining
	limit := plans[0].hardLimit
	if useSafe {
		limit = plans[0].safeLimit
	}
	if limit <= 0 {
		return 0
	}

	if len(plans) == 1 {
		if limit > remaining {
			return remaining
		}
		return limit
	}

	total := lnwire.MilliSatoshi(0)
	other := lnwire.MilliSatoshi(0)
	for i, plan := range plans {
		value := plan.hardLimit
		if useSafe {
			value = plan.safeLimit
		}
		total += value
		if i != 0 {
			other += value
		}
	}
	if total <= 0 {
		return 0
	}

	allocation := lnwire.MilliSatoshi(
		float64(remaining) * float64(limit) / float64(total),
	)

	requiredNow := subtractFloor(remaining, other)
	if allocation < requiredNow {
		allocation = requiredNow
	}

	fair := ceilDiv(
		remaining, lnwire.MilliSatoshi(len(plans)),
	)
	if allocation < fair && limit >= fair {
		allocation = fair
	}

	if allocation > limit {
		allocation = limit
	}
	if allocation > remaining {
		allocation = remaining
	}
	if allocation < minimumShard && remaining >= minimumShard &&
		limit >= minimumShard {

		allocation = minimumShard
	}

	return allocation
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.reserved[key] += routeAmount(rt, i)
		}
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts in flight")
	}

	if amt < r.lastRemaining {
		r.consecutiveFailures = 0
		r.retryHint = 0
	}
	r.lastRemaining = amt

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	plans := r.planPaths(amt, partsLeft)

	if len(plans) != 0 {
		shard := plannedAllocation(amt, plans)
		if r.retryHint != 0 && shard > r.retryHint {
			shard = r.retryHint
		}
		if shard > plans[0].hardLimit {
			shard = plans[0].hardLimit
		}
		if shard > amt {
			shard = amt
		}

		for shard > 0 {
			rt, err := r.buildRoute(shard, plans[0].edges)
			if err == nil && r.routeFeasible(rt) {
				r.reserve(rt)
				return rt, nil
			}

			next := shard * 2 / 3
			if next >= shard {
				next = shard - 1
			}
			if next < minimumShard && amt >= minimumShard {
				break
			}
			shard = next
		}
	}

	var candidates []lnwire.MilliSatoshi
	candidates = appendUniqueAmount(candidates, r.retryHint, amt)
	candidates = appendUniqueAmount(candidates, amt, amt)
	candidates = appendUniqueAmount(
		candidates,
		ceilDiv(amt, lnwire.MilliSatoshi(partsLeft)),
		amt,
	)
	candidates = appendUniqueAmount(candidates, amt*2/3, amt)
	candidates = appendUniqueAmount(candidates, amt/2, amt)
	candidates = appendUniqueAmount(candidates, amt/3, amt)
	candidates = appendUniqueAmount(candidates, amt/4, amt)
	candidates = appendUniqueAmount(candidates, minimumShard, amt)

	var lastErr error
	for _, shard := range candidates {
		path, _, err := r.findPath(
			shard, make(map[candidateEdgeKey]int),
		)
		if err != nil {
			lastErr = err
			continue
		}

		rt, err := r.buildRoute(shard, path)
		if err != nil {
			lastErr = err
			continue
		}
		if !r.routeFeasible(rt) {
			lastErr = errors.New("route is not feasible")
			continue
		}

		r.reserve(rt)
		return rt, nil
	}

	if lastErr == nil {
		lastErr = errors.New("no route found")
	}
	return nil, lastErr
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordPass(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	inferred := amt
	if edge.capacity > amt {
		inferred += (edge.capacity - amt) * 3 / 4
	}
	if inferred > belief.estimate {
		belief.estimate = inferred
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordSettlement(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil {
		return
	}

	if key.from == r.source {
		r.localSpent[key.chanID] += amt
		return
	}

	belief := r.beliefs[key]
	estimate := belief.estimate
	if estimate < amt {
		estimate = amt
	}

	inferred := amt
	if edge.capacity > amt {
		inferred += (edge.capacity - amt) * 3 / 4
	}
	if inferred > estimate {
		estimate = inferred
	}

	belief.estimate = subtractFloor(estimate, amt)
	belief.lowerOK = subtractFloor(belief.lowerOK, amt)
	if belief.upperBad != 0 {
		belief.upperBad = subtractFloor(belief.upperBad, amt)
		if belief.upperBad == 0 {
			belief.upperBad = 1
		}
	}

	likelyRemaining := lnwire.MilliSatoshi(0)
	if edge.capacity > amt {
		likelyRemaining = (edge.capacity - amt) * 2 / 3
	}
	if belief.estimate < likelyRemaining {
		belief.estimate = likelyRemaining
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt * 30 / 100
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes != source {
			continue
		}

		outgoing := i + 1
		if outgoing < len(rt.Hops) {
			return outgoing
		}
		return -1
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			r.recordSettlement(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.20
		}

		r.consecutiveFailures = 0
		r.retryHint = 0
		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if ok {
				r.routePenalty[key] += riskCostMsat * 0.35
			}
		}

		r.consecutiveFailures++
		delivered := deliveredAmount(rt)
		if delivered > minimumShard {
			r.retryHint = delivered * 2 / 3
		}
		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		r.recordPass(key, routeAmount(rt, i))
		r.routePenalty[key] *= 0.70
	}

	key, ok := r.routeEdge(rt, failIndex)
	if !ok {
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	case lnwire.CodeTemporaryChannelFailure:
		r.recordFailure(key, routeAmount(rt, failIndex))
		r.routePenalty[key] += riskCostMsat * 1.6

	default:
		r.routePenalty[key] += riskCostMsat * 0.75
	}

	r.consecutiveFailures++

	delivered := deliveredAmount(rt)
	if delivered > minimumShard {
		retry := delivered * 2 / 3
		if r.consecutiveFailures >= 3 {
			retry = delivered / 2
		}
		if r.consecutiveFailures >= 6 {
			retry = delivered / 3
		}
		if retry < minimumShard {
			retry = minimumShard
		}
		r.retryHint = retry
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta  = 40
	maxAttempts     = 64
	minShardAmount  = lnwire.MilliSatoshi(1_000)
	maxPlanChoices  = 14
	planningDepth   = 4
	uncoveredWeight = 18.0
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs      map[edgeKey]liquidityBelief
	reserved     map[edgeKey]lnwire.MilliSatoshi
	paymentUpper map[edgeKey]lnwire.MilliSatoshi
	failures     map[edgeKey]uint32
	broken       map[edgeKey]bool

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		paymentUpper:  make(map[edgeKey]lnwire.MilliSatoshi),
		failures:      make(map[edgeKey]uint32),
		broken:        make(map[edgeKey]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	nodes := []route.Vertex{source}

	for len(nodes) > 0 {
		node := nodes[0]
		nodes = nodes[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					nodes = append(nodes, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, exists := r.edges[key]; exists {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, exists := sharedBeliefs.values[key]
		if !exists {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.51 * math.Exp(-20*x)
	highMode := 0.48 / (1 + math.Exp(24*(x-0.87)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}
		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := math.Max(1, float64(edge.capacity)*0.075)
	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))

	confidence := math.Min(0.84, 0.18*float64(belief.samples))
	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

func (r *candidateRouter) freshlyImpossible(edge *candidateEdge,
	amt lnwire.MilliSatoshi) bool {

	upper := r.paymentUpper[edge.key]
	return upper > 0 && amt+r.reserved[edge.key] >= upper
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
	utility     float64
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, exists := score[item.node]
		if !exists || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(item.amt) {
				continue
			}
			if r.freshlyImpossible(edge, item.amt) {
				continue
			}

			total := item.amt + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			// Reliability dominates. The failure term encourages genuine
			// route diversity while still permitting lower-amount retries.
			step := -math.Log(probability) +
				float64(edgeFee)/4_000_000 +
				0.010 +
				0.32*float64(r.failures[edge.key])
			candidate := item.score + step

			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, exists := next[r.source]; !exists {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(r.edges[key], amounts[i])
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, exists := next[node]
		if !exists {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < minShardAmount {
		minimum = minShardAmount
	}
	if minimum > amt {
		minimum = amt
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, maxPlanChoices+8)

	for _, fraction := range [][2]int64{
		{1, 1},
		{9, 10},
		{4, 5},
		{3, 4},
		{2, 3},
		{3, 5},
		{1, 2},
		{2, 5},
		{1, 3},
	} {
		addAmount(
			&values, seen,
			amt*lnwire.MilliSatoshi(fraction[0])/
				lnwire.MilliSatoshi(fraction[1]),
			minimum, amt,
		)
	}

	addAmount(&values, seen, minimum*2, minimum, amt)
	addAmount(&values, seen, minimum*3/2, minimum, amt)
	addAmount(&values, seen, minimum*5/4, minimum, amt)
	addAmount(&values, seen, minimum, minimum, amt)

	if r.lastFailedAmt > 0 {
		for _, fraction := range [][2]int64{
			{9, 10},
			{4, 5},
			{2, 3},
			{1, 2},
			{1, 3},
		} {
			addAmount(
				&values, seen,
				r.lastFailedAmt*
					lnwire.MilliSatoshi(fraction[0])/
					lnwire.MilliSatoshi(fraction[1]),
				minimum, amt,
			)
		}
	}

	var evidence []lnwire.MilliSatoshi
	for key, upper := range r.paymentUpper {
		if r.broken[key] || upper <= 1 {
			continue
		}

		evidence = append(
			evidence,
			upper*9/10,
			upper*4/5,
			upper*2/3,
			upper/2,
		)
	}

	for key, belief := range r.beliefs {
		if r.broken[key] {
			continue
		}
		if belief.lowerOK > 0 {
			evidence = append(
				evidence,
				belief.lowerOK,
				belief.lowerOK*9/10,
			)
		}
		if belief.upperFail > 1 {
			evidence = append(
				evidence,
				belief.upperFail*4/5,
				belief.upperFail*2/3,
			)
		}
	}

	sort.Slice(evidence, func(i, j int) bool {
		return evidence[i] > evidence[j]
	})
	if len(evidence) > 10 {
		evidence = evidence[:10]
	}

	for _, value := range evidence {
		addAmount(&values, seen, value, minimum, amt)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})
	if len(values) > maxPlanChoices {
		values = values[:maxPlanChoices]
	}

	return values
}

func (r *candidateRouter) reserveChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		r.reserved[key] += choice.amounts[i]
	}
}

func (r *candidateRouter) releaseChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		reserved := r.reserved[key]
		if reserved <= choice.amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - choice.amounts[i]
		}
	}
}

func choiceCost(choice *routeChoice) float64 {
	retryCost := 1/choice.probability - 1
	if retryCost > 12 {
		retryCost = 12
	}

	return -math.Log(choice.probability) +
		0.16*retryCost +
		float64(choice.fee)/4_000_000 +
		0.20
}

// planRemainder performs a bounded route-set search. Reservations make each
// successive route account for the liquidity already assigned to earlier
// shards, which naturally produces unequal allocations across independent
// corridors.
func (r *candidateRouter) planRemainder(
	remaining lnwire.MilliSatoshi, slots, depth uint32) float64 {

	if remaining <= 0 {
		return 0
	}
	if slots == 0 {
		return uncoveredWeight
	}

	if depth == 0 {
		choice, err := r.findRoute(remaining)
		if err == nil {
			return choiceCost(choice)
		}

		return uncoveredWeight +
			4*float64(remaining)/float64(remaining+1_000_000)
	}

	amounts := r.candidateAmounts(remaining, slots)
	best := math.Inf(1)
	limit := len(amounts)
	if limit > 8 {
		limit = 8
	}

	for _, shard := range amounts[:limit] {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		r.reserveChoice(choice)
		rest := r.planRemainder(
			remaining-shard, slots-1, depth-1,
		)
		r.releaseChoice(choice)

		// Reward progress per occupied part. This prevents a sequence of
		// extremely reliable dust shards from consuming the attempt budget.
		progress := float64(shard) / float64(remaining)
		cost := choiceCost(choice) + rest + 0.34*(1-progress)
		if cost < best {
			best = cost
		}
	}

	if math.IsInf(best, 1) {
		return uncoveredWeight
	}

	return best
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	amounts := r.candidateAmounts(amt, partsLeft)

	var best *routeChoice
	limit := len(amounts)
	if limit > maxPlanChoices {
		limit = maxPlanChoices
	}

	for _, shard := range amounts[:limit] {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		r.reserveChoice(choice)
		depth := uint32(planningDepth)
		if partsLeft-1 < depth {
			depth = partsLeft - 1
		}
		continuation := r.planRemainder(
			amt-shard, partsLeft-1, depth,
		)
		r.releaseChoice(choice)

		progress := float64(shard) / float64(amt)
		choice.utility = choiceCost(choice) +
			continuation +
			0.42*(1-progress)

		if best == nil || choice.utility < best.utility {
			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.reserveChoice(best)
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	fresh := r.paymentUpper[key]
	if fresh == 0 || amt < fresh {
		r.paymentUpper[key] = amt
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	lowEstimate := amt / 5
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = lowEstimate
	} else {
		belief.estimate = (3*belief.estimate + lowEstimate) / 4
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnProbeSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.estimate < amt {
		belief.estimate = amt
	}

	optimistic := edge.capacity * 4 / 5
	if belief.estimate < optimistic {
		belief.estimate = (belief.estimate + optimistic) / 2
	}
	if belief.upperFail > 0 && belief.upperFail <= belief.lowerOK {
		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	if belief.upperFail > 0 &&
		belief.lowerOK >= belief.upperFail {

		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}
	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) releaseRoute(keys []edgeKey,
	amounts []lnwire.MilliSatoshi) {

	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	r.releaseRoute(keys, amounts)

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.failures[key] > 0 {
				r.failures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		// A forwarding node reports a failure for its outgoing edge. The
		// source of hop i therefore corresponds to edge i+1.
		for i := 0; i+1 < len(rt.Hops); i++ {
			if rt.Hops[i].PubKeyBytes ==
				result.FailureSource {

				failIndex = i + 1
				break
			}
		}
	}

	r.lastFailedAmt = rt.Hops[len(rt.Hops)-1].AmtToForward

	if failIndex < 0 || failIndex >= len(keys) {
		for _, key := range keys {
			r.failures[key]++
		}

		return nil
	}

	for i := 0; i < failIndex; i++ {
		r.learnProbeSuccess(keys[i], amounts[i])
		if r.failures[keys[i]] > 0 {
			r.failures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	r.failures[key] += 2

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	maxAttempts    = 64
	minShardAmount = lnwire.MilliSatoshi(1_000)

	maxAmountChoices = 18
	maxRouteChoices  = 4
	planningDepth    = 3
)

type edgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key edgeKey

	capacity      lnwire.MilliSatoshi
	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs      map[edgeKey]liquidityBelief
	reserved     map[edgeKey]lnwire.MilliSatoshi
	paymentUpper map[edgeKey]lnwire.MilliSatoshi
	failures     map[edgeKey]uint32
	broken       map[edgeKey]bool

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		paymentUpper:  make(map[edgeKey]lnwire.MilliSatoshi),
		failures:      make(map[edgeKey]uint32),
		broken:        make(map[edgeKey]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	nodes := []route.Vertex{source}

	for len(nodes) > 0 {
		node := nodes[0]
		nodes = nodes[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					nodes = append(nodes, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.51 * math.Exp(-20*x)
	highMode := 0.48 / (1 + math.Exp(24*(x-0.87)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := math.Max(1, float64(edge.capacity)*0.07)
	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))

	confidence := math.Min(0.86, 0.18*float64(belief.samples))
	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

func (r *candidateRouter) freshlyImpossible(edge *candidateEdge,
	amt lnwire.MilliSatoshi) bool {

	upper := r.paymentUpper[edge.key]
	return upper > 0 && amt+r.reserved[edge.key] >= upper
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
	cost        float64
}

func (r *candidateRouter) findRoute(deliver lnwire.MilliSatoshi,
	diversity map[edgeKey]float64) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(item.amt) {
				continue
			}
			if r.freshlyImpossible(edge, item.amt) {
				continue
			}

			total := item.amt + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			step := -math.Log(probability) +
				float64(edgeFee)/5_000_000 +
				0.008 +
				0.22*float64(r.failures[edge.key]) +
				diversity[edge.key]

			candidate := item.score + step
			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(r.edges[key], amounts[i])
	}

	choice := &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}
	choice.cost = choiceCost(choice)

	return choice, nil
}

func (r *candidateRouter) routeChoices(
	deliver lnwire.MilliSatoshi) []*routeChoice {

	var choices []*routeChoice
	diversity := make(map[edgeKey]float64)
	signatures := make(map[string]bool)

	for i := 0; i < maxRouteChoices; i++ {
		choice, err := r.findRoute(deliver, diversity)
		if err != nil {
			break
		}

		signature := ""
		for _, key := range choice.keys {
			signature += fmt.Sprintf(
				"%d:%x:%x/", key.chanID, key.from[:4], key.to[:4],
			)
		}
		if !signatures[signature] {
			signatures[signature] = true
			choices = append(choices, choice)
		}

		for _, key := range choice.keys {
			diversity[key] += 0.85
		}
	}

	return choices
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))

	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	maximum lnwire.MilliSatoshi) {

	if value < minShardAmount {
		value = minShardAmount
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) edgeOffer(
	edge *candidateEdge) lnwire.MilliSatoshi {

	available := edge.capacity - r.reserved[edge.key]
	if available <= 0 {
		return 0
	}

	if edge.key.from == r.source {
		balance := r.localBalances[edge.key.chanID] -
			r.reserved[edge.key]
		if balance < available {
			available = balance
		}

		return available
	}

	belief := r.beliefs[edge.key]
	switch {
	case belief.lowerOK > r.reserved[edge.key]:
		available = belief.lowerOK - r.reserved[edge.key]

	case belief.upperFail > r.reserved[edge.key]+1:
		available = belief.upperFail -
			r.reserved[edge.key] - 1

	case belief.estimate > r.reserved[edge.key]:
		available = belief.estimate - r.reserved[edge.key]

	default:
		available = edge.capacity * 4 / 5
	}

	if upper := r.paymentUpper[edge.key]; upper > 0 {
		if upper <= r.reserved[edge.key]+1 {
			return 0
		}

		fresh := upper - r.reserved[edge.key] - 1
		if fresh < available {
			available = fresh
		}
	}

	if edge.maxHTLC > 0 && available > edge.maxHTLC {
		available = edge.maxHTLC
	}

	return available
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, maxAmountChoices+16)

	equal := (amt + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	for _, value := range []lnwire.MilliSatoshi{
		amt,
		amt * 9 / 10,
		amt * 4 / 5,
		amt * 3 / 4,
		amt * 2 / 3,
		amt * 3 / 5,
		amt / 2,
		amt * 2 / 5,
		amt / 3,
		equal * 3 / 2,
		equal * 5 / 4,
		equal,
		equal * 4 / 5,
		equal * 2 / 3,
	} {
		addAmount(&values, seen, value, amt)
	}

	if r.lastFailedAmt > 0 {
		for _, value := range []lnwire.MilliSatoshi{
			r.lastFailedAmt * 9 / 10,
			r.lastFailedAmt * 4 / 5,
			r.lastFailedAmt * 2 / 3,
			r.lastFailedAmt / 2,
			r.lastFailedAmt / 3,
		} {
			addAmount(&values, seen, value, amt)
		}
	}

	var offers []lnwire.MilliSatoshi
	for _, edge := range r.incomingEdges[r.spec.Target] {
		if r.broken[edge.key] {
			continue
		}

		offer := r.edgeOffer(edge)
		if offer > 0 {
			offers = append(offers, offer)
		}
	}

	for key, upper := range r.paymentUpper {
		if r.broken[key] || upper <= r.reserved[key]+1 {
			continue
		}

		offers = append(
			offers,
			upper-r.reserved[key]-1,
		)
	}

	sort.Slice(offers, func(i, j int) bool {
		return offers[i] > offers[j]
	})
	if len(offers) > 12 {
		offers = offers[:12]
	}

	for _, offer := range offers {
		addAmount(&values, seen, offer, amt)
		addAmount(&values, seen, offer*9/10, amt)
		addAmount(&values, seen, offer*4/5, amt)
		addAmount(&values, seen, offer*2/3, amt)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	if len(values) > maxAmountChoices {
		kept := append(
			[]lnwire.MilliSatoshi(nil),
			values[:maxAmountChoices-4]...,
		)
		tailStart := len(values) - 4
		if tailStart < maxAmountChoices-4 {
			tailStart = maxAmountChoices - 4
		}
		for _, value := range values[tailStart:] {
			duplicate := false
			for _, old := range kept {
				if old == value {
					duplicate = true
					break
				}
			}
			if !duplicate {
				kept = append(kept, value)
			}
		}
		values = kept
	}

	return values
}

func choiceCost(choice *routeChoice) float64 {
	retryCost := 1/choice.probability - 1
	if retryCost > 15 {
		retryCost = 15
	}

	return -math.Log(choice.probability) +
		0.14*retryCost +
		float64(choice.fee)/5_000_000 +
		0.12
}

func (r *candidateRouter) reserveChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		r.reserved[key] += choice.amounts[i]
	}
}

func (r *candidateRouter) releaseChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		reserved := r.reserved[key]
		if reserved <= choice.amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - choice.amounts[i]
		}
	}
}

type planResult struct {
	cost    float64
	covered lnwire.MilliSatoshi
}

func betterPlan(a, b planResult) bool {
	if a.covered != b.covered {
		return a.covered > b.covered
	}

	return a.cost < b.cost
}

func (r *candidateRouter) planRemainder(remaining lnwire.MilliSatoshi,
	slots, depth uint32) planResult {

	if remaining <= 0 {
		return planResult{}
	}
	if slots == 0 {
		return planResult{
			cost: math.Inf(1),
		}
	}

	if slots == 1 || depth == 0 {
		choices := r.routeChoices(remaining)
		if len(choices) == 0 {
			return planResult{
				cost: math.Inf(1),
			}
		}

		return planResult{
			cost:    choices[0].cost,
			covered: remaining,
		}
	}

	best := planResult{
		cost: math.Inf(1),
	}

	amounts := r.candidateAmounts(remaining, slots)
	limit := len(amounts)
	if limit > 11 {
		limit = 11
	}

	for _, shard := range amounts[:limit] {
		choices := r.routeChoices(shard)
		for _, choice := range choices {
			r.reserveChoice(choice)
			rest := r.planRemainder(
				remaining-shard, slots-1, depth-1,
			)
			r.releaseChoice(choice)

			covered := shard + rest.covered
			cost := choice.cost + rest.cost
			if math.IsInf(rest.cost, 1) {
				cost = choice.cost +
					20*float64(remaining-covered)/
						float64(remaining)
			}

			progress := float64(shard) / float64(remaining)
			candidate := planResult{
				cost:    cost + 0.18*(1-progress),
				covered: covered,
			}
			if betterPlan(candidate, best) {
				best = candidate
			}
		}
	}

	return best
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	slots := r.spec.MaxParts - inFlightHtlcs
	amounts := r.candidateAmounts(amt, slots)

	var best *routeChoice
	bestCovered := lnwire.MilliSatoshi(-1)
	bestUtility := math.Inf(1)

	for _, shard := range amounts {
		choices := r.routeChoices(shard)
		for _, choice := range choices {
			r.reserveChoice(choice)

			depth := uint32(planningDepth)
			if slots > 0 && slots-1 < depth {
				depth = slots - 1
			}
			rest := r.planRemainder(
				amt-shard, slots-1, depth,
			)

			r.releaseChoice(choice)

			covered := shard + rest.covered
			utility := choice.cost + rest.cost
			if math.IsInf(rest.cost, 1) {
				missing := amt - covered
				utility = choice.cost +
					25*float64(missing)/float64(amt)
			}

			progress := float64(shard) / float64(amt)
			utility += 0.20 * (1 - progress)

			if covered > bestCovered ||
				(covered == bestCovered &&
					utility < bestUtility) {

				best = choice
				bestCovered = covered
				bestUtility = utility
			}
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.reserveChoice(best)
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}

		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	fresh := r.paymentUpper[key]
	if fresh == 0 || amt < fresh {
		r.paymentUpper[key] = amt
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	lowEstimate := amt / 6
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = lowEstimate
	} else {
		belief.estimate = (3*belief.estimate + lowEstimate) / 4
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnProbeSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.estimate < amt {
		belief.estimate = amt
	}

	optimistic := edge.capacity * 4 / 5
	if belief.estimate < optimistic {
		belief.estimate = (belief.estimate + optimistic) / 2
	}

	if belief.upperFail > 0 &&
		belief.upperFail <= belief.lowerOK {

		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	estimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if estimate < optimistic {
		estimate = (estimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(estimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	if belief.upperFail > 0 &&
		belief.lowerOK >= belief.upperFail {

		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}

	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) releaseRoute(keys []edgeKey,
	amounts []lnwire.MilliSatoshi) {

	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	r.releaseRoute(keys, amounts)

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.failures[key] > 0 {
				r.failures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i := 0; i+1 < len(rt.Hops); i++ {
			if rt.Hops[i].PubKeyBytes ==
				result.FailureSource {

				failIndex = i + 1
				break
			}
		}
	}

	r.lastFailedAmt = rt.Hops[len(rt.Hops)-1].AmtToForward

	if failIndex < 0 || failIndex >= len(keys) {
		for _, key := range keys {
			r.failures[key]++
		}

		return nil
	}

	for i := 0; i < failIndex; i++ {
		r.learnProbeSuccess(keys[i], amounts[i])
		if r.failures[keys[i]] > 0 {
			r.failures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	r.failures[key] += 2

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta     = 40
	maxAttempts        = 64
	minShardAmount     = lnwire.MilliSatoshi(1_000)
	maxAmountChoices   = 20
	maxRouteChoices    = 7
	uncoveredPlanCost  = 30.0
	maxGreedyPlanDepth = 12
)

type edgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedCandidateBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs      map[edgeKey]liquidityBelief
	reserved     map[edgeKey]lnwire.MilliSatoshi
	paymentUpper map[edgeKey]lnwire.MilliSatoshi
	failures     map[edgeKey]uint32
	broken       map[edgeKey]bool

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		paymentUpper:  make(map[edgeKey]lnwire.MilliSatoshi),
		failures:      make(map[edgeKey]uint32),
		broken:        make(map[edgeKey]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	nodes := []route.Vertex{source}

	for len(nodes) > 0 {
		node := nodes[0]
		nodes = nodes[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					nodes = append(nodes, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedCandidateBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedCandidateBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity * 4 / 5
		}
		r.beliefs[key] = belief
	}
	sharedCandidateBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.52 * math.Exp(-22*x)
	highMode := 0.47 / (1 + math.Exp(25*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := math.Max(1, float64(edge.capacity)*0.065)
	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))

	confidence := math.Min(0.88, 0.20*float64(belief.samples))
	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

func (r *candidateRouter) freshlyImpossible(edge *candidateEdge,
	amt lnwire.MilliSatoshi) bool {

	upper := r.paymentUpper[edge.key]
	if upper == 0 {
		return false
	}

	return amt+r.reserved[edge.key] >= upper
}

func (r *candidateRouter) failurePenalty(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	count := r.failures[edge.key]
	if count == 0 {
		return 0
	}

	total := amt + r.reserved[edge.key]
	upper := r.paymentUpper[edge.key]
	if upper > 0 && total*2 <= upper {
		return 0.035 * float64(count)
	}
	if upper > 0 && total*3 <= upper*2 {
		return 0.10 * float64(count)
	}

	return 0.42 * float64(count)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
	utility     float64
}

func (r *candidateRouter) findRoute(deliver lnwire.MilliSatoshi,
	forbidden map[edgeKey]bool) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if forbidden[edge.key] || r.broken[edge.key] {
				continue
			}
			if !edge.usable(item.amt) {
				continue
			}
			if r.freshlyImpossible(edge, item.amt) {
				continue
			}

			total := item.amt + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			capacityBonus := 0.025 * math.Log1p(
				float64(edge.capacity) /
					math.Max(1, float64(item.amt)),
			)
			step := -math.Log(probability) +
				float64(edgeFee)/5_000_000 +
				0.012 +
				r.failurePenalty(edge, item.amt) -
				math.Min(0.09, capacityBonus)
			candidate := item.score + step

			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(r.edges[key], amounts[i])
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func samePath(a, b *routeChoice) bool {
	if len(a.keys) != len(b.keys) {
		return false
	}

	for i := range a.keys {
		if a.keys[i] != b.keys[i] {
			return false
		}
	}

	return true
}

func appendUniqueChoice(choices []*routeChoice,
	choice *routeChoice) []*routeChoice {

	for _, existing := range choices {
		if samePath(existing, choice) {
			return choices
		}
	}

	return append(choices, choice)
}

func (r *candidateRouter) routeOptions(
	deliver lnwire.MilliSatoshi) []*routeChoice {

	first, err := r.findRoute(deliver, nil)
	if err != nil {
		return nil
	}

	choices := []*routeChoice{first}
	type rankedEdge struct {
		key   edgeKey
		value float64
	}

	ranked := make([]rankedEdge, 0, len(first.keys))
	for i, key := range first.keys {
		edge := r.edges[key]
		if edge == nil {
			continue
		}

		p := r.edgeProbability(edge, first.amounts[i])
		value := -math.Log(p) + r.failurePenalty(
			edge, first.amounts[i],
		)
		if i == len(first.keys)-1 {
			value += 0.25
		}

		ranked = append(ranked, rankedEdge{
			key:   key,
			value: value,
		})
	}

	sort.Slice(ranked, func(i, j int) bool {
		return ranked[i].value > ranked[j].value
	})

	for _, item := range ranked {
		if len(choices) >= maxRouteChoices {
			break
		}

		forbidden := map[edgeKey]bool{item.key: true}
		alternative, err := r.findRoute(deliver, forbidden)
		if err != nil {
			continue
		}

		choices = appendUniqueChoice(choices, alternative)
	}

	for i := len(first.keys) - 1; i >= 0; i-- {
		if len(choices) >= maxRouteChoices {
			break
		}

		forbidden := map[edgeKey]bool{first.keys[i]: true}
		alternative, err := r.findRoute(deliver, forbidden)
		if err != nil {
			continue
		}

		choices = appendUniqueChoice(choices, alternative)
	}

	sort.Slice(choices, func(i, j int) bool {
		return choiceCost(choices[i]) < choiceCost(choices[j])
	})
	if len(choices) > maxRouteChoices {
		choices = choices[:maxRouteChoices]
	}

	return choices
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addCandidateAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, maximum,
	minimum lnwire.MilliSatoshi) {

	if value > maximum {
		value = maximum
	}
	if value < minimum {
		value = minimum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := minShardAmount
	if minimum > amt {
		minimum = amt
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 64)
	add := func(value lnwire.MilliSatoshi) {
		addCandidateAmount(&values, seen, value, amt, minimum)
	}

	equal := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)

	add(amt)
	add(amt * 7 / 8)
	add(amt * 3 / 4)
	add(amt * 2 / 3)
	add(amt * 3 / 5)
	add(amt / 2)
	add(amt * 2 / 5)
	add(amt / 3)
	add(amt / 4)
	add(equal * 2)
	add(equal * 3 / 2)
	add(equal * 5 / 4)
	add(equal)
	add(equal * 4 / 5)
	add(equal * 2 / 3)
	add(equal / 2)

	if r.lastFailedAmt > 0 {
		add(r.lastFailedAmt * 9 / 10)
		add(r.lastFailedAmt * 3 / 4)
		add(r.lastFailedAmt * 2 / 3)
		add(r.lastFailedAmt / 2)
		add(r.lastFailedAmt / 3)
		add(r.lastFailedAmt / 4)
	}

	for key, upper := range r.paymentUpper {
		if r.broken[key] || upper <= 1 {
			continue
		}

		reserved := r.reserved[key]
		if upper <= reserved+1 {
			continue
		}

		headroom := upper - reserved
		add(headroom * 9 / 10)
		add(headroom * 3 / 4)
		add(headroom * 2 / 3)
		add(headroom / 2)
		add(headroom / 3)
	}

	for key, belief := range r.beliefs {
		if r.broken[key] {
			continue
		}

		reserved := r.reserved[key]
		if belief.lowerOK > reserved {
			headroom := belief.lowerOK - reserved
			add(headroom)
			add(headroom * 9 / 10)
			add(headroom * 3 / 4)
		}
		if belief.estimate > reserved {
			headroom := belief.estimate - reserved
			add(headroom * 9 / 10)
			add(headroom * 2 / 3)
		}
	}

	for _, edge := range r.incomingEdges[r.spec.Target] {
		if r.broken[edge.key] {
			continue
		}

		limit := edge.capacity
		if edge.maxHTLC > 0 && edge.maxHTLC < limit {
			limit = edge.maxHTLC
		}
		if limit <= r.reserved[edge.key] {
			continue
		}

		headroom := limit - r.reserved[edge.key]
		add(headroom * 9 / 10)
		add(headroom * 3 / 4)
		add(headroom / 2)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] < values[j]
	})

	if len(values) <= maxAmountChoices {
		return values
	}

	selected := make([]lnwire.MilliSatoshi, 0, maxAmountChoices)
	selectedSeen := make(map[lnwire.MilliSatoshi]bool)
	for i := 0; i < maxAmountChoices; i++ {
		index := i * (len(values) - 1) / (maxAmountChoices - 1)
		value := values[index]
		if !selectedSeen[value] {
			selectedSeen[value] = true
			selected = append(selected, value)
		}
	}

	for _, important := range []lnwire.MilliSatoshi{
		equal, amt, r.lastFailedAmt / 2,
	} {
		if important <= 0 {
			continue
		}
		if important > amt {
			important = amt
		}
		if important < minimum {
			important = minimum
		}
		if selectedSeen[important] {
			continue
		}

		if len(selected) >= maxAmountChoices {
			selected[len(selected)/2] = important
		} else {
			selected = append(selected, important)
		}
		selectedSeen[important] = true
	}

	sort.Slice(selected, func(i, j int) bool {
		return selected[i] < selected[j]
	})

	return selected
}

func (r *candidateRouter) reserveChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		r.reserved[key] += choice.amounts[i]
	}
}

func (r *candidateRouter) releaseChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		reserved := r.reserved[key]
		if reserved <= choice.amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - choice.amounts[i]
		}
	}
}

func choiceCost(choice *routeChoice) float64 {
	retryCost := 1/choice.probability - 1
	if retryCost > 16 {
		retryCost = 16
	}

	return -math.Log(choice.probability) +
		0.14*retryCost +
		float64(choice.fee)/5_000_000 +
		0.16
}

func (r *candidateRouter) greedyPlanCost(
	remaining lnwire.MilliSatoshi, slots uint32) float64 {

	if remaining <= 0 {
		return 0
	}
	if slots == 0 {
		return uncoveredPlanCost
	}

	original := remaining
	reservedChoices := make([]*routeChoice, 0, slots)
	defer func() {
		for i := len(reservedChoices) - 1; i >= 0; i-- {
			r.releaseChoice(reservedChoices[i])
		}
	}()

	totalCost := 0.0
	maxDepth := slots
	if maxDepth > maxGreedyPlanDepth {
		maxDepth = maxGreedyPlanDepth
	}

	for step := uint32(0); step < maxDepth && remaining > 0; step++ {
		left := slots - step
		amounts := r.candidateAmounts(remaining, left)

		var best *routeChoice
		bestMetric := math.Inf(1)

		for _, shard := range amounts {
			if shard > remaining {
				continue
			}

			options := r.routeOptions(shard)
			for _, choice := range options {
				progress := float64(shard) /
					float64(remaining)
				metric := choiceCost(choice) +
					0.72*(1-progress)

				r.reserveChoice(choice)
				remainder := remaining - shard
				if remainder > 0 && left > 1 {
					probe := (remainder +
						lnwire.MilliSatoshi(left-2)) /
						lnwire.MilliSatoshi(left-1)
					if len(r.routeOptions(probe)) == 0 {
						metric += 2.4
					}
				}
				r.releaseChoice(choice)

				if metric < bestMetric {
					bestMetric = metric
					best = choice
				}
			}
		}

		if best == nil {
			fraction := float64(remaining) / float64(original)
			return totalCost + uncoveredPlanCost*(0.5+fraction)
		}

		r.reserveChoice(best)
		reservedChoices = append(reservedChoices, best)
		remaining -= best.deliver
		totalCost += choiceCost(best)
	}

	if remaining > 0 {
		fraction := float64(remaining) / float64(original)
		totalCost += uncoveredPlanCost * (0.5 + fraction)
	}

	return totalCost
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	amounts := r.candidateAmounts(amt, partsLeft)

	var best *routeChoice
	bestUtility := math.Inf(1)

	for _, shard := range amounts {
		options := r.routeOptions(shard)
		for _, choice := range options {
			r.reserveChoice(choice)
			continuation := r.greedyPlanCost(
				amt-shard, partsLeft-1,
			)
			r.releaseChoice(choice)

			progress := float64(shard) / float64(amt)
			utility := choiceCost(choice) +
				continuation +
				0.34*(1-progress)

			if utility < bestUtility {
				bestUtility = utility
				best = choice
			}
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.reserveChoice(best)
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedCandidateBeliefs.Lock()
	sharedCandidateBeliefs.values[key] = belief
	sharedCandidateBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	fresh := r.paymentUpper[key]
	if fresh == 0 || amt < fresh {
		r.paymentUpper[key] = amt
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	depletedEstimate := amt / 10
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = depletedEstimate
	} else {
		belief.estimate = (
			4*belief.estimate + depletedEstimate
		) / 5
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnProbeSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.estimate < amt {
		belief.estimate = amt
	}

	optimistic := edge.capacity * 9 / 10
	if belief.estimate < optimistic {
		belief.estimate = (
			belief.estimate + 2*optimistic
		) / 3
	}
	if belief.upperFail > 0 && belief.upperFail <= belief.lowerOK {
		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (
			preEstimate + 2*optimistic
		) / 3
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	if belief.upperFail > 0 &&
		belief.lowerOK >= belief.upperFail {

		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}
	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) releaseRoute(keys []edgeKey,
	amounts []lnwire.MilliSatoshi) {

	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	r.releaseRoute(keys, amounts)

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.failures[key] > 0 {
				r.failures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i := 0; i+1 < len(rt.Hops); i++ {
			if rt.Hops[i].PubKeyBytes ==
				result.FailureSource {

				failIndex = i + 1
				break
			}
		}
	}

	r.lastFailedAmt = rt.Hops[len(rt.Hops)-1].AmtToForward

	if failIndex < 0 || failIndex >= len(keys) {
		for _, key := range keys {
			r.failures[key]++
		}

		return nil
	}

	for i := 0; i < failIndex; i++ {
		r.learnProbeSuccess(keys[i], amounts[i])
		if r.failures[keys[i]] > 0 {
			r.failures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.failures[key] += 2
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.failures[key] += 4
		r.broken[key] = true

	default:
		r.failures[key]++
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	maxAttempts    = 64
	minShardAmount = lnwire.MilliSatoshi(1_000)

	maxAmountChoices = 18
	maxPlanBranches  = 9
	maxPlanningDepth = 3
	uncoveredCost    = 80.0
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs      map[edgeKey]liquidityBelief
	reserved     map[edgeKey]lnwire.MilliSatoshi
	paymentUpper map[edgeKey]lnwire.MilliSatoshi
	failures     map[edgeKey]uint32
	broken       map[edgeKey]bool

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		paymentUpper:  make(map[edgeKey]lnwire.MilliSatoshi),
		failures:      make(map[edgeKey]uint32),
		broken:        make(map[edgeKey]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	nodes := []route.Vertex{source}

	for len(nodes) != 0 {
		node := nodes[0]
		nodes = nodes[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					nodes = append(nodes, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.54 * math.Exp(-18*x)
	highMode := 0.45 / (1 + math.Exp(25*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := math.Max(1, float64(edge.capacity)*0.065)
	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))

	confidence := math.Min(0.86, 0.16*float64(belief.samples))
	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

func (r *candidateRouter) freshlyImpossible(edge *candidateEdge,
	amt lnwire.MilliSatoshi) bool {

	upper := r.paymentUpper[edge.key]
	return upper > 0 && amt+r.reserved[edge.key] >= upper
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	index := len(old) - 1
	value := old[index]
	*q = old[:index]

	return value
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
	utility     float64
}

func (r *candidateRouter) edgePenalty(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	probability := r.edgeProbability(edge, amt)
	fee := edge.fee(amt)
	if edge.key.from == r.source {
		fee = 0
	}

	failurePenalty := 0.07 * float64(r.failures[edge.key])
	return -math.Log(probability) +
		float64(fee)/5_000_000 +
		failurePenalty + 0.008
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: deliver,
	}
	next := make(map[route.Vertex]*candidateEdge)

	queue := &dijkstraQueue{}
	heap.Push(queue, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for queue.Len() != 0 {
		item := heap.Pop(queue).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.amt != required[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(item.amt) {
				continue
			}
			if r.freshlyImpossible(edge, item.amt) {
				continue
			}

			total := item.amt + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			sending := item.amt
			if edge.key.from != r.source {
				sending += edge.fee(item.amt)
			}

			candidate := item.score +
				r.edgePenalty(edge, item.amt)

			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(queue, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(
			r.edges[key], amounts[i],
		)
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New(
				"route contains a cycle",
			)
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	last := len(path) - 1
	amounts[last] = deliver
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	maximum lnwire.MilliSatoshi) {

	if maximum <= 0 {
		return
	}
	if value > maximum {
		value = maximum
	}
	if value < minShardAmount && maximum >= minShardAmount {
		value = minShardAmount
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, maxAmountChoices)

	for _, fraction := range [][2]int64{
		{1, 1},
		{9, 10},
		{4, 5},
		{7, 10},
		{3, 5},
		{1, 2},
		{2, 5},
		{1, 3},
		{1, 4},
		{1, 5},
		{1, 8},
	} {
		addAmount(
			&values, seen,
			amt*lnwire.MilliSatoshi(fraction[0])/
				lnwire.MilliSatoshi(fraction[1]),
			amt,
		)
	}

	equal := amt / lnwire.MilliSatoshi(partsLeft)
	addAmount(&values, seen, equal, amt)
	addAmount(&values, seen, equal*3/4, amt)
	addAmount(&values, seen, equal/2, amt)

	if r.lastFailedAmt > 0 {
		for _, fraction := range [][2]int64{
			{4, 5},
			{2, 3},
			{1, 2},
			{1, 3},
			{1, 4},
		} {
			addAmount(
				&values, seen,
				r.lastFailedAmt*
					lnwire.MilliSatoshi(fraction[0])/
					lnwire.MilliSatoshi(fraction[1]),
				amt,
			)
		}
	}

	type evidenceAmount struct {
		amount lnwire.MilliSatoshi
		weight int
	}

	var evidence []evidenceAmount
	for key, upper := range r.paymentUpper {
		if r.broken[key] || upper <= 1 {
			continue
		}

		evidence = append(evidence,
			evidenceAmount{upper * 9 / 10, 5},
			evidenceAmount{upper * 3 / 4, 4},
			evidenceAmount{upper / 2, 3},
		)
	}

	for key, belief := range r.beliefs {
		if r.broken[key] {
			continue
		}
		if belief.lowerOK > 0 {
			evidence = append(evidence,
				evidenceAmount{belief.lowerOK, 6},
				evidenceAmount{belief.lowerOK * 9 / 10, 5},
			)
		}
		if belief.upperFail > 1 {
			evidence = append(evidence,
				evidenceAmount{belief.upperFail * 4 / 5, 5},
				evidenceAmount{belief.upperFail * 2 / 3, 4},
			)
		}
	}

	sort.Slice(evidence, func(i, j int) bool {
		if evidence[i].weight == evidence[j].weight {
			return evidence[i].amount > evidence[j].amount
		}

		return evidence[i].weight > evidence[j].weight
	})

	for _, candidate := range evidence {
		if len(values) >= maxAmountChoices {
			break
		}
		addAmount(&values, seen, candidate.amount, amt)
	}

	if len(values) > maxAmountChoices {
		values = values[:maxAmountChoices]
	}

	return values
}

func (r *candidateRouter) reserveChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		r.reserved[key] += choice.amounts[i]
	}
}

func (r *candidateRouter) releaseChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		reserved := r.reserved[key]
		if reserved <= choice.amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - choice.amounts[i]
		}
	}
}

func choiceCost(choice *routeChoice) float64 {
	probability := math.Max(choice.probability, 0.005)
	retryCost := 1/probability - 1
	if retryCost > 15 {
		retryCost = 15
	}

	return -math.Log(probability) +
		0.12*retryCost +
		float64(choice.fee)/5_000_000 +
		0.12
}

func (r *candidateRouter) planRemainder(
	remaining lnwire.MilliSatoshi, slots, depth uint32) float64 {

	if remaining <= 0 {
		return 0
	}
	if slots == 0 {
		return uncoveredCost
	}

	if slots == 1 || depth == 0 {
		choice, err := r.findRoute(remaining)
		if err != nil {
			return uncoveredCost
		}

		return choiceCost(choice)
	}

	amounts := r.candidateAmounts(remaining, slots)
	best := math.Inf(1)
	limit := len(amounts)
	if limit > maxPlanBranches {
		limit = maxPlanBranches
	}

	for _, shard := range amounts[:limit] {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		r.reserveChoice(choice)
		rest := r.planRemainder(
			remaining-shard, slots-1, depth-1,
		)
		r.releaseChoice(choice)

		progress := float64(shard) / float64(remaining)
		cost := choiceCost(choice) + rest +
			0.18*(1-progress)
		if cost < best {
			best = cost
		}
	}

	if math.IsInf(best, 1) {
		return uncoveredCost
	}

	return best
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	amounts := r.candidateAmounts(amt, partsLeft)

	var best *routeChoice
	for _, shard := range amounts {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		r.reserveChoice(choice)

		depth := uint32(maxPlanningDepth)
		if partsLeft-1 < depth {
			depth = partsLeft - 1
		}
		continuation := r.planRemainder(
			amt-shard, partsLeft-1, depth,
		)

		r.releaseChoice(choice)

		progress := float64(shard) / float64(amt)
		choice.utility = choiceCost(choice) +
			continuation + 0.20*(1-progress)

		if continuation >= uncoveredCost {
			choice.utility += uncoveredCost
		}

		if best == nil || choice.utility < best.utility {
			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.reserveChoice(best)
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	fresh := r.paymentUpper[key]
	if fresh == 0 || amt < fresh {
		r.paymentUpper[key] = amt
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	depletedEstimate := amt / 8
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = depletedEstimate
	} else {
		belief.estimate =
			(4*belief.estimate + depletedEstimate) / 5
	}

	if belief.upperFail > 0 &&
		belief.lowerOK >= belief.upperFail {

		belief.lowerOK = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnProbeSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.estimate < amt {
		belief.estimate = amt
	}

	optimistic := edge.capacity * 4 / 5
	if belief.estimate < optimistic {
		belief.estimate =
			(belief.estimate + optimistic) / 2
	}
	if belief.upperFail > 0 &&
		belief.upperFail <= belief.lowerOK {

		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	if belief.upperFail > 0 &&
		belief.lowerOK >= belief.upperFail {

		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}
	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) releaseRoute(keys []edgeKey,
	amounts []lnwire.MilliSatoshi) {

	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	r.releaseRoute(keys, amounts)

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.failures[key] > 0 {
				r.failures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i := 0; i+1 < len(rt.Hops); i++ {
			if rt.Hops[i].PubKeyBytes ==
				result.FailureSource {

				failIndex = i + 1
				break
			}
		}
	}

	r.lastFailedAmt =
		rt.Hops[len(rt.Hops)-1].AmtToForward

	if failIndex < 0 || failIndex >= len(keys) {
		for _, key := range keys {
			r.failures[key]++
		}

		return nil
	}

	for i := 0; i < failIndex; i++ {
		r.learnProbeSuccess(keys[i], amounts[i])
		if r.failures[keys[i]] > 0 {
			r.failures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.failures[key]++
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true

	default:
		r.failures[key]++
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	maxAttempts    = 48
	maxPlanParts   = 20
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved       map[edgeKey]lnwire.MilliSatoshi
	failedCeilings map[edgeKey]lnwire.MilliSatoshi
	edgeFailures   map[edgeKey]uint32
	broken         map[edgeKey]bool
	routeTries     map[uint64]uint32

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[edgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		beliefs:        make(map[edgeKey]liquidityBelief),
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		failedCeilings: make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:   make(map[edgeKey]uint32),
		broken:         make(map[edgeKey]bool),
		routeTries:     make(map[uint64]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, exists := r.edges[key]; exists {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, exists := sharedBeliefs.values[key]
		if !exists {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := math.Max(float64(edge.capacity)*0.10, 1)
	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))

	confidence := math.Min(0.80, 0.20*float64(belief.samples))
	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: deliver,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, exists := score[item.node]
		if !exists || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		needed := required[item.node]
		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(needed) {
				continue
			}

			total := needed + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}

			if ceiling := r.failedCeilings[edge.key]; ceiling > 0 &&
				total >= ceiling {

				continue
			}

			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, needed)
			edgeFee := edge.fee(needed)
			sending := needed + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = needed
			}
			if sending <= 0 {
				continue
			}

			failurePenalty := 0.22 *
				float64(r.edgeFailures[edge.key])
			step := -math.Log(probability) +
				float64(edgeFee)/2_500_000 +
				0.012 + failurePenalty
			candidateScore := item.score + step

			old, exists := score[edge.key.from]
			if exists && candidateScore >= old {
				continue
			}

			score[edge.key.from] = candidateScore
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidateScore,
			})
		}
	}

	if _, exists := next[r.source]; !exists {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(r.edges[key], amounts[i])
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, exists := next[node]
		if !exists {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))

	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func routeFingerprint(rt *route.Route) uint64 {
	hash := uint64(1469598103934665603)
	mix := func(value byte) {
		hash ^= uint64(value)
		hash *= 1099511628211
	}

	amount := uint64(rt.Hops[len(rt.Hops)-1].AmtToForward)
	for i := 0; i < 8; i++ {
		mix(byte(amount >> (8 * i)))
	}

	for _, hop := range rt.Hops {
		for i := 0; i < 8; i++ {
			mix(byte(hop.ChannelID >> (8 * i)))
		}
		for _, value := range hop.PubKeyBytes {
			mix(value)
		}
	}

	return hash
}

func (r *candidateRouter) reserveChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		r.reserved[key] += choice.amounts[i]
	}
}

func (r *candidateRouter) releaseChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		value := r.reserved[key]
		if value <= choice.amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = value - choice.amounts[i]
		}
	}
}

func balancedShards(total lnwire.MilliSatoshi,
	parts int) []lnwire.MilliSatoshi {

	result := make([]lnwire.MilliSatoshi, parts)
	base := total / lnwire.MilliSatoshi(parts)
	extra := total % lnwire.MilliSatoshi(parts)

	for i := range result {
		result[i] = base
		if lnwire.MilliSatoshi(i) < extra {
			result[i]++
		}
	}

	return result
}

func skewedShards(total lnwire.MilliSatoshi,
	parts int) []lnwire.MilliSatoshi {

	if parts <= 1 {
		return []lnwire.MilliSatoshi{total}
	}

	weights := make([]float64, parts)
	sum := 0.0
	for i := range weights {
		position := float64(i) / float64(parts-1)
		weights[i] = 1.35 - 0.70*position
		sum += weights[i]
	}

	result := make([]lnwire.MilliSatoshi, parts)
	remaining := total
	for i := 0; i < parts-1; i++ {
		value := lnwire.MilliSatoshi(
			float64(total) * weights[i] / sum,
		)
		if value < 1 {
			value = 1
		}

		maximum := remaining -
			lnwire.MilliSatoshi(parts-i-1)
		if value > maximum {
			value = maximum
		}

		result[i] = value
		remaining -= value
	}
	result[parts-1] = remaining

	return result
}

func (r *candidateRouter) evaluatePlan(
	shards []lnwire.MilliSatoshi) (*routeChoice, float64, bool) {

	choices := make([]*routeChoice, 0, len(shards))
	utility := 0.035 * float64(len(shards))

	defer func() {
		for i := len(choices) - 1; i >= 0; i-- {
			r.releaseChoice(choices[i])
		}
	}()

	for _, shard := range shards {
		choice, err := r.findRoute(shard)
		if err != nil {
			return nil, 0, false
		}

		if len(choices) == 0 {
			fingerprint := routeFingerprint(choice.route)
			if r.routeTries[fingerprint] >= 2 {
				return nil, 0, false
			}
		}

		utility += -math.Log(choice.probability)
		utility += float64(choice.fee) / 2_000_000
		r.reserveChoice(choice)
		choices = append(choices, choice)
	}

	if len(choices) == 0 {
		return nil, 0, false
	}

	return choices[0], utility, true
}

func addAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) fallbackAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 16)

	addAmount(&values, seen, amt, minimum, amt)
	addAmount(&values, seen, amt*7/8, minimum, amt)
	addAmount(&values, seen, amt*3/4, minimum, amt)
	addAmount(&values, seen, amt*2/3, minimum, amt)
	addAmount(&values, seen, amt*3/5, minimum, amt)
	addAmount(&values, seen, amt/2, minimum, amt)
	addAmount(&values, seen, amt*2/5, minimum, amt)
	addAmount(&values, seen, amt/3, minimum, amt)
	addAmount(&values, seen, amt/4, minimum, amt)
	addAmount(&values, seen, minimum*2, minimum, amt)
	addAmount(&values, seen, minimum*3/2, minimum, amt)
	addAmount(&values, seen, minimum, minimum, amt)

	if r.lastFailedAmt > 0 {
		addAmount(
			&values, seen, r.lastFailedAmt*2/3,
			minimum, amt,
		)
		addAmount(
			&values, seen, r.lastFailedAmt/2,
			minimum, amt,
		)
		addAmount(
			&values, seen, r.lastFailedAmt*2/5,
			minimum, amt,
		)
	}

	var bounds []lnwire.MilliSatoshi
	for key, ceiling := range r.failedCeilings {
		if r.broken[key] || ceiling <= 1 {
			continue
		}

		for _, numerator := range []lnwire.MilliSatoshi{3, 2, 1} {
			bound := ceiling * numerator / 4
			if bound >= minimum && bound <= amt {
				bounds = append(bounds, bound)
			}
		}
	}

	sort.Slice(bounds, func(i, j int) bool {
		return bounds[i] > bounds[j]
	})
	if len(bounds) > 6 {
		bounds = bounds[:6]
	}
	for _, bound := range bounds {
		addAmount(&values, seen, bound, minimum, amt)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	return values
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	planLimit := int(partsLeft)
	if planLimit > maxPlanParts {
		planLimit = maxPlanParts
	}

	var best *routeChoice
	bestUtility := math.Inf(1)

	for parts := 1; parts <= planLimit; parts++ {
		plans := [][]lnwire.MilliSatoshi{
			balancedShards(amt, parts),
		}
		if parts >= 2 {
			plans = append(plans, skewedShards(amt, parts))
		}

		for _, shards := range plans {
			choice, utility, ok := r.evaluatePlan(shards)
			if !ok {
				continue
			}
			if utility < bestUtility {
				best = choice
				bestUtility = utility
			}
		}
	}

	if best == nil {
		for _, shard := range r.fallbackAmounts(amt, partsLeft) {
			choice, err := r.findRoute(shard)
			if err != nil {
				continue
			}

			fingerprint := routeFingerprint(choice.route)
			if r.routeTries[fingerprint] >= 2 {
				continue
			}

			remainingParts := math.Ceil(
				float64(amt) / float64(shard),
			)
			choice.utility = -math.Log(choice.probability) +
				0.08*remainingParts +
				float64(choice.fee)/2_000_000

			if best == nil || choice.utility < bestUtility {
				best = choice
				bestUtility = choice.utility
			}
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.reserveChoice(best)
	r.routeTries[routeFingerprint(best.route)]++
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnPass(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.estimate < amt {
		belief.estimate = amt
	}
	if belief.upperFail > 0 && belief.upperFail <= belief.lowerOK {
		belief.upperFail = 0
	}
	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	target := amt / 4
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = target
	} else {
		belief.estimate = (3*belief.estimate + target) / 4
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}

	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	r.lastFailedAmt = delivered

	if failIndex < 0 || failIndex >= len(keys) {
		for i, key := range keys {
			r.edgeFailures[key]++
			ceiling := r.failedCeilings[key]
			if ceiling == 0 || amounts[i] < ceiling {
				r.failedCeilings[key] = amounts[i]
			}
		}

		return nil
	}

	for i := 0; i < failIndex; i++ {
		r.learnPass(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	r.edgeFailures[key] += 3

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		ceiling := r.failedCeilings[key]
		if ceiling == 0 || failedAmt < ceiling {
			r.failedCeilings[key] = failedAmt
		}
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true

	default:
		ceiling := r.failedCeilings[key]
		if ceiling == 0 || failedAmt < ceiling {
			r.failedCeilings[key] = failedAmt
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	maxAttempts    = 96
	minShardAmount = lnwire.MilliSatoshi(1_000)
	maxAmounts     = 18
	planDepth      = 4
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incoming map[route.Vertex][]*candidateEdge
	edges    map[edgeKey]*candidateEdge
	local    map[uint64]lnwire.MilliSatoshi

	beliefs map[edgeKey]liquidityBelief
	reserved map[edgeKey]lnwire.MilliSatoshi
	freshFail map[edgeKey]lnwire.MilliSatoshi
	failures map[edgeKey]uint32
	broken   map[edgeKey]bool

	lastFailed lnwire.MilliSatoshi
	attempts   uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:    source,
		spec:      spec,
		incoming:  make(map[route.Vertex][]*candidateEdge),
		edges:     make(map[edgeKey]*candidateEdge),
		local:     make(map[uint64]lnwire.MilliSatoshi),
		beliefs:   make(map[edgeKey]liquidityBelief),
		reserved:  make(map[edgeKey]lnwire.MilliSatoshi),
		freshFail: make(map[edgeKey]lnwire.MilliSatoshi),
		failures:  make(map[edgeKey]uint32),
		broken:    make(map[edgeKey]bool),
	}

	for chanID, balance := range localBalances {
		r.local[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	pending := []route.Vertex{source}

	for len(pending) != 0 {
		node := pending[0]
		pending = pending[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					pending = append(pending, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incoming[node] = append(r.incoming[node], edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	if p < 0.003 {
		return 0.003
	}
	if p > 0.989 {
		return 0.989
	}

	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.003
	}

	x := float64(amt) / float64(capacity)
	low := 0.52 * math.Exp(-21*x)
	high := 0.47 / (1 + math.Exp(25*(x-0.88)))

	return clampProbability(low + high)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.001
	}

	if edge.key.from == r.source {
		if total <= r.local[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.997
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		over := float64(total) / float64(belief.upperFail)
		return clampProbability(0.008 / math.Max(1, over))
	}

	scale := math.Max(1, float64(edge.capacity)*0.065)
	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))

	confidence := math.Min(0.88, 0.19*float64(belief.samples))
	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

func (r *candidateRouter) failurePenalty(key edgeKey,
	amt lnwire.MilliSatoshi) float64 {

	count := r.failures[key]
	if count == 0 {
		return 0
	}

	upper := r.freshFail[key]
	if upper == 0 {
		return math.Min(1.2, 0.22*float64(count))
	}

	ratio := float64(amt+r.reserved[key]) / float64(upper)
	if ratio >= 1 {
		return math.Min(4.5, 1.35+0.48*float64(count))
	}

	return math.Min(
		1.5,
		0.16*float64(count)*ratio*ratio,
	)
}

type pathItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type pathQueue []*pathItem

func (q pathQueue) Len() int {
	return len(q)
}

func (q pathQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q pathQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *pathQueue) Push(value any) {
	*q = append(*q, value.(*pathItem))
}

func (q *pathQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	rt          *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
	cost        float64
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	scores := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)
	pq := &pathQueue{}
	heap.Push(pq, &pathItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*pathItem)
		best, ok := scores[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incoming[item.node] {
			if r.broken[edge.key] || !edge.usable(item.amt) {
				continue
			}

			total := item.amt + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.local[edge.key.chanID] {

				continue
			}

			p := r.edgeProbability(edge, item.amt)
			fee := edge.fee(item.amt)
			sending := item.amt + fee
			if edge.key.from == r.source {
				fee = 0
				sending = item.amt
			}

			step := -math.Log(p) +
				r.failurePenalty(edge.key, item.amt) +
				float64(fee)/5_000_000 +
				0.012
			candidate := item.score + step

			old, exists := scores[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			scores[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &pathItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(r.edges[key], amounts[i])
	}
	probability = math.Max(probability, 0.000001)

	return &routeChoice{
		rt:          rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	last := len(path) - 1
	amounts[last] = deliver
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	minimum := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)
	if minimum < minShardAmount {
		minimum = minShardAmount
	}
	if minimum > remaining {
		minimum = remaining
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, maxAmounts+12)

	for _, fraction := range [][2]int64{
		{1, 1},
		{9, 10},
		{4, 5},
		{3, 4},
		{2, 3},
		{3, 5},
		{1, 2},
		{2, 5},
		{1, 3},
	} {
		addCandidate(
			&values, seen,
			remaining*lnwire.MilliSatoshi(fraction[0])/
				lnwire.MilliSatoshi(fraction[1]),
			minimum, remaining,
		)
	}

	addCandidate(&values, seen, minimum, minimum, remaining)
	addCandidate(
		&values, seen, minimum*5/4, minimum, remaining,
	)
	addCandidate(
		&values, seen, minimum*3/2, minimum, remaining,
	)
	addCandidate(
		&values, seen, minimum*2, minimum, remaining,
	)

	var evidence []lnwire.MilliSatoshi
	for key, upper := range r.freshFail {
		if r.broken[key] || upper <= 1 {
			continue
		}

		evidence = append(
			evidence,
			upper*19/20,
			upper*17/20,
			upper*3/4,
			upper*2/3,
			upper/2,
		)
	}

	for key, belief := range r.beliefs {
		if r.broken[key] {
			continue
		}

		if belief.lowerOK > 0 {
			evidence = append(
				evidence,
				belief.lowerOK,
				belief.lowerOK*9/10,
				belief.lowerOK*3/4,
			)
		}
		if belief.estimate > 0 {
			evidence = append(
				evidence,
				belief.estimate*9/10,
				belief.estimate*3/4,
			)
		}
		if belief.upperFail > 1 {
			evidence = append(
				evidence,
				belief.upperFail*17/20,
				belief.upperFail*2/3,
			)
		}
	}

	if r.lastFailed > 0 {
		evidence = append(
			evidence,
			r.lastFailed*17/20,
			r.lastFailed*3/4,
			r.lastFailed*2/3,
			r.lastFailed/2,
		)
	}

	sort.Slice(evidence, func(i, j int) bool {
		return evidence[i] > evidence[j]
	})
	if len(evidence) > 16 {
		evidence = evidence[:16]
	}

	for _, value := range evidence {
		addCandidate(
			&values, seen, value, minimum, remaining,
		)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})
	if len(values) > maxAmounts {
		values = values[:maxAmounts]
	}

	return values
}

func (r *candidateRouter) reserve(choice *routeChoice) {
	for i, key := range choice.keys {
		r.reserved[key] += choice.amounts[i]
	}
}

func (r *candidateRouter) release(choice *routeChoice) {
	for i, key := range choice.keys {
		current := r.reserved[key]
		if current <= choice.amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = current - choice.amounts[i]
		}
	}
}

func routeCost(choice *routeChoice) float64 {
	retries := 1/choice.probability - 1
	if retries > 16 {
		retries = 16
	}

	return -math.Log(choice.probability) +
		0.12*retries +
		float64(choice.fee)/5_000_000 +
		0.16
}

func (r *candidateRouter) plan(remaining lnwire.MilliSatoshi,
	slots, depth uint32) float64 {

	if remaining <= 0 {
		return 0
	}
	if slots == 0 {
		return 24
	}

	if depth == 0 {
		choice, err := r.findRoute(remaining)
		if err != nil {
			return 24
		}

		return routeCost(choice)
	}

	amounts := r.candidateAmounts(remaining, slots)
	limit := len(amounts)
	if limit > 9 {
		limit = 9
	}

	best := math.Inf(1)
	for _, shard := range amounts[:limit] {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		r.reserve(choice)
		continuation := r.plan(
			remaining-shard, slots-1, depth-1,
		)
		r.release(choice)

		progress := float64(shard) / float64(remaining)
		cost := routeCost(choice) + continuation +
			0.26*(1-progress)
		if cost < best {
			best = cost
		}
	}

	if math.IsInf(best, 1) {
		return 24
	}

	return best
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	slots := r.spec.MaxParts - inFlightHtlcs
	amounts := r.candidateAmounts(amt, slots)

	var best *routeChoice
	for _, shard := range amounts {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		r.reserve(choice)
		depth := uint32(planDepth)
		if slots-1 < depth {
			depth = slots - 1
		}
		continuation := r.plan(
			amt-shard, slots-1, depth,
		)
		r.release(choice)

		progress := float64(shard) / float64(amt)
		choice.cost = routeCost(choice) + continuation +
			0.34*(1-progress)

		if best == nil || choice.cost < best.cost {
			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.reserve(best)
	r.attempts++

	return best.rt, nil
}

func routeEdges(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(key edgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	fresh := r.freshFail[key]
	if fresh == 0 || amt < fresh {
		r.freshFail[key] = amt
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	depleted := amt / 8
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = depleted
	} else {
		belief.estimate = (4*belief.estimate + depleted) / 5
	}

	if belief.upperFail > 0 &&
		belief.lowerOK >= belief.upperFail {

		belief.lowerOK = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnProbeSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}

	optimistic := edge.capacity * 4 / 5
	if belief.estimate < optimistic {
		belief.estimate =
			(2*belief.estimate + optimistic) / 3
	}

	if belief.upperFail > 0 &&
		belief.upperFail <= belief.lowerOK {

		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= amount+floor {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	estimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if estimate < optimistic {
		estimate = (estimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(estimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	if belief.upperFail > 0 &&
		belief.lowerOK >= belief.upperFail {

		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}
	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) releaseRoute(keys []edgeKey,
	amounts []lnwire.MilliSatoshi) {

	for i, key := range keys {
		current := r.reserved[key]
		if current <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = current - amounts[i]
		}
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdges(rt)
	r.releaseRoute(keys, amounts)

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.local[key.chanID]
				if amounts[i] >= balance {
					r.local[key.chanID] = 0
				} else {
					r.local[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.failures[key] > 0 {
				r.failures[key]--
			}
			delete(r.freshFail, key)
		}

		r.lastFailed = 0
		return nil
	}

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i := 0; i+1 < len(rt.Hops); i++ {
			if rt.Hops[i].PubKeyBytes ==
				result.FailureSource {

				failIndex = i + 1
				break
			}
		}
	}

	r.lastFailed = rt.Hops[len(rt.Hops)-1].AmtToForward

	if failIndex < 0 || failIndex >= len(keys) {
		for _, key := range keys {
			if r.failures[key] < 12 {
				r.failures[key]++
			}
		}

		return nil
	}

	for i := 0; i < failIndex; i++ {
		r.learnProbeSuccess(keys[i], amounts[i])
		if r.failures[keys[i]] > 0 {
			r.failures[keys[i]]--
		}
	}

	key := keys[failIndex]
	if r.failures[key] < 12 {
		r.failures[key] += 2
	}

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, amounts[failIndex])

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta   = uint32(40)
	riskCostMsat     = 300000.0
	minProbability   = 0.003
	maxProbability   = 0.995
	lowerRetryFactor = 0.67
	maxShardChoices  = 128
	feeQualityWeight = 2500.0
	missingPlanCost  = 18.0
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]liquidityBelief
	blocked       map[candidateEdgeKey]bool
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty  map[candidateEdgeKey]float64
	failureCount  map[candidateEdgeKey]uint32

	baseShard           lnwire.MilliSatoshi
	lastRemaining       lnwire.MilliSatoshi
	consecutiveFailures uint32
	failureCeiling      lnwire.MilliSatoshi
	lastFailed          candidateEdgeKey
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[candidateEdgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[candidateEdgeKey]liquidityBelief),
		blocked:       make(map[candidateEdgeKey]bool),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:  make(map[candidateEdgeKey]float64),
		failureCount:  make(map[candidateEdgeKey]uint32),
		lastRemaining: spec.Amount,
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	parts := uint32(1)
	switch {
	case spec.Amount > 1_000_000_000:
		parts = 6
	case spec.Amount > 250_000_000:
		parts = 4
	case spec.Amount > 50_000_000:
		parts = 2
	}
	if parts > spec.MaxParts {
		parts = spec.MaxParts
	}
	if parts == 0 {
		parts = 1
	}
	r.baseShard = ceilDiv(
		spec.Amount, lnwire.MilliSatoshi(parts),
	)

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, ok := r.edgeByKey[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}
	return (a + b - 1) / b
}

func clampAmount(amt, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if amt < 0 {
		return 0
	}
	if amt > capacity {
		return capacity
	}
	return amt
}

func clampProbability(p float64) float64 {
	if p < minProbability {
		return minProbability
	}
	if p > maxProbability {
		return maxProbability
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.505 * math.Exp(-x/0.026)
	highMode := 0.475 / (1 + math.Exp(14.5*(x-0.79)))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) availableLocal(
	key candidateEdgeKey) lnwire.MilliSatoshi {

	available := r.localBalances[key.chanID]
	reserved := r.reserved[key]
	if reserved >= available {
		return 0
	}
	return available - reserved
}

func (r *candidateRouter) exposure(edge *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	reserved := r.reserved[edge.key]
	if reserved >= edge.capacity ||
		amt > edge.capacity-reserved {

		return edge.capacity + 1
	}
	return amt + reserved
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	exposure := r.exposure(edge, amt)
	if exposure > edge.capacity {
		return minProbability
	}

	if edge.key.from == r.source {
		if amt > r.availableLocal(edge.key) {
			return minProbability
		}
		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && exposure >= belief.upperBad {
		return minProbability
	}
	if belief.lowerOK != 0 && exposure <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(exposure, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.065, 1)
	point := 1 / (1 + math.Exp(
		(float64(exposure)-float64(belief.estimate))/width,
	))

	weight := 0.50
	if belief.lowerOK != 0 || belief.upperBad != 0 {
		weight = 0.68
	}

	return clampProbability((1-weight)*prior + weight*point)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		bestScore, ok := dist[item.node]
		if !ok || item.score > bestScore {
			continue
		}
		if item.arriving != required[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) {
				continue
			}

			reserved := r.reserved[edge.key]
			if reserved >= edge.capacity ||
				amtOver > edge.capacity-reserved {

				continue
			}

			if edge.key.from == r.source &&
				amtOver > r.availableLocal(edge.key) {

				continue
			}

			exposure := amtOver + reserved
			belief := r.beliefs[edge.key]
			if edge.key.from != r.source &&
				belief.upperBad != 0 &&
				exposure >= belief.upperBad {

				continue
			}

			probability := r.probability(edge, amtOver)
			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			}

			risk := -math.Log(probability) * riskCostMsat
			score := item.score + float64(fee) + risk +
				r.routePenalty[edge.key] + 200

			if edge.key == r.lastFailed {
				score += riskCostMsat * 0.12
			}

			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edgeByKey) {
			return nil, errors.New("route contains a cycle")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, ok := r.edgeByKey[key]
	return key, ok
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.reserved[key] += routeAmount(rt, i)
		}
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func addShardChoice(values map[lnwire.MilliSatoshi]struct{},
	candidate, maximum lnwire.MilliSatoshi) {

	if candidate <= 0 || candidate > maximum {
		return
	}
	values[candidate] = struct{}{}
}

func (r *candidateRouter) shardChoices(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	values := make(map[lnwire.MilliSatoshi]struct{})
	add := func(candidate lnwire.MilliSatoshi) {
		addShardChoice(values, candidate, amt)
	}

	ideal := ceilDiv(amt, lnwire.MilliSatoshi(partsLeft))
	add(amt)
	add(ideal)
	add(r.baseShard)

	for parts := uint32(2); parts <= partsLeft; parts++ {
		equal := ceilDiv(amt, lnwire.MilliSatoshi(parts))
		add(equal)
		add(equal * 5 / 4)
		add(equal * 4 / 5)
		add(equal * 2 / 3)
		add(equal / 2)
	}

	for _, ratio := range []int64{
		92, 84, 76, 68, 60, 52, 45, 38, 32, 26, 20, 15,
	} {
		add(amt * lnwire.MilliSatoshi(ratio) / 100)
	}

	if r.failureCeiling != 0 {
		add(r.failureCeiling)
		add(r.failureCeiling * 9 / 10)
		add(r.failureCeiling * 3 / 4)
	}

	for key, edge := range r.edgeByKey {
		if key.from == r.source {
			available := r.availableLocal(key)
			add(available)
			add(available * 9 / 10)
			continue
		}

		belief := r.beliefs[key]
		if belief.lowerOK != 0 {
			add(belief.lowerOK)
			add(belief.lowerOK * 9 / 10)
			add(belief.lowerOK * 3 / 4)
		}
		if belief.estimate != 0 {
			add(belief.estimate * 9 / 10)
			add(belief.estimate * 2 / 3)
		}
		if belief.upperBad != 0 {
			if belief.upperBad > 1 {
				add(belief.upperBad - 1)
			}
			add(belief.upperBad * 2 / 3)
			add(belief.upperBad / 2)
		} else {
			add(edge.capacity * 7 / 10)
			add(edge.capacity * 9 / 20)
		}
	}

	choices := make([]lnwire.MilliSatoshi, 0, len(values))
	for value := range values {
		choices = append(choices, value)
	}

	sort.Slice(choices, func(i, j int) bool {
		a := math.Abs(math.Log(
			float64(choices[i]) / float64(ideal),
		))
		b := math.Abs(math.Log(
			float64(choices[j]) / float64(ideal),
		))
		if a == b {
			return choices[i] > choices[j]
		}
		return a < b
	})

	if len(choices) > maxShardChoices {
		choices = choices[:maxShardChoices]
	}

	return choices
}

func (r *candidateRouter) routeQuality(rt *route.Route) float64 {
	delivered := deliveredAmount(rt)
	if delivered <= 0 {
		return math.Inf(1)
	}

	negativeLogProbability := 0.0
	penalty := 0.0
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			return math.Inf(1)
		}

		edge := r.edgeByKey[key]
		probability := r.probability(
			edge, routeAmount(rt, i),
		)
		negativeLogProbability -= math.Log(probability)
		penalty += r.routePenalty[key] / riskCostMsat
	}

	fee := rt.TotalAmount - delivered
	feeCost := feeQualityWeight *
		float64(fee) / float64(delivered)
	hopCost := 0.006 * float64(len(rt.Hops))

	return negativeLogProbability + feeCost + penalty + hopCost
}

func (r *candidateRouter) plannedQuality(rt *route.Route,
	remaining lnwire.MilliSatoshi, partsLeft uint32) float64 {

	shard := deliveredAmount(rt)
	quality := r.routeQuality(rt)
	if shard >= remaining {
		return quality - 0.35
	}
	if partsLeft <= 1 {
		return math.Inf(1)
	}

	after := remaining - shard
	futureParts := partsLeft - 1
	nextNeed := ceilDiv(
		after, lnwire.MilliSatoshi(futureParts),
	)

	r.reserve(rt)
	nextRoute, err := r.findRoute(nextNeed)
	if err == nil {
		nextQuality := r.routeQuality(nextRoute)
		quality += 0.40 * nextQuality

		if futureParts > 1 && nextNeed < after {
			r.reserve(nextRoute)
			lastNeed := ceilDiv(
				after-nextNeed,
				lnwire.MilliSatoshi(futureParts-1),
			)
			_, secondErr := r.findRoute(lastNeed)
			r.release(nextRoute)
			if secondErr != nil {
				quality += missingPlanCost * 0.45
			}
		}
	} else {
		quality += missingPlanCost
	}
	r.release(rt)

	progress := float64(shard) / float64(remaining)
	quality -= 0.30 * progress

	return quality
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 ||
		inFlightHtlcs >= r.spec.MaxParts {

		return nil, errors.New("maximum parts in flight")
	}

	if amt < r.lastRemaining {
		r.consecutiveFailures = 0
		r.failureCeiling = 0
		r.lastFailed = candidateEdgeKey{}
	}
	r.lastRemaining = amt

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	choices := r.shardChoices(amt, partsLeft)

	var (
		bestRoute   *route.Route
		bestQuality = math.Inf(1)
		lastErr     error
	)

	for _, shard := range choices {
		rt, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		quality := r.plannedQuality(rt, amt, partsLeft)
		if quality < bestQuality {
			bestQuality = quality
			bestRoute = rt
		}
	}

	if bestRoute == nil {
		if lastErr == nil {
			lastErr = errors.New("no route found")
		}
		return nil, lastErr
	}

	r.reserve(bestRoute)
	return bestRoute, nil
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	edge := r.edgeByKey[key]
	if edge != nil {
		belief.lowerOK = clampAmount(
			belief.lowerOK, edge.capacity,
		)
		belief.estimate = clampAmount(
			belief.estimate, edge.capacity,
		)
		if belief.upperBad > edge.capacity {
			belief.upperBad = 0
		}
		if belief.upperBad != 0 &&
			belief.lowerOK >= belief.upperBad {

			belief.lowerOK = belief.upperBad - 1
			if belief.lowerOK < 0 {
				belief.lowerOK = 0
			}
		}
	}

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordPass(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	estimate := amt + (edge.capacity-amt)*4/5
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) settleLiquidity(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil {
		return
	}

	if key.from == r.source {
		balance := r.localBalances[key.chanID]
		if amt >= balance {
			r.localBalances[key.chanID] = 0
		} else {
			r.localBalances[key.chanID] = balance - amt
		}
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK > amt {
		belief.lowerOK -= amt
	} else {
		belief.lowerOK = 0
	}

	if belief.upperBad > amt {
		belief.upperBad -= amt
	} else {
		belief.upperBad = 0
	}

	minimumEstimate := amt + (edge.capacity-amt)*4/5
	if belief.estimate < minimumEstimate {
		belief.estimate = minimumEstimate
	}
	if belief.estimate > amt {
		belief.estimate -= amt
	} else {
		belief.estimate = 0
	}

	r.saveBelief(key, belief)

	reverseKey := candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edgeByKey[reverseKey]
	if reverseEdge == nil || reverseKey.from == r.source {
		return
	}

	reverse := r.beliefs[reverseKey]
	if reverse.lowerOK < amt {
		reverse.lowerOK = amt
	}
	reverse.estimate = clampAmount(
		reverse.estimate+amt, reverseEdge.capacity,
	)
	if reverse.estimate < reverse.lowerOK {
		reverse.estimate = reverse.lowerOK
	}
	if reverse.upperBad != 0 &&
		reverse.upperBad <= reverse.lowerOK {

		reverse.upperBad = 0
	}

	r.saveBelief(reverseKey, reverse)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	amt += r.reserved[key]
	if amt > edge.capacity {
		amt = edge.capacity
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt * 32 / 100
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			amt := routeAmount(rt, i)
			r.recordPass(key, amt)
			r.settleLiquidity(key, amt)
			r.routePenalty[key] *= 0.18
			r.failureCount[key] = 0
		}

		r.consecutiveFailures = 0
		r.failureCeiling = 0
		r.lastFailed = candidateEdgeKey{}
		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if ok {
				r.routePenalty[key] += riskCostMsat / 3
			}
		}
		r.consecutiveFailures++
		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.recordPass(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.70
		}
	}

	key, ok := r.routeEdge(rt, failIndex)
	if !ok {
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	default:
		failedAmount := routeAmount(rt, failIndex)
		r.recordFailure(key, failedAmount)
		r.failureCount[key]++
		r.lastFailed = key

		multiplier := 1.0
		if r.failureCount[key] > 3 {
			multiplier = 1.7
		}
		r.routePenalty[key] += riskCostMsat * multiplier
	}

	r.consecutiveFailures++
	delivered := deliveredAmount(rt)
	ceiling := lnwire.MilliSatoshi(
		float64(delivered) * lowerRetryFactor,
	)
	if ceiling > 0 &&
		(r.failureCeiling == 0 ||
			ceiling < r.failureCeiling) {

		r.failureCeiling = ceiling
	}

	if r.consecutiveFailures >= 2 &&
		ceiling > 0 && ceiling < r.baseShard {

		r.baseShard = ceiling
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta    = 40
	maxRouteAttempts  = 48
	maxAmountChoices  = 24
	probabilityFloor  = 0.005
	probabilityCeiling = 0.985
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved     map[edgeKey]lnwire.MilliSatoshi
	edgeFailures map[edgeKey]uint32
	broken       map[edgeKey]bool

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:  make(map[edgeKey]uint32),
		broken:        make(map[edgeKey]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, exists := r.edges[key]; exists {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < probabilityFloor:
		return probabilityFloor

	case p > probabilityCeiling:
		return probabilityCeiling

	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return probabilityFloor
	}

	x := float64(amt) / float64(capacity)

	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) availableBudget(
	edge *candidateEdge) lnwire.MilliSatoshi {

	budget := edge.capacity
	if edge.key.from == r.source {
		budget = r.localBalances[edge.key.chanID]
	}

	reserved := r.reserved[edge.key]
	if reserved >= budget {
		return 0
	}

	return budget - reserved
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return probabilityFloor
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return probabilityFloor
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := float64(edge.capacity) * 0.09
	if scale < 1 {
		scale = 1
	}

	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))

	confidence := math.Min(0.80, 0.20*float64(belief.samples))
	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: deliver,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		needed := required[item.node]
		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(needed) {
				continue
			}
			if needed > r.availableBudget(edge) {
				continue
			}

			probability := r.edgeProbability(edge, needed)
			edgeFee := edge.fee(needed)
			sending := needed + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = needed
			}

			failurePenalty := 0.22 *
				float64(r.edgeFailures[edge.key])
			reservationRatio := float64(r.reserved[edge.key]) /
				math.Max(1, float64(edge.capacity))

			step := -math.Log(probability) +
				float64(edgeFee)/2_500_000 +
				0.012 +
				failurePenalty +
				0.30*reservationRatio

			candidate := item.score + step
			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(
			r.edges[key], amounts[i],
		)
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New(
				"route contains a cycle",
			)
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}
	if minimum > amt {
		minimum = amt
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, maxAmountChoices*2)

	ratios := [][2]int64{
		{1, 1},
		{7, 8},
		{4, 5},
		{3, 4},
		{2, 3},
		{3, 5},
		{1, 2},
		{2, 5},
		{1, 3},
		{1, 4},
	}
	for _, ratio := range ratios {
		addCandidate(
			&values, seen,
			amt*lnwire.MilliSatoshi(ratio[0])/
				lnwire.MilliSatoshi(ratio[1]),
			minimum, amt,
		)
	}

	addCandidate(&values, seen, minimum, minimum, amt)
	addCandidate(
		&values, seen, minimum*5/4, minimum, amt,
	)
	addCandidate(
		&values, seen, minimum*3/2, minimum, amt,
	)
	addCandidate(
		&values, seen, minimum*2, minimum, amt,
	)

	if r.lastFailedAmt > 0 {
		for _, ratio := range [][2]int64{
			{7, 8},
			{3, 4},
			{2, 3},
			{1, 2},
		} {
			addCandidate(
				&values, seen,
				r.lastFailedAmt*
					lnwire.MilliSatoshi(ratio[0])/
					lnwire.MilliSatoshi(ratio[1]),
				minimum, amt,
			)
		}
	}

	type breakpoint struct {
		value    lnwire.MilliSatoshi
		strength int
	}

	breakpoints := make([]breakpoint, 0, len(r.beliefs)*3)
	for key, belief := range r.beliefs {
		if r.broken[key] {
			continue
		}

		reserved := r.reserved[key]
		addBreakpoint := func(value lnwire.MilliSatoshi,
			strength int) {

			if value <= reserved {
				return
			}

			value -= reserved
			if value < minimum || value > amt {
				return
			}

			breakpoints = append(breakpoints, breakpoint{
				value:    value,
				strength: strength,
			})
		}

		if belief.lowerOK > 0 {
			addBreakpoint(belief.lowerOK*15/16, 4)
		}
		if belief.estimate > 0 {
			addBreakpoint(belief.estimate*4/5, 2)
		}
		if belief.upperFail > 1 {
			addBreakpoint(belief.upperFail*3/4, 3)
			addBreakpoint(belief.upperFail/2, 2)
		}
	}

	sort.Slice(breakpoints, func(i, j int) bool {
		if breakpoints[i].strength != breakpoints[j].strength {
			return breakpoints[i].strength >
				breakpoints[j].strength
		}

		return breakpoints[i].value > breakpoints[j].value
	})

	for _, point := range breakpoints {
		if len(values) >= maxAmountChoices*2 {
			break
		}

		addCandidate(
			&values, seen, point.value, minimum, amt,
		)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	if len(values) <= maxAmountChoices {
		return values
	}

	trimmed := make([]lnwire.MilliSatoshi, 0, maxAmountChoices)
	selected := make(map[lnwire.MilliSatoshi]bool)

	keep := func(value lnwire.MilliSatoshi) {
		if len(trimmed) >= maxAmountChoices || selected[value] {
			return
		}

		selected[value] = true
		trimmed = append(trimmed, value)
	}

	keep(amt)
	keep(minimum)

	step := float64(len(values)-1) /
		float64(maxAmountChoices-1)
	for i := 0; i < maxAmountChoices; i++ {
		index := int(math.Round(float64(i) * step))
		if index >= len(values) {
			index = len(values) - 1
		}
		keep(values[index])
	}

	for _, value := range values {
		keep(value)
	}

	sort.Slice(trimmed, func(i, j int) bool {
		return trimmed[i] > trimmed[j]
	})

	return trimmed
}

func (r *candidateRouter) reserveChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		r.reserved[key] += choice.amounts[i]
	}
}

func (r *candidateRouter) releaseChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		reserved := r.reserved[key]
		if reserved <= choice.amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - choice.amounts[i]
		}
	}
}

func routeOverlap(first, second *routeChoice) float64 {
	if first == nil || second == nil || len(first.keys) == 0 {
		return 0
	}

	used := make(map[edgeKey]bool, len(first.keys))
	for _, key := range first.keys {
		used[key] = true
	}

	overlap := 0
	for _, key := range second.keys {
		if used[key] {
			overlap++
		}
	}

	return float64(overlap) / float64(len(first.keys))
}

func ceilDivMSat(value lnwire.MilliSatoshi,
	divisor uint32) lnwire.MilliSatoshi {

	if divisor <= 1 {
		return value
	}

	d := lnwire.MilliSatoshi(divisor)
	return (value + d - 1) / d
}

func (r *candidateRouter) scoreChoice(choice *routeChoice,
	remaining lnwire.MilliSatoshi, partsLeft uint32) float64 {

	shardFraction := float64(choice.deliver) / float64(remaining)
	if shardFraction <= 0 {
		return math.Inf(1)
	}

	risk := -math.Log(choice.probability)
	feeCost := float64(choice.fee) / 2_500_000

	// Normalize risk by useful progress. This strongly prefers a reliable
	// unequal shard over repeatedly probing an unreliable full amount.
	score := (risk+0.09)/shardFraction + feeCost

	estimatedParts := math.Ceil(
		float64(remaining) / float64(choice.deliver),
	)
	if estimatedParts > float64(partsLeft) {
		score += 2.0 * (
			estimatedParts - float64(partsLeft),
		)
	} else {
		score += 0.025 * (estimatedParts - 1)
	}

	remainder := remaining - choice.deliver
	if remainder <= 0 || partsLeft <= 1 {
		return score
	}

	// Reserve the first corridor while examining the next required shard.
	// This turns reservations into a bounded two-stage route-set planner.
	r.reserveChoice(choice)
	defer r.releaseChoice(choice)

	nextAmount := ceilDivMSat(remainder, partsLeft-1)
	next, err := r.findRoute(nextAmount)
	if err != nil {
		return score + 2.5
	}

	nextRisk := -math.Log(next.probability)
	score += 0.45 * nextRisk
	score += 0.30 * routeOverlap(choice, next)
	score += float64(next.fee) / 6_000_000

	covered := choice.deliver + next.deliver
	if covered > remaining {
		covered = remaining
	}
	coverage := float64(covered) / float64(remaining)
	score -= 0.12 * coverage

	return score
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxRouteAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		choice.utility = r.scoreChoice(
			choice, amt, partsLeft,
		)
		if best == nil || choice.utility < best.utility {
			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.reserveChoice(best)
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	depletedEstimate := amt / 4
	if belief.estimate == 0 ||
		belief.estimate >= amt {

		belief.estimate = depletedEstimate
	} else {
		belief.estimate = (
			3*belief.estimate + depletedEstimate,
		) / 4
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnProbeSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	optimistic := edge.capacity * 17 / 20
	evidenceEstimate := (amt + optimistic) / 2
	if evidenceEstimate > edge.capacity {
		evidenceEstimate = edge.capacity
	}
	if belief.estimate < evidenceEstimate {
		belief.estimate = evidenceEstimate
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}

	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func failureEdgeIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	r.lastFailedAmt = delivered

	failIndex := failureEdgeIndex(
		rt, result.FailureSource,
	)
	if failIndex < 0 || failIndex >= len(keys) {
		return nil
	}

	// Every channel before the reported failure carried the HTLC. Since
	// the attempt failed, this is availability evidence without a balance
	// shift.
	for i := 0; i < failIndex; i++ {
		r.learnProbeSuccess(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	r.edgeFailures[key]++

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.edgeFailures[key]++
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
		r.edgeFailures[key] += 3
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	maxAttempts    = 72
	minShardAmount = lnwire.MilliSatoshi(1_000)
	maxAmountTests = 30
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs      map[edgeKey]liquidityBelief
	reserved     map[edgeKey]lnwire.MilliSatoshi
	paymentUpper map[edgeKey]lnwire.MilliSatoshi
	failures     map[edgeKey]uint32
	broken       map[edgeKey]bool

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		paymentUpper:  make(map[edgeKey]lnwire.MilliSatoshi),
		failures:      make(map[edgeKey]uint32),
		broken:        make(map[edgeKey]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	nodes := []route.Vertex{source}

	for len(nodes) > 0 {
		node := nodes[0]
		nodes = nodes[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					nodes = append(nodes, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, exists := r.edges[key]; exists {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, exists := sharedBeliefs.values[key]
		if !exists {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.51 * math.Exp(-20*x)
	highMode := 0.48 / (1 + math.Exp(24*(x-0.87)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := math.Max(1, float64(edge.capacity)*0.07)
	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))

	confidence := math.Min(0.86, 0.17*float64(belief.samples))
	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

func (r *candidateRouter) freshlyImpossible(edge *candidateEdge,
	amt lnwire.MilliSatoshi) bool {

	upper := r.paymentUpper[edge.key]
	return upper > 0 && amt+r.reserved[edge.key] >= upper
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
	utility     float64
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, exists := score[item.node]
		if !exists || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(item.amt) {
				continue
			}
			if r.freshlyImpossible(edge, item.amt) {
				continue
			}

			total := item.amt + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			// Liquidity probability is the primary path cost. Failure
			// history encourages another corridor without permanently
			// excluding lower-amount retries.
			step := -math.Log(probability) +
				float64(edgeFee)/5_000_000 +
				0.012 +
				0.24*float64(r.failures[edge.key])

			candidate := item.score + step
			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, exists := next[r.source]; !exists {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(r.edges[key], amounts[i])
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, exists := next[node]
		if !exists {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func amountDistance(a, b lnwire.MilliSatoshi) float64 {
	if a <= 0 || b <= 0 {
		return math.Inf(1)
	}

	return math.Abs(math.Log(float64(a) / float64(b)))
}

func (r *candidateRouter) candidateAmounts(
	amt lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	attemptsLeft := maxAttempts - r.attempts
	if attemptsLeft == 0 {
		return nil
	}

	// MaxParts limits concurrent shards, not the total number of sequential
	// shards. The minimum is therefore set by the remaining attempt budget,
	// rather than by amt divided by the currently available MPP slots.
	minimum := (amt + lnwire.MilliSatoshi(attemptsLeft) - 1) /
		lnwire.MilliSatoshi(attemptsLeft)
	if minimum < minShardAmount {
		minimum = minShardAmount
	}
	if minimum > amt {
		minimum = amt
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, maxAmountTests+16)

	for _, fraction := range [][2]int64{
		{1, 1},
		{7, 8},
		{3, 4},
		{2, 3},
		{3, 5},
		{1, 2},
		{2, 5},
		{1, 3},
		{1, 4},
		{1, 5},
		{1, 6},
		{1, 8},
		{1, 12},
		{1, 16},
	} {
		addAmount(
			&values, seen,
			amt*lnwire.MilliSatoshi(fraction[0])/
				lnwire.MilliSatoshi(fraction[1]),
			minimum, amt,
		)
	}

	addAmount(&values, seen, minimum, minimum, amt)
	addAmount(&values, seen, minimum*5/4, minimum, amt)
	addAmount(&values, seen, minimum*3/2, minimum, amt)
	addAmount(&values, seen, minimum*2, minimum, amt)

	if r.lastFailedAmt > 0 {
		for _, fraction := range [][2]int64{
			{9, 10},
			{4, 5},
			{3, 4},
			{2, 3},
			{1, 2},
			{1, 3},
			{1, 4},
		} {
			addAmount(
				&values, seen,
				r.lastFailedAmt*
					lnwire.MilliSatoshi(fraction[0])/
					lnwire.MilliSatoshi(fraction[1]),
				minimum, amt,
			)
		}
	}

	var evidence []lnwire.MilliSatoshi
	for key, upper := range r.paymentUpper {
		if r.broken[key] || upper <= 1 {
			continue
		}

		evidence = append(
			evidence,
			upper-1,
			upper*9/10,
			upper*4/5,
			upper*2/3,
			upper/2,
		)
	}

	for key, belief := range r.beliefs {
		if r.broken[key] {
			continue
		}

		if belief.lowerOK > 0 {
			evidence = append(
				evidence,
				belief.lowerOK,
				belief.lowerOK*9/10,
				belief.lowerOK*3/4,
			)
		}
		if belief.upperFail > 1 {
			evidence = append(
				evidence,
				belief.upperFail-1,
				belief.upperFail*9/10,
				belief.upperFail*3/4,
				belief.upperFail/2,
			)
		}
		if belief.samples > 0 && belief.estimate > 0 {
			evidence = append(
				evidence,
				belief.estimate,
				belief.estimate*4/5,
			)
		}
	}

	// Evidence nearest the current amount or the last failed amount is most
	// likely to describe a useful bottleneck for this request.
	pivot := amt
	if r.lastFailedAmt > 0 && r.lastFailedAmt < pivot {
		pivot = r.lastFailedAmt
	}
	sort.Slice(evidence, func(i, j int) bool {
		di := amountDistance(evidence[i], pivot)
		dj := amountDistance(evidence[j], pivot)
		if di == dj {
			return evidence[i] > evidence[j]
		}

		return di < dj
	})
	if len(evidence) > 16 {
		evidence = evidence[:16]
	}

	for _, value := range evidence {
		addAmount(&values, seen, value, minimum, amt)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	if len(values) <= maxAmountTests {
		return values
	}

	// Preserve candidates across the full size range instead of truncating
	// only the smallest or largest shards.
	selected := make([]lnwire.MilliSatoshi, 0, maxAmountTests)
	selectedSeen := make(map[lnwire.MilliSatoshi]bool)
	for i := 0; i < maxAmountTests; i++ {
		position := i * (len(values) - 1) / (maxAmountTests - 1)
		value := values[position]
		if selectedSeen[value] {
			continue
		}

		selectedSeen[value] = true
		selected = append(selected, value)
	}

	return selected
}

func (r *candidateRouter) reserveChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		r.reserved[key] += choice.amounts[i]
	}
}

func choiceUtility(choice *routeChoice,
	remaining lnwire.MilliSatoshi) float64 {

	probability := math.Max(choice.probability, 0.005)
	progress := float64(choice.deliver) / float64(remaining)
	progress = math.Max(progress, 1e-9)

	retryCost := 1/probability - 1
	if retryCost > 14 {
		retryCost = 14
	}

	// The fixed cost prevents reliable dust shards from consuming the attempt
	// budget. Dividing by progress favors useful delivery while retaining a
	// strong reliability preference for large, uncertain payments.
	cost := 0.24 -
		math.Log(probability) +
		0.08*retryCost +
		float64(choice.fee)/5_000_000 +
		0.008*float64(len(choice.keys))

	return cost / math.Pow(progress, 0.72)
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	amounts := r.candidateAmounts(amt)
	var best *routeChoice

	for _, shard := range amounts {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		choice.utility = choiceUtility(choice, amt)

		// Reservations from actual in-flight HTLCs already make concurrent
		// requests select complementary corridors. Prefer the candidate with
		// the best reliability-adjusted delivered progress.
		if best == nil || choice.utility < best.utility ||
			(choice.utility == best.utility &&
				choice.deliver > best.deliver) {

			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.reserveChoice(best)
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	fresh := r.paymentUpper[key]
	if fresh == 0 || amt < fresh {
		r.paymentUpper[key] = amt
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	lowEstimate := amt / 5
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = lowEstimate
	} else {
		belief.estimate = (3*belief.estimate + lowEstimate) / 4
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnProbeSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.estimate < amt {
		belief.estimate = amt
	}

	optimistic := edge.capacity * 4 / 5
	if belief.estimate < optimistic {
		belief.estimate = (belief.estimate + optimistic) / 2
	}
	if belief.upperFail > 0 && belief.upperFail <= belief.lowerOK {
		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	if belief.upperFail > 0 &&
		belief.lowerOK >= belief.upperFail {

		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}
	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) releaseRoute(keys []edgeKey,
	amounts []lnwire.MilliSatoshi) {

	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	r.releaseRoute(keys, amounts)

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.failures[key] > 0 {
				r.failures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		// A forwarding node reports a failure for its outgoing edge.
		for i := 0; i+1 < len(rt.Hops); i++ {
			if rt.Hops[i].PubKeyBytes ==
				result.FailureSource {

				failIndex = i + 1
				break
			}
		}
	}

	r.lastFailedAmt = rt.Hops[len(rt.Hops)-1].AmtToForward

	if failIndex < 0 || failIndex >= len(keys) {
		for _, key := range keys {
			r.failures[key]++
		}

		return nil
	}

	for i := 0; i < failIndex; i++ {
		r.learnProbeSuccess(keys[i], amounts[i])
		if r.failures[keys[i]] > 0 {
			r.failures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	r.failures[key] += 2

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta   = 40
	maxRouteAttempts = 48
	maxShardChoices  = 36
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
	failures  uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type attemptKey struct {
	amount lnwire.MilliSatoshi
	hash   uint64
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved     map[edgeKey]lnwire.MilliSatoshi
	edgeFailures map[edgeKey]uint32
	broken       map[edgeKey]bool
	attempted    map[attemptKey]uint32

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:  make(map[edgeKey]uint32),
		broken:        make(map[edgeKey]bool),
		attempted:     make(map[attemptKey]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity * 4 / 5
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.003:
		return 0.003
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.003
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-20*x)
	highMode := 0.495 / (1 + math.Exp(24*(x-0.90)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.003
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.003
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := float64(edge.capacity) * 0.08
	if scale < 1 {
		scale = 1
	}
	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))

	confidence := math.Min(0.82, 0.18*float64(belief.samples))
	probability := (1-confidence)*prior + confidence*point

	// A liquidity failure is evidence for the depleted bimodal state even
	// below the exact failed amount. Smaller probes remain possible, but
	// competing unexplored corridors are preferred.
	if belief.failures > 0 && belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 1 {
			ratio = 1
		}

		factor := 0.10 + 0.72*math.Exp(-5*ratio)
		factor /= 1 + 0.20*float64(belief.failures-1)
		probability *= factor
	}

	return clampProbability(probability)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(item.amt) {
				continue
			}

			total := item.amt + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			// Reliability dominates fees. Only the edge proven to fail is
			// penalized, since upstream edges successfully carried a failed
			// attempt far enough to receive the downstream error.
			step := -math.Log(probability) +
				float64(edgeFee)/2_500_000 +
				0.012 +
				0.70*float64(r.edgeFailures[edge.key])
			candidate := item.score + step

			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(r.edges[key], amounts[i])
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	base := make([]lnwire.MilliSatoshi, 0, 16)
	addCandidate(&base, seen, amt, minimum, amt)
	addCandidate(&base, seen, amt*4/5, minimum, amt)
	addCandidate(&base, seen, amt*3/4, minimum, amt)
	addCandidate(&base, seen, amt*2/3, minimum, amt)
	addCandidate(&base, seen, amt/2, minimum, amt)
	addCandidate(&base, seen, amt/3, minimum, amt)
	addCandidate(&base, seen, minimum*2, minimum, amt)
	addCandidate(&base, seen, minimum*3/2, minimum, amt)
	addCandidate(&base, seen, minimum, minimum, amt)

	if r.lastFailedAmt > 0 {
		addCandidate(
			&base, seen, r.lastFailedAmt*3/4, minimum, amt,
		)
		addCandidate(
			&base, seen, r.lastFailedAmt/2, minimum, amt,
		)
		addCandidate(
			&base, seen, r.lastFailedAmt/3, minimum, amt,
		)
	}

	// Known bounds and estimated corridor sizes create unequal split
	// candidates. Complements let one shard leave exactly enough for a
	// differently sized parallel corridor.
	var breakpoints []lnwire.MilliSatoshi
	for key, edge := range r.edges {
		if r.broken[key] {
			continue
		}

		belief := r.beliefs[key]
		candidates := []lnwire.MilliSatoshi{
			edge.capacity * 4 / 5,
			edge.capacity * 2 / 3,
		}
		if belief.lowerOK > 0 {
			candidates = append(candidates, belief.lowerOK)
		}
		if belief.estimate > 0 {
			candidates = append(
				candidates, belief.estimate*4/5,
			)
		}
		if belief.upperFail > 1 {
			candidates = append(
				candidates,
				belief.upperFail*3/4,
				belief.upperFail/2,
			)
		}

		for _, value := range candidates {
			if value >= minimum && value <= amt {
				breakpoints = append(breakpoints, value)
			}

			complement := amt - value
			if complement >= minimum && complement <= amt {
				breakpoints = append(
					breakpoints, complement,
				)
			}
		}
	}

	sort.Slice(breakpoints, func(i, j int) bool {
		return breakpoints[i] < breakpoints[j]
	})

	// Uniformly sample a bounded set of breakpoints so both small and large
	// unequal corridors remain represented.
	limit := maxShardChoices - len(base)
	if limit < 0 {
		limit = 0
	}
	if len(breakpoints) <= limit {
		for _, value := range breakpoints {
			addCandidate(&base, seen, value, minimum, amt)
		}
	} else if limit > 0 {
		for i := 0; i < limit; i++ {
			index := i * (len(breakpoints) - 1)
			if limit > 1 {
				index /= limit - 1
			}
			addCandidate(
				&base, seen, breakpoints[index],
				minimum, amt,
			)
		}
	}

	sort.Slice(base, func(i, j int) bool {
		return base[i] > base[j]
	})

	return base
}

func routeHash(keys []edgeKey) uint64 {
	const (
		offset = uint64(1469598103934665603)
		prime  = uint64(1099511628211)
	)

	hash := offset
	for _, key := range keys {
		hash ^= key.chanID
		hash *= prime
		for _, value := range key.from {
			hash ^= uint64(value)
			hash *= prime
		}
		for _, value := range key.to {
			hash ^= uint64(value)
			hash *= prime
		}
	}

	return hash
}

func (r *candidateRouter) reserveChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		r.reserved[key] += choice.amounts[i]
	}
}

func (r *candidateRouter) releaseChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		reserved := r.reserved[key]
		if reserved <= choice.amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - choice.amounts[i]
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxRouteAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		shardsNeeded := float64(amt) / float64(shard)
		choice.utility = -math.Log(choice.probability) +
			0.24*math.Log(shardsNeeded) +
			float64(choice.fee)/2_500_000

		key := attemptKey{
			amount: shard,
			hash:   routeHash(choice.keys),
		}
		choice.utility += 3.5 * float64(r.attempted[key])

		// Look one shard ahead while the first route is reserved. This
		// favors unequal route sets whose remaining amount still fits a
		// parallel corridor instead of selecting each shard independently.
		remaining := amt - shard
		if remaining > 0 && partsLeft > 1 {
			r.reserveChoice(choice)

			nextMinimum := (remaining +
				lnwire.MilliSatoshi(partsLeft-1) - 1) /
				lnwire.MilliSatoshi(partsLeft-1)
			nextChoice, nextErr := r.findRoute(nextMinimum)

			r.releaseChoice(choice)

			if nextErr != nil {
				choice.utility += 8
			} else {
				choice.utility += 0.35 *
					-math.Log(nextChoice.probability)
				choice.utility += float64(nextChoice.fee) /
					7_500_000
			}
		}

		if best == nil || choice.utility < best.utility {
			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.reserveChoice(best)
	r.attempted[attemptKey{
		amount: best.deliver,
		hash:   routeHash(best.keys),
	}]++
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	depletedEstimate := amt / 5
	if belief.estimate == 0 || belief.estimate > depletedEstimate {
		belief.estimate = depletedEstimate
	} else {
		belief.estimate =
			(3*belief.estimate + depletedEstimate) / 4
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}

	belief.samples++
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnProbeSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	optimistic := edge.capacity * 9 / 10
	if belief.estimate < amt {
		belief.estimate = amt
	}
	if belief.estimate < optimistic {
		belief.estimate =
			(belief.estimate + optimistic) / 2
	}

	if belief.upperFail > 0 && belief.upperFail <= belief.lowerOK {
		belief.upperFail = 0
	}
	if belief.failures > 0 {
		belief.failures--
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSettlement(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	estimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if estimate < optimistic {
		estimate = (estimate + optimistic) / 2
	}

	// A settlement transfers liquidity away from this direction.
	belief.estimate = subtractFloor(estimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	if belief.failures > 0 {
		belief.failures--
	}
	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}
	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}
	if reverseBelief.failures > 0 {
		reverseBelief.failures--
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSettlement(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	r.lastFailedAmt = rt.Hops[len(rt.Hops)-1].AmtToForward

	if failIndex < 0 || failIndex >= len(keys) {
		return nil
	}

	// Every edge before the failing outgoing edge successfully forwarded
	// this probe. Record that positive evidence without shifting liquidity,
	// because the failed HTLC is rolled back.
	for i := 0; i < failIndex; i++ {
		r.learnProbeSuccess(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	r.edgeFailures[key]++

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta     = 40
	maxRouteAttempts   = 48
	maxAmountChoices   = 22
	maxRouteChoices    = 4
	maxPlannedChoices  = 14
	minShardAmountMsat = 1_000
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key           edgeKey
	capacity      lnwire.MilliSatoshi
	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
	failures  uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type attemptKey struct {
	amount lnwire.MilliSatoshi
	hash   uint64
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved      map[edgeKey]lnwire.MilliSatoshi
	edgeFailures  map[edgeKey]uint32
	policyBroken  map[edgeKey]bool
	attempted     map[attemptKey]uint32
	pathFailures  map[uint64]uint32
	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:  make(map[edgeKey]uint32),
		policyBroken:  make(map[edgeKey]bool),
		attempted:     make(map[attemptKey]uint32),
		pathFailures:  make(map[uint64]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity * 4 / 5
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.004:
		return 0.004
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.004
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-20*x)
	highMode := 0.495 / (1 + math.Exp(24*(x-0.90)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.004
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}
		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.004
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := float64(edge.capacity) * 0.075
	if scale < 1 {
		scale = 1
	}
	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))

	confidence := math.Min(0.84, 0.17*float64(belief.samples))
	probability := (1-confidence)*prior + confidence*point

	if belief.failures > 0 && belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 1 {
			ratio = 1
		}

		factor := 0.08 + 0.82*math.Exp(-5.5*ratio)
		factor /= 1 + 0.16*float64(belief.failures-1)
		probability *= factor
	}

	return clampProbability(probability)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	cost        float64
	utility     float64
	hash        uint64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(deliver lnwire.MilliSatoshi,
	extraPenalty map[edgeKey]float64) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)
	pq := &dijkstraQueue{}

	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.policyBroken[edge.key] || !edge.usable(item.amt) {
				continue
			}

			total := item.amt + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			step := -math.Log(probability) +
				float64(edgeFee)/3_000_000 +
				0.010 +
				0.48*float64(r.edgeFailures[edge.key]) +
				extraPenalty[edge.key]
			candidate := item.score + step

			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(r.edges[key], amounts[i])
	}

	hash := routeHash(keys)
	cost := -math.Log(probability) +
		float64(rt.TotalAmount-deliver)/3_000_000 +
		0.055*float64(len(keys)) +
		0.90*float64(r.pathFailures[hash])

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		cost:        cost,
		hash:        hash,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) findRouteChoices(
	deliver lnwire.MilliSatoshi) []*routeChoice {

	first, err := r.findRoute(deliver, nil)
	if err != nil {
		return nil
	}

	choices := []*routeChoice{first}
	seen := map[uint64]bool{first.hash: true}
	frontier := []*routeChoice{first}

	for len(frontier) > 0 && len(choices) < maxRouteChoices {
		parent := frontier[0]
		frontier = frontier[1:]

		for _, key := range parent.keys {
			penalty := map[edgeKey]float64{key: 5}
			alternative, err := r.findRoute(deliver, penalty)
			if err != nil || seen[alternative.hash] {
				continue
			}

			seen[alternative.hash] = true
			choices = append(choices, alternative)
			frontier = append(frontier, alternative)
			if len(choices) >= maxRouteChoices {
				break
			}
		}
	}

	sort.Slice(choices, func(i, j int) bool {
		return choices[i].cost < choices[j].cost
	})
	return choices
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < minShardAmountMsat {
		minimum = minShardAmountMsat
	}
	if minimum > amt {
		minimum = amt
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, maxAmountChoices)

	for _, value := range []lnwire.MilliSatoshi{
		amt,
		amt * 7 / 8,
		amt * 4 / 5,
		amt * 3 / 4,
		amt * 2 / 3,
		amt * 3 / 5,
		amt / 2,
		amt * 2 / 5,
		amt / 3,
		minimum * 2,
		minimum * 3 / 2,
		minimum,
	} {
		addCandidate(&values, seen, value, minimum, amt)
	}

	if r.lastFailedAmt > 0 {
		for _, value := range []lnwire.MilliSatoshi{
			r.lastFailedAmt * 4 / 5,
			r.lastFailedAmt * 2 / 3,
			r.lastFailedAmt / 2,
			r.lastFailedAmt / 3,
			amt - r.lastFailedAmt/2,
		} {
			addCandidate(&values, seen, value, minimum, amt)
		}
	}

	var breakpoints []lnwire.MilliSatoshi
	for key, edge := range r.edges {
		if r.policyBroken[key] {
			continue
		}

		belief := r.beliefs[key]
		limits := []lnwire.MilliSatoshi{
			edge.capacity * 9 / 10,
			edge.capacity * 4 / 5,
			edge.capacity * 2 / 3,
		}
		if belief.lowerOK > 0 {
			limits = append(limits, belief.lowerOK)
		}
		if belief.estimate > 0 {
			limits = append(
				limits,
				belief.estimate,
				belief.estimate*4/5,
			)
		}
		if belief.upperFail > 1 {
			limits = append(
				limits,
				belief.upperFail-1,
				belief.upperFail*3/4,
				belief.upperFail/2,
			)
		}

		for _, value := range limits {
			if value >= minimum && value <= amt {
				breakpoints = append(breakpoints, value)
			}

			complement := amt - value
			if complement >= minimum && complement <= amt {
				breakpoints = append(breakpoints, complement)
			}
		}
	}

	sort.Slice(breakpoints, func(i, j int) bool {
		return breakpoints[i] < breakpoints[j]
	})

	remainingSlots := maxAmountChoices - len(values)
	if remainingSlots > 0 && len(breakpoints) > 0 {
		for i := 0; i < remainingSlots; i++ {
			index := i * (len(breakpoints) - 1)
			if remainingSlots > 1 {
				index /= remainingSlots - 1
			}
			addCandidate(
				&values, seen, breakpoints[index],
				minimum, amt,
			)
		}
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})
	return values
}

func routeHash(keys []edgeKey) uint64 {
	const (
		offset = uint64(1469598103934665603)
		prime  = uint64(1099511628211)
	)

	hash := offset
	for _, key := range keys {
		hash ^= key.chanID
		hash *= prime
		for _, value := range key.from {
			hash ^= uint64(value)
			hash *= prime
		}
		for _, value := range key.to {
			hash ^= uint64(value)
			hash *= prime
		}
	}
	return hash
}

func (r *candidateRouter) reserveChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		r.reserved[key] += choice.amounts[i]
	}
}

func (r *candidateRouter) releaseChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		reserved := r.reserved[key]
		if reserved <= choice.amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - choice.amounts[i]
		}
	}
}

func (r *candidateRouter) bestImmediateChoice(
	amt lnwire.MilliSatoshi, partsLeft uint32) *routeChoice {

	var best *routeChoice
	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		for _, choice := range r.findRouteChoices(shard) {
			needed := float64(amt) / float64(shard)
			choice.utility = choice.cost +
				0.16*math.Log(needed) +
				3.2*float64(r.attempted[attemptKey{
					amount: shard,
					hash:   choice.hash,
				}])

			if best == nil || choice.utility < best.utility {
				best = choice
			}
		}
	}
	return best
}

func (r *candidateRouter) completionCost(first *routeChoice,
	remaining lnwire.MilliSatoshi, slots uint32) float64 {

	cost := first.cost + 0.11
	r.reserveChoice(first)
	reserved := []*routeChoice{first}

	defer func() {
		for i := len(reserved) - 1; i >= 0; i-- {
			r.releaseChoice(reserved[i])
		}
	}()

	originalRemaining := remaining
	for remaining > 0 && slots > 0 {
		choice := r.bestImmediateChoice(remaining, slots)
		if choice == nil {
			break
		}

		progress := float64(choice.deliver) / float64(remaining)
		cost += choice.cost + 0.11 + 0.20*(1-progress)

		r.reserveChoice(choice)
		reserved = append(reserved, choice)
		remaining -= choice.deliver
		slots--
	}

	if remaining > 0 {
		fraction := float64(remaining) /
			float64(originalRemaining+first.deliver)
		cost += 18 + 12*fraction
	}

	return cost
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxRouteAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var candidates []*routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		for _, choice := range r.findRouteChoices(shard) {
			choice.utility = choice.cost +
				3.2*float64(r.attempted[attemptKey{
					amount: shard,
					hash:   choice.hash,
				}])
			candidates = append(candidates, choice)
		}
	}

	if len(candidates) == 0 {
		return nil, errors.New("no route found")
	}

	sort.Slice(candidates, func(i, j int) bool {
		return candidates[i].utility < candidates[j].utility
	})
	if len(candidates) > maxPlannedChoices {
		candidates = candidates[:maxPlannedChoices]
	}

	var best *routeChoice
	bestPlan := math.Inf(1)

	for _, choice := range candidates {
		remaining := amt - choice.deliver
		planCost := choice.utility

		if remaining > 0 {
			if partsLeft <= 1 {
				continue
			}

			planCost = r.completionCost(
				choice, remaining, partsLeft-1,
			)
			planCost += 3.2 * float64(r.attempted[attemptKey{
				amount: choice.deliver,
				hash:   choice.hash,
			}])
		}

		if planCost < bestPlan {
			bestPlan = planCost
			best = choice
		}
	}

	if best == nil {
		best = candidates[0]
	}

	r.reserveChoice(best)
	r.attempted[attemptKey{
		amount: best.deliver,
		hash:   best.hash,
	}]++
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	depletedEstimate := amt / 5
	if belief.estimate == 0 || belief.estimate > depletedEstimate {
		belief.estimate = depletedEstimate
	} else {
		belief.estimate =
			(3*belief.estimate + depletedEstimate) / 4
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}

	belief.samples++
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnProbeSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	optimistic := edge.capacity * 9 / 10
	if belief.estimate < amt {
		belief.estimate = amt
	}
	if belief.estimate < optimistic {
		belief.estimate =
			(belief.estimate + optimistic) / 2
	}

	if belief.upperFail > 0 && belief.upperFail <= belief.lowerOK {
		belief.upperFail = 0
	}
	if belief.failures > 0 {
		belief.failures--
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}
	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}
	return b
}

func (r *candidateRouter) learnSettlement(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	estimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if estimate < optimistic {
		estimate = (estimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(estimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	if belief.failures > 0 {
		belief.failures--
	}
	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}
	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}
	if reverseBelief.failures > 0 {
		reverseBelief.failures--
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}

	hash := routeHash(keys)
	if result.Failure == nil {
		for i, key := range keys {
			r.learnSettlement(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		if r.pathFailures[hash] > 0 {
			r.pathFailures[hash]--
		}
		r.lastFailedAmt = 0
		return nil
	}

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	r.lastFailedAmt = rt.Hops[len(rt.Hops)-1].AmtToForward

	if failIndex < 0 || failIndex >= len(keys) {
		r.pathFailures[hash]++
		for _, key := range keys {
			r.edgeFailures[key]++
		}
		return nil
	}

	for i := 0; i < failIndex; i++ {
		r.learnProbeSuccess(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	r.edgeFailures[key]++
	r.pathFailures[hash]++

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBroken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta    = uint32(40)
	riskCostMsat      = 300000.0
	minProbability    = 0.003
	maxProbability    = 0.995
	lowerRetryFactor  = 0.66
	maxShardChoices   = 80
	maxCorridors      = 10
	diversityPenalty  = 4 * riskCostMsat
	unknownFailPenalty = riskCostMsat
)

type edgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief
	blocked       map[edgeKey]bool
	reserved      map[edgeKey]lnwire.MilliSatoshi
	penalties     map[edgeKey]float64
	failures      map[edgeKey]uint32

	lastRemaining  lnwire.MilliSatoshi
	failureCeiling lnwire.MilliSatoshi
	failStreak     uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		blocked:       make(map[edgeKey]bool),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		penalties:     make(map[edgeKey]float64),
		failures:      make(map[edgeKey]uint32),
		lastRemaining: spec.Amount,
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, ok := r.edgeByKey[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}
	return (a + b - 1) / b
}

func clampAmount(amt, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if amt < 0 {
		return 0
	}
	if amt > capacity {
		return capacity
	}
	return amt
}

func clampProbability(p float64) float64 {
	if p < minProbability {
		return minProbability
	}
	if p > maxProbability {
		return maxProbability
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-x/0.025)
	highMode := 0.48 / (1 + math.Exp(14*(x-0.78)))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) availableLocal(key edgeKey) lnwire.MilliSatoshi {
	available := r.localBalances[key.chanID]
	reserved := r.reserved[key]
	if reserved >= available {
		return 0
	}
	return available - reserved
}

func (r *candidateRouter) availableCapacity(
	edge *candidateEdge) lnwire.MilliSatoshi {

	available := edge.capacity
	if reserved := r.reserved[edge.key]; reserved >= available {
		return 0
	} else {
		available -= reserved
	}

	if edge.key.from == r.source {
		local := r.availableLocal(edge.key)
		if local < available {
			available = local
		}
		return available
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && belief.upperBad-1 < available {
		available = belief.upperBad - 1
	}

	return clampAmount(available, edge.capacity)
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if amt > r.availableLocal(edge.key) {
			return minProbability
		}
		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		return minProbability
	}
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.06, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(belief.estimate))/width,
	))

	weight := 0.50
	if belief.lowerOK != 0 || belief.upperBad != 0 {
		weight = 0.67
	}

	return clampProbability((1-weight)*prior + weight*point)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extra map[edgeKey]float64) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := dist[item.node]
		if !ok || item.score > best ||
			item.arriving != required[item.node] {

			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) ||
				amtOver > r.availableCapacity(edge) {

				continue
			}

			probability := r.probability(edge, amtOver)
			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			}

			score := item.score + float64(fee) +
				-math.Log(probability)*riskCostMsat +
				r.penalties[edge.key] + extra[edge.key] + 250

			old, exists := dist[edge.key.from]
			if exists && score >= old {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edgeByKey) {
			return nil, errors.New("route contains a cycle")
		}
	}

	return r.buildRoute(amt, path)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		if !edge.usable(amtOver[i]) ||
			amtOver[i] > r.availableCapacity(edge) {

			return nil, errors.New("path cannot carry amount")
		}

		forward := amt
		expiry := finalCltvDelta
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routePath(
	rt *route.Route) ([]*candidateEdge, bool) {

	path := make([]*candidateEdge, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeByKey[key]
		if edge == nil {
			return nil, false
		}

		path[i] = edge
		from = hop.PubKeyBytes
	}

	return path, true
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (edgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return edgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := edgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, ok := r.edgeByKey[key]
	return key, ok
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.reserved[key] += routeAmount(rt, i)
		}
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func (r *candidateRouter) fixedRouteLimit(path []*candidateEdge,
	known lnwire.MilliSatoshi,
	maximum lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if known <= 0 || known > maximum {
		return 0
	}
	if _, err := r.buildRoute(known, path); err != nil {
		return 0
	}

	low := known
	high := maximum
	for low < high {
		mid := low + (high-low+1)/2
		if _, err := r.buildRoute(mid, path); err == nil {
			low = mid
		} else {
			high = mid - 1
		}
	}

	return low
}

type corridor struct {
	path    []*candidateEdge
	limit   lnwire.MilliSatoshi
	safe    lnwire.MilliSatoshi
	quality float64
}

func (r *candidateRouter) discoverCorridors(amt,
	probe lnwire.MilliSatoshi, count int) []corridor {

	if probe <= 0 {
		probe = 1
	}

	extra := make(map[edgeKey]float64)
	corridors := make([]corridor, 0, count)
	seen := make(map[string]bool)

	for len(corridors) < count {
		rt, err := r.findRoute(probe, extra)
		if err != nil {
			break
		}

		path, ok := r.routePath(rt)
		if !ok {
			break
		}

		signature := ""
		for _, edge := range path {
			signature += fmt.Sprintf(
				"%d:%x;", edge.key.chanID, edge.key.to[:],
			)
		}
		if seen[signature] {
			break
		}
		seen[signature] = true

		limit := r.fixedRouteLimit(path, probe, amt)
		if limit != 0 {
			safe := limit * 4 / 5
			if safe < probe {
				safe = probe
			}
			if safe > limit {
				safe = limit
			}

			corridors = append(corridors, corridor{
				path:    path,
				limit:   limit,
				safe:    safe,
				quality: r.routeQuality(rt),
			})
		}

		for _, edge := range path {
			extra[edge.key] += diversityPenalty
		}
	}

	sort.Slice(corridors, func(i, j int) bool {
		if corridors[i].safe != corridors[j].safe {
			return corridors[i].safe > corridors[j].safe
		}
		return corridors[i].quality < corridors[j].quality
	})

	return corridors
}

func (r *candidateRouter) routeQuality(rt *route.Route) float64 {
	delivered := deliveredAmount(rt)
	if delivered <= 0 {
		return math.Inf(1)
	}

	negativeLogProbability := 0.0
	penalty := 0.0
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			return math.Inf(1)
		}

		edge := r.edgeByKey[key]
		negativeLogProbability -= math.Log(
			r.probability(edge, routeAmount(rt, i)),
		)
		penalty += r.penalties[key] / riskCostMsat
	}

	fee := rt.TotalAmount - delivered
	feeCost := 3000 * float64(fee) / float64(delivered)
	hopCost := 0.006 * float64(len(rt.Hops))

	return negativeLogProbability + penalty + feeCost + hopCost
}

func appendAmount(choices *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool,
	amt, maximum lnwire.MilliSatoshi) {

	if amt <= 0 || amt > maximum || seen[amt] ||
		len(*choices) >= maxShardChoices {

		return
	}

	seen[amt] = true
	*choices = append(*choices, amt)
}

func (r *candidateRouter) genericChoices(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	choices := make([]lnwire.MilliSatoshi, 0, 32)
	seen := make(map[lnwire.MilliSatoshi]bool)

	add := func(candidate lnwire.MilliSatoshi) {
		appendAmount(&choices, seen, candidate, amt)
	}

	add(amt)
	for parts := uint32(2); parts <= partsLeft; parts++ {
		equal := ceilDiv(amt, lnwire.MilliSatoshi(parts))
		add(equal)
		add(equal * 4 / 5)
		add(equal * 2 / 3)
	}

	for _, ratio := range []int64{
		90, 80, 72, 64, 56, 48, 40, 32, 24, 16,
	} {
		add(amt * lnwire.MilliSatoshi(ratio) / 100)
	}

	if r.failureCeiling != 0 {
		add(r.failureCeiling)
		add(r.failureCeiling * 4 / 5)
	}

	for _, belief := range r.beliefs {
		add(belief.lowerOK)
		add(belief.lowerOK * 9 / 10)
		add(belief.estimate * 4 / 5)
		if belief.upperBad > 1 {
			add((belief.upperBad - 1) * 4 / 5)
			add((belief.upperBad - 1) * 2 / 3)
		}
	}

	return choices
}

func (r *candidateRouter) plannedRoutes(amt lnwire.MilliSatoshi,
	partsLeft uint32) []*route.Route {

	if partsLeft == 0 {
		return nil
	}

	equal := ceilDiv(amt, lnwire.MilliSatoshi(partsLeft))
	probe := equal / 3
	if probe <= 0 {
		probe = 1
	}

	count := int(partsLeft) + 3
	if count > maxCorridors {
		count = maxCorridors
	}

	corridors := r.discoverCorridors(amt, probe, count)
	if len(corridors) == 0 && probe != equal {
		corridors = r.discoverCorridors(amt, equal, count)
	}
	if len(corridors) == 0 {
		return nil
	}

	routes := make([]*route.Route, 0, len(corridors)*3)
	for i, corridor := range corridors {
		otherCapacity := lnwire.MilliSatoshi(0)
		used := uint32(0)

		for j, other := range corridors {
			if i == j || used >= partsLeft-1 {
				continue
			}
			otherCapacity += other.safe
			used++
		}

		required := lnwire.MilliSatoshi(1)
		if otherCapacity < amt {
			required = amt - otherCapacity
		}

		candidates := []lnwire.MilliSatoshi{
			corridor.safe,
			corridor.limit * 2 / 3,
			equal,
			required,
		}

		seen := make(map[lnwire.MilliSatoshi]bool)
		for _, shard := range candidates {
			if shard <= 0 || shard > corridor.limit ||
				shard > amt || seen[shard] {

				continue
			}
			seen[shard] = true

			rt, err := r.buildRoute(shard, corridor.path)
			if err == nil {
				routes = append(routes, rt)
			}
		}
	}

	return routes
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts in flight")
	}

	if amt < r.lastRemaining {
		r.failStreak = 0
		r.failureCeiling = 0
	}
	r.lastRemaining = amt

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	if partsLeft == 0 {
		return nil, errors.New("maximum parts in flight")
	}

	var (
		bestRoute   *route.Route
		bestQuality = math.Inf(1)
		lastErr     error
	)

	consider := func(rt *route.Route, planBonus float64) {
		if rt == nil {
			return
		}

		delivered := deliveredAmount(rt)
		if delivered <= 0 || delivered > amt {
			return
		}

		quality := r.routeQuality(rt) - planBonus
		quality -= 0.12 * math.Log1p(
			float64(delivered) / float64(ceilDiv(
				amt, lnwire.MilliSatoshi(partsLeft),
			)),
		)

		if quality < bestQuality {
			bestQuality = quality
			bestRoute = rt
		}
	}

	for _, rt := range r.plannedRoutes(amt, partsLeft) {
		consider(rt, 0.18)
	}

	for _, shard := range r.genericChoices(amt, partsLeft) {
		rt, err := r.findRoute(shard, nil)
		if err != nil {
			lastErr = err
			continue
		}
		consider(rt, 0)
	}

	if bestRoute == nil {
		if lastErr == nil {
			lastErr = errors.New("no route found")
		}
		return nil, lastErr
	}

	r.reserve(bestRoute)
	return bestRoute, nil
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key edgeKey,
	belief liquidityBelief) {

	edge := r.edgeByKey[key]
	if edge != nil {
		belief.lowerOK = clampAmount(
			belief.lowerOK, edge.capacity,
		)
		belief.estimate = clampAmount(
			belief.estimate, edge.capacity,
		)
		if belief.upperBad > edge.capacity {
			belief.upperBad = 0
		}
		if belief.upperBad != 0 &&
			belief.lowerOK >= belief.upperBad {

			belief.lowerOK = 0
		}
	}

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordPass(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	estimate := amt + (edge.capacity-amt)*4/5
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt * 35 / 100
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.estimate < belief.lowerOK {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) settleLiquidity(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil {
		return
	}

	if key.from == r.source {
		balance := r.localBalances[key.chanID]
		if amt >= balance {
			r.localBalances[key.chanID] = 0
		} else {
			r.localBalances[key.chanID] = balance - amt
		}
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK > amt {
		belief.lowerOK -= amt
	} else {
		belief.lowerOK = 0
	}
	if belief.upperBad > amt {
		belief.upperBad -= amt
	} else {
		belief.upperBad = 0
	}
	if belief.estimate > amt {
		belief.estimate -= amt
	} else {
		belief.estimate = 0
	}
	r.saveBelief(key, belief)

	reverseKey := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edgeByKey[reverseKey]
	if reverseEdge == nil || reverseKey.from == r.source {
		return
	}

	reverse := r.beliefs[reverseKey]
	if reverse.lowerOK < amt {
		reverse.lowerOK = amt
	}
	reverse.estimate = clampAmount(
		reverse.estimate+amt, reverseEdge.capacity,
	)
	if reverse.estimate < reverse.lowerOK {
		reverse.estimate = reverse.lowerOK
	}
	if reverse.upperBad != 0 &&
		reverse.upperBad <= reverse.lowerOK {

		reverse.upperBad = 0
	}
	r.saveBelief(reverseKey, reverse)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			amt := routeAmount(rt, i)
			r.recordPass(key, amt)
			r.settleLiquidity(key, amt)
			r.penalties[key] *= 0.20
			r.failures[key] = 0
		}

		r.failStreak = 0
		r.failureCeiling = 0
		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if ok {
				r.penalties[key] += unknownFailPenalty
			}
		}

		r.failStreak++
		if delivered := deliveredAmount(rt); delivered > 0 {
			ceiling := delivered * 3 / 4
			if r.failureCeiling == 0 ||
				ceiling < r.failureCeiling {

				r.failureCeiling = ceiling
			}
		}
		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.recordPass(key, routeAmount(rt, i))
			r.penalties[key] *= 0.70
		}
	}

	key, ok := r.routeEdge(rt, failIndex)
	if !ok {
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	default:
		failedAmount := routeAmount(rt, failIndex)
		r.recordFailure(key, failedAmount)
		r.failures[key]++
		r.penalties[key] += riskCostMsat *
			(1 + 0.35*float64(r.failures[key]-1))
	}

	r.failStreak++
	delivered := deliveredAmount(rt)
	if delivered > 0 {
		ceiling := lnwire.MilliSatoshi(
			float64(delivered) * lowerRetryFactor,
		)
		if ceiling > 0 &&
			(r.failureCeiling == 0 ||
				ceiling < r.failureCeiling) {

			r.failureCeiling = ceiling
		}
	}

	return nil
}
